    { "id": "sd1-12-1", "core": "core1", "domain": "sd1", "objective": "1.2", "term": "Non-repudiation", "definition": "A security property ensuring a party cannot credibly deny having sent a message or performed an action, typically achieved through digital signatures and logging.", "scenario": "prove that a specific employee, and no one else, digitally signed and submitted a financial transaction", "distractors": ["Confidentiality", "Integrity", "Availability"], "tip": "Can't DENY having done it — digital signatures and logging are the mechanisms, distinct from the CIA triad's three goals." , "diagram": "<svg viewBox='0 0 380 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-12-1'><title id='dt-sd1-12-1'>Can&#39;t deny having done it \u2014 digital signatures and logging are the mechanisms, distinct from the CIA triad&#39;s three goals.</title><rect x='30' y='30' width='110' height='34' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='85' y='51' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Sender signs + logs</text><line x1='140' y1='47' x2='234' y2='47' stroke='var(--muted)' stroke-width='1.5'/><path d='M232 43 L239 47 L232 51' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='240' y='30' width='110' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='295' y='51' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Action recorded</text><text x='190' y='90' font-size='7.5' fill='var(--text)' text-anchor='middle'>Sender can&#39;t credibly deny having sent the</text><text x='190' y='102' font-size='7.5' fill='var(--text)' text-anchor='middle'>message or performed the action.</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Can&#39;t deny having done it \u2014 digital signatures and logging are the mechanisms,</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>distinct from the CIA triad&#39;s three goals.</text></svg>"},
    { "id": "sd1-12-2", "core": "core1", "domain": "sd1", "objective": "1.2", "term": "Zero trust", "definition": "A security model that assumes no implicit trust for any user or device, requiring continuous verification for every access request regardless of network location.", "scenario": "require every internal application request to be authenticated and authorized, even from a device already on the corporate network", "distractors": ["Perimeter-based security", "Implicit trust model", "Defense in depth alone"], "tip": "CONTINUOUS verification regardless of location — the opposite of trusting anything already inside the perimeter.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-12-2'><title id='dt-sd1-12-2'>A security model that assumes no implicit trust for any user or device, requiring continuous verification for every access request regardless of network location.</title><text x='90' y='16' font-size='8.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Perimeter model</text><circle cx='90' cy='80' r='60' fill='none' stroke='var(--muted-2)' stroke-width='1.5' stroke-dasharray='4 3'/><text x='90' y='36' font-size='6.5' fill='var(--muted)' text-anchor='middle'>trusted once inside</text><circle cx='60' cy='90' r='9' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><circle cx='110' cy='70' r='9' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><circle cx='95' cy='105' r='9' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='90' y='150' font-size='6.5' fill='var(--red)' text-anchor='middle' font-weight='700'>one breach = free roam</text><line x1='190' y1='20' x2='190' y2='160' stroke='var(--border)' stroke-width='1'/><text x='290' y='16' font-size='8.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Zero trust</text><circle cx='260' cy='90' r='9' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><rect x='245' y='102' width='30' height='12' rx='2' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1'/><text x='260' y='111' font-size='5.5' fill='var(--primary)' text-anchor='middle'>verify</text><circle cx='310' cy='70' r='9' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><rect x='295' y='82' width='30' height='12' rx='2' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1'/><text x='310' y='91' font-size='5.5' fill='var(--primary)' text-anchor='middle'>verify</text><text x='290' y='150' font-size='6.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>every request re-checked</text></svg>" },
    { "id": "sd1-12-3", "core": "core1", "domain": "sd1", "objective": "1.2", "term": "Honeypot", "definition": "A decoy system deliberately made to look vulnerable and attractive to attackers, used to detect and study malicious activity away from real assets.", "scenario": "observe attacker techniques on a deliberately vulnerable-looking fake server without risking real production data", "distractors": ["Honeynet", "Honeyfile", "Honeytoken"], "tip": "A single DECOY SYSTEM — a honeynet is a whole decoy NETWORK, honeyfile/honeytoken are decoy DATA, variations on the same idea at different scales." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-12-3'><title id='dt-sd1-12-3'>A single decoy system deliberately made to look vulnerable, used to detect and study attackers.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='2'/><text x='95' y='50' font-size='7.3' fill='var(--amber)' text-anchor='middle' font-weight='700'>Fake vulnerable</text><text x='95' y='64' font-size='6.4' fill='var(--amber)' text-anchor='middle'>server (decoy)</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Attacker</text><text x='285' y='58' font-size='6.4' fill='var(--red)' text-anchor='middle'>lured away from</text><text x='285' y='70' font-size='6.2' fill='var(--red)' text-anchor='middle'>real production data</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A single decoy system deliberately made to look vulnerable, used to detect and study</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>attackers.</text></svg>"},
    { "id": "sd1-12-4", "core": "core1", "domain": "sd1", "objective": "1.2", "term": "Gap analysis", "definition": "A structured comparison between an organization's current security posture and a desired target state, used to identify what controls or capabilities are missing.", "scenario": "identify exactly which required controls are missing before a compliance audit", "distractors": ["Risk assessment", "Penetration test", "Vulnerability scan"], "tip": "CURRENT state vs. DESIRED state — a risk assessment evaluates likelihood/impact of threats instead, a different kind of analysis." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-12-4'><title id='dt-sd1-12-4'>A structured comparison between current security posture and a desired target state.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Current posture</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>what exists today</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='50' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Target state</text><text x='285' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>required controls</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>CURRENT vs. DESIRED state \u2014 a risk assessment instead</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>evaluates likelihood/impact of threats.</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A structured comparison between current security posture and a desired target state.</text></svg>"},
    { "id": "sd1-12-5", "core": "core1", "domain": "sd1", "objective": "1.2", "term": "AAA (Authentication, Authorization, Accounting)", "definition": "A framework covering verifying identity (authentication), granting permissions (authorization), and logging activity (accounting) for system access.", "scenario": "verify a user's identity, decide what they're allowed to access, and log what they did after they log in", "distractors": ["CIA triad", "Non-repudiation", "Zero trust"], "tip": "Authentication, Authorization, Accounting — three access-control FUNCTIONS, not the CIA triad's broader confidentiality/integrity/availability goals.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-12-5'><title id='dt-sd1-12-5'>Three distinct functions in sequence — not the CIA triad's broader confidentiality/integrity/availability goals.</title><defs><marker id='sp-aaa-arrow' markerWidth='7' markerHeight='7' refX='6' refY='3.5' orient='auto'><path d='M0 0 L7 3.5 L0 7 Z' fill='var(--muted)'/></marker></defs><rect x='10' y='50' width='100' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='60' y='72' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Authentication</text><text x='60' y='87' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Who are you? (login)</text><line x1='110' y1='75' x2='140' y2='75' stroke='var(--muted)' stroke-width='1.3' marker-end='url(#sp-aaa-arrow)'/><rect x='140' y='50' width='100' height='50' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='190' y='72' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Authorization</text><text x='190' y='87' font-size='6.5' fill='var(--muted)' text-anchor='middle'>What can you do?</text><line x1='240' y1='75' x2='270' y2='75' stroke='var(--muted)' stroke-width='1.3' marker-end='url(#sp-aaa-arrow)'/><rect x='270' y='50' width='100' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='320' y='72' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Accounting</text><text x='320' y='87' font-size='6.5' fill='var(--muted)' text-anchor='middle'>What did you do? (log)</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)'>Three distinct functions in sequence — not the CIA triad's</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)'>broader confidentiality/integrity/availability goals.</text></svg>" },

    { "id": "sd1-13-1", "core": "core1", "domain": "sd1", "objective": "1.3", "term": "Change management process", "definition": "A formal, documented process for proposing, reviewing, approving, testing, and recording changes to systems, reducing the risk of unintended security impact.", "scenario": "get formal approval and a documented rollback plan before altering a production firewall's rule set", "distractors": ["Incident response plan", "Business continuity plan", "Standard operating procedure"], "tip": "PROPOSE, REVIEW, APPROVE, TEST, RECORD — the full formal cycle for planned changes, distinct from an incident response plan for unplanned events." , "diagram": "<svg viewBox='0 0 380 236' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-13-1'><title id='dt-sd1-13-1'>Propose, review, approve, test, and record \u2014 the full formal cycle for planned changes.</title><rect x='16' y='16' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='27' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Impact analysis</text><text x='190.0' y='40' font-size='7.5' fill='var(--muted)' text-anchor='middle'>assess what could break</text><line x1='190.0' y1='48' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Change approval</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>formal review</text><line x1='190.0' y1='90' x2='190.0' y2='94' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 92 L190.0 99 L194.0 92' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='100' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='111' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Maintenance window</text><text x='190.0' y='124' font-size='7.5' fill='var(--muted)' text-anchor='middle'>scheduled, low-impact time</text><line x1='190.0' y1='132' x2='190.0' y2='136' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 134 L190.0 141 L194.0 134' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='142' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='153' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Backout plan ready</text><text x='190.0' y='166' font-size='7.5' fill='var(--muted)' text-anchor='middle'>if it goes wrong</text><text x='16' y='214' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Propose, review, approve, test, and record \u2014 the full formal cycle for planned</text><text x='16' y='226' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>changes.</text></svg>"},
    { "id": "sd1-13-2", "core": "core1", "domain": "sd1", "objective": "1.3", "term": "Backout plan", "definition": "A predefined procedure for reversing a change and restoring the previous known-good state if the change causes unexpected problems.", "scenario": "quickly revert a failed software update that broke authentication for every user", "distractors": ["Maintenance window", "Change approval board", "Impact analysis"], "tip": "REVERSES a change if it goes wrong — must be planned BEFORE the change, not improvised after something breaks." , "diagram": "<svg viewBox='0 0 380 236' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-13-2'><title id='dt-sd1-13-2'>Reverses a change if it goes wrong \u2014 must be planned BEFORE the change, not improvised after something breaks.</title><rect x='16' y='16' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='27' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Impact analysis</text><text x='190.0' y='40' font-size='7.5' fill='var(--muted)' text-anchor='middle'>assess what could break</text><line x1='190.0' y1='48' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Change approval</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>formal review</text><line x1='190.0' y1='90' x2='190.0' y2='94' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 92 L190.0 99 L194.0 92' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='100' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='111' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Maintenance window</text><text x='190.0' y='124' font-size='7.5' fill='var(--muted)' text-anchor='middle'>scheduled, low-impact time</text><line x1='190.0' y1='132' x2='190.0' y2='136' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 134 L190.0 141 L194.0 134' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='142' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='153' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Backout plan ready</text><text x='190.0' y='166' font-size='7.5' fill='var(--text)' text-anchor='middle'>if it goes wrong</text><text x='16' y='214' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Reverses a change if it goes wrong \u2014 must be planned BEFORE the change, not</text><text x='16' y='226' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>improvised after something breaks.</text></svg>"},
    { "id": "sd1-13-3", "core": "core1", "domain": "sd1", "objective": "1.3", "term": "Maintenance window", "definition": "A scheduled, pre-approved time period during which changes can be made to production systems with minimal impact on users.", "scenario": "schedule a risky server patch for 2 a.m. Sunday when usage is lowest", "distractors": ["Backout plan", "Change freeze", "Service level agreement"], "tip": "PRE-APPROVED TIME slot — a change freeze is the opposite, a period where NO changes are allowed at all." , "diagram": "<svg viewBox='0 0 380 236' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-13-3'><title id='dt-sd1-13-3'>A pre-approved time slot for changes \u2014 a change FREEZE is the opposite, a period where no changes are allowed.</title><rect x='16' y='16' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='27' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Impact analysis</text><text x='190.0' y='40' font-size='7.5' fill='var(--muted)' text-anchor='middle'>assess what could break</text><line x1='190.0' y1='48' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Change approval</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>formal review</text><line x1='190.0' y1='90' x2='190.0' y2='94' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 92 L190.0 99 L194.0 92' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='100' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='111' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Maintenance window</text><text x='190.0' y='124' font-size='7.5' fill='var(--text)' text-anchor='middle'>scheduled, low-impact time</text><line x1='190.0' y1='132' x2='190.0' y2='136' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 134 L190.0 141 L194.0 134' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='142' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='153' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Backout plan ready</text><text x='190.0' y='166' font-size='7.5' fill='var(--muted)' text-anchor='middle'>if it goes wrong</text><text x='16' y='214' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A pre-approved time slot for changes \u2014 a change FREEZE is the opposite, a</text><text x='16' y='226' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>period where no changes are allowed.</text></svg>"},
    { "id": "sd1-13-4", "core": "core1", "domain": "sd1", "objective": "1.3", "term": "Impact analysis", "definition": "An assessment of how a proposed change could affect systems, users, and security before the change is approved and implemented.", "scenario": "evaluate what else might break before approving a change to a shared authentication server", "distractors": ["Backout plan", "Root cause analysis", "Business impact analysis"], "tip": "BEFORE approval — assesses what COULD be affected; root cause analysis instead happens AFTER an incident to find what went wrong." , "diagram": "<svg viewBox='0 0 380 236' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-13-4'><title id='dt-sd1-13-4'>Assesses what COULD be affected BEFORE approval \u2014 root cause analysis instead happens AFTER an incident.</title><rect x='16' y='16' width='348' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='190.0' y='27' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Impact analysis</text><text x='190.0' y='40' font-size='7.5' fill='var(--text)' text-anchor='middle'>assess what could break</text><line x1='190.0' y1='48' x2='190.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 50 L190.0 57 L194.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Change approval</text><text x='190.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>formal review</text><line x1='190.0' y1='90' x2='190.0' y2='94' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 92 L190.0 99 L194.0 92' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='100' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='111' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Maintenance window</text><text x='190.0' y='124' font-size='7.5' fill='var(--muted)' text-anchor='middle'>scheduled, low-impact time</text><line x1='190.0' y1='132' x2='190.0' y2='136' stroke='var(--muted)' stroke-width='1.5'/><path d='M186.0 134 L190.0 141 L194.0 134' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='142' width='348' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='190.0' y='153' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Backout plan ready</text><text x='190.0' y='166' font-size='7.5' fill='var(--muted)' text-anchor='middle'>if it goes wrong</text><text x='16' y='214' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Assesses what COULD be affected BEFORE approval \u2014 root cause analysis instead</text><text x='16' y='226' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>happens AFTER an incident.</text></svg>"},

    { "id": "sd1-14-1", "core": "core1", "domain": "sd1", "objective": "1.4", "term": "Public key infrastructure (PKI)", "definition": "A framework of policies, roles, and technology used to create, manage, distribute, and revoke digital certificates and manage public-key encryption.", "scenario": "issue and manage trusted digital certificates for a company's internal and external websites", "distractors": ["Hashing algorithm", "Symmetric encryption", "Digital rights management"], "tip": "The FRAMEWORK around certificates — creates, distributes, and revokes them; not itself an encryption algorithm.", "diagram": "<svg viewBox='0 0 380 210' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-14-1'><title id='dt-sd1-14-1'>PKI is the whole framework around this \u2014 issuing, distributing, and revoking the certificates, not an encryption algorithm itself.</title><rect x='120' y='10' width='140' height='34' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='190' y='31' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Certificate Authority</text><line x1='190' y1='44' x2='190' y2='60' stroke='var(--primary)' stroke-width='1.3'/><text x='200' y='55' font-size='6.5' fill='var(--muted)'>issues, binds identity to a public key</text><rect x='120' y='60' width='140' height='30' rx='5' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='79' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Certificate (public key)</text><rect x='16' y='120' width='140' height='40' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='86' y='140' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Sender</text><text x='86' y='153' font-size='6.5' fill='var(--muted)' text-anchor='middle'>encrypts with recipient's public key</text><line x1='156' y1='140' x2='224' y2='140' stroke='var(--blue)' stroke-width='1.5'/><rect x='224' y='120' width='140' height='40' rx='6' fill='var(--green)' fill-opacity='.14' stroke='var(--green)' stroke-width='1.5'/><text x='294' y='140' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Recipient</text><text x='294' y='153' font-size='6.5' fill='var(--muted)' text-anchor='middle'>only their private key can decrypt</text><text x='16' y='188' font-size='8.5' fill='var(--muted-2)'>PKI is the whole framework around this \u2014 issuing, distributing,</text><text x='16' y='200' font-size='8.5' fill='var(--muted-2)'>and revoking the certificates, not an encryption algorithm itself.</text></svg>" },
    { "id": "sd1-14-2", "core": "core1", "domain": "sd1", "objective": "1.4", "term": "Hardware security module (HSM)", "definition": "A dedicated physical device that securely generates, stores, and manages cryptographic keys, keeping them isolated from general-purpose servers.", "scenario": "store a certificate authority's private signing key in a way that's extremely resistant to extraction even if the server is compromised", "distractors": ["Trusted Platform Module (TPM)", "Key management system (KMS)", "Hardware token"], "tip": "DEDICATED physical device for KEYS — a TPM is similar but built INTO a single computer, this is typically a separate enterprise-grade appliance." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-14-2'><title id='dt-sd1-14-2'>A dedicated physical device for keys \u2014 a TPM is similar but built into a single computer, this is a separate enterprise appliance.</title><rect x='130' y='24' width='120' height='80' rx='8' fill='var(--surface-2)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='46' font-size='10' fill='var(--text)' text-anchor='middle' font-weight='700'>HSM</text><rect x='155' y='58' width='70' height='30' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='190' y='77' font-size='8' fill='var(--text)' text-anchor='middle'>\ud83d\udd11 keys</text><text x='190' y='118' font-size='7.3' fill='var(--text)' text-anchor='middle'>A dedicated, isolated physical device \u2014</text><text x='190' y='130' font-size='7.3' fill='var(--text)' text-anchor='middle'>a TPM does similar work built into one PC.</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A dedicated physical device for keys \u2014 a TPM is similar but built into a single</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>computer, this is a separate enterprise appliance.</text></svg>"},
    { "id": "sd1-14-3", "core": "core1", "domain": "sd1", "objective": "1.4", "term": "Salting", "definition": "Adding random, unique data to a password before hashing it, so that identical passwords produce different hash outputs and precomputed rainbow tables become ineffective.", "scenario": "prevent two users with the identical password from having identical stored password hashes", "distractors": ["Hashing alone", "Encryption", "Obfuscation"], "tip": "RANDOM data added BEFORE hashing — defeats precomputed rainbow tables, since identical passwords now produce DIFFERENT hashes." , "diagram": "<svg viewBox='0 0 380 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-14-3'><title id='dt-sd1-14-3'>A random value added before hashing \u2014 identical passwords now produce different hashes, defeating precomputed rainbow tables.</title><text x='95' y='16' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>No salt</text><rect x='20' y='26' width='150' height='20' rx='3' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='40' font-size='7' fill='var(--text)' text-anchor='middle'>pass = &#39;hunter2&#39;</text><line x1='95' y1='46' x2='95' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M91 54 L95 61 L99 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='64' width='150' height='20' rx='3' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='95' y='78' font-size='7' fill='var(--red)' text-anchor='middle'>hash: 8f14e45f...</text><text x='95' y='98' font-size='6.8' fill='var(--muted)' text-anchor='middle'>same password \u2192 same hash,</text><text x='95' y='109' font-size='6.8' fill='var(--muted)' text-anchor='middle'>crackable via rainbow table</text><text x='285' y='16' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Salted</text><rect x='210' y='26' width='150' height='20' rx='3' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='40' font-size='7' fill='var(--text)' text-anchor='middle'>pass + salt &#39;x7q2&#39;</text><line x1='285' y1='46' x2='285' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M281 54 L285 61 L289 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='64' width='150' height='20' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='285' y='78' font-size='7' fill='var(--primary)' text-anchor='middle'>hash: c1a9f02b...</text><text x='285' y='98' font-size='6.8' fill='var(--muted)' text-anchor='middle'>unique salt per user \u2192</text><text x='285' y='109' font-size='6.8' fill='var(--muted)' text-anchor='middle'>different hash every time</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A random value added before hashing \u2014 identical passwords now produce different</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>hashes, defeating precomputed rainbow tables.</text></svg>"},
    { "id": "sd1-14-4", "core": "core1", "domain": "sd1", "objective": "1.4", "term": "Digital signature", "definition": "A cryptographic mechanism that uses a sender's private key to prove the authenticity and integrity of a message, verifiable by anyone with the sender's public key.", "scenario": "let recipients verify that a signed software update genuinely came from the vendor and wasn't tampered with", "distractors": ["Symmetric key exchange", "Hashing alone", "Steganography"], "tip": "PRIVATE key signs, PUBLIC key verifies — proves both authenticity AND integrity together, more than hashing alone provides." , "diagram": "<svg viewBox='0 0 400 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-14-4'><title id='dt-sd1-14-4'>Private key signs, public key verifies \u2014 proving both authenticity and integrity together, more than a plain hash alone provides.</title><rect x='20' y='30' width='90' height='30' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='65' y='49' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Sender</text><text x='65' y='68' font-size='7' fill='var(--muted)' text-anchor='middle'>signs with</text><text x='65' y='79' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>PRIVATE key</text><line x1='110' y1='45' x2='254' y2='45' stroke='var(--muted)' stroke-width='1.5'/><path d='M252 41 L259 45 L252 49' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='150' y='33' width='120' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='210' y='49' font-size='7' fill='var(--text)' text-anchor='middle'>message + signature</text><rect x='280' y='30' width='90' height='30' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='325' y='49' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Recipient</text><text x='325' y='68' font-size='7' fill='var(--muted)' text-anchor='middle'>verifies with</text><text x='325' y='79' font-size='7' fill='var(--blue)' text-anchor='middle' font-weight='700'>PUBLIC key</text><text x='190' y='108' font-size='7.5' fill='var(--text)' text-anchor='middle'>Proves both authenticity (it was really the sender)</text><text x='190' y='120' font-size='7.5' fill='var(--text)' text-anchor='middle'>and integrity (nothing was altered in transit).</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Private key signs, public key verifies \u2014 proving both authenticity and integrity</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>together, more than a plain hash alone provides.</text></svg>"},
    { "id": "sd1-14-5", "core": "core1", "domain": "sd1", "objective": "1.4", "term": "Key escrow", "definition": "A practice of storing a copy of a cryptographic key with a trusted third party so it can be recovered if the original is lost, without weakening day-to-day security.", "scenario": "ensure encrypted company data can still be recovered even if the only employee who knows the encryption key leaves the company", "distractors": ["Key stretching", "Perfect forward secrecy", "Certificate pinning"], "tip": "A TRUSTED THIRD PARTY holds a backup copy — recovery-focused, the opposite goal of perfect forward secrecy, which makes old keys unrecoverable." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd1-14-5'><title id='dt-sd1-14-5'>Storing a copy of a cryptographic key with a trusted third party so it can be recovered if lost.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Original key</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>held by employee</text><rect x='210' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Escrow copy</text><text x='285' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>trusted third party</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>A backup for RECOVERY \u2014 the opposite goal of perfect</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>forward secrecy, which makes old keys unrecoverable.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Storing a copy of a cryptographic key with a trusted third party so it can be</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>recovered if lost.</text></svg>"},

    { "id": "sd2-21-1", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Nation-state actor", "definition": "A highly resourced, sophisticated threat actor sponsored or directed by a government, typically pursuing espionage, sabotage, or long-term strategic objectives.", "scenario": "explain who is most likely behind a highly sophisticated, patient, multi-year intrusion targeting critical infrastructure", "distractors": ["Unskilled attacker (script kiddie)", "Hacktivist", "Insider threat"], "tip": "GOVERNMENT-sponsored, highly resourced — espionage and sabotage over quick financial gain, the most sophisticated tier of threat actor." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-1'><title id='dt-sd2-21-1'>Government-sponsored and highly resourced \u2014 espionage and sabotage over quick financial gain, the most sophisticated tier.</title><text x='190' y='16' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat actor sophistication / resourcing</text><rect x='20' y='100' width='62' height='30' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='51.0' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Unskilled</text><text x='51.0' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>attacker</text><rect x='88' y='88' width='62' height='42' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='119.0' y='80' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Hacktivist</text><rect x='156' y='76' width='62' height='54' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='187.0' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Insider</text><text x='187.0' y='68' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>threat</text><rect x='224' y='64' width='62' height='66' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='255.0' y='46' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Organized</text><text x='255.0' y='56' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>crime</text><rect x='292' y='52' width='62' height='78' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='323.0' y='44' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Nation-state</text><text x='190' y='148' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>government-sponsored espionage</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Government-sponsored and highly resourced \u2014 espionage and sabotage over quick</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>financial gain, the most sophisticated tier.</text></svg>"},
    { "id": "sd2-21-2", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Hacktivist", "definition": "A threat actor motivated by political or social causes, typically seeking to embarrass, disrupt, or draw attention to a target rather than gain financially.", "scenario": "explain who defaced a company's website with a political message after a controversial company decision", "distractors": ["Organized crime", "Nation-state actor", "Insider threat"], "tip": "POLITICAL/SOCIAL motive — embarrassment or disruption, not direct financial gain like organized crime." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-2'><title id='dt-sd2-21-2'>Political or social motive \u2014 seeks to embarrass, disrupt, or draw attention, not direct financial gain like organized crime.</title><text x='190' y='16' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat actor sophistication / resourcing</text><rect x='20' y='100' width='62' height='30' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='51.0' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Unskilled</text><text x='51.0' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>attacker</text><rect x='88' y='88' width='62' height='42' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='119.0' y='80' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Hacktivist</text><rect x='156' y='76' width='62' height='54' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='187.0' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Insider</text><text x='187.0' y='68' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>threat</text><rect x='224' y='64' width='62' height='66' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='255.0' y='46' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Organized</text><text x='255.0' y='56' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>crime</text><rect x='292' y='52' width='62' height='78' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='323.0' y='44' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Nation-state</text><text x='190' y='148' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>political / social causes</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Political or social motive \u2014 seeks to embarrass, disrupt, or draw attention,</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>not direct financial gain like organized crime.</text></svg>"},
    { "id": "sd2-21-3", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Insider threat", "definition": "A threat originating from someone with legitimate authorized access, such as a current or former employee, who misuses that access maliciously or negligently.", "scenario": "explain how a disgruntled former employee's still-active account was used to delete critical files", "distractors": ["Nation-state actor", "Hacktivist", "Organized crime"], "tip": "Already has LEGITIMATE access — the defining trait, whether the misuse is malicious OR just negligent." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-3'><title id='dt-sd2-21-3'>Already has legitimate access \u2014 the defining trait, whether the misuse turns out to be malicious or just negligent.</title><text x='190' y='16' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat actor sophistication / resourcing</text><rect x='20' y='100' width='62' height='30' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='51.0' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Unskilled</text><text x='51.0' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>attacker</text><rect x='88' y='88' width='62' height='42' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='119.0' y='80' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Hacktivist</text><rect x='156' y='76' width='62' height='54' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='187.0' y='58' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Insider</text><text x='187.0' y='68' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>threat</text><rect x='224' y='64' width='62' height='66' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='255.0' y='46' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Organized</text><text x='255.0' y='56' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>crime</text><rect x='292' y='52' width='62' height='78' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='323.0' y='44' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Nation-state</text><text x='190' y='148' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>already has legitimate access</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Already has legitimate access \u2014 the defining trait, whether the misuse turns</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>out to be malicious or just negligent.</text></svg>"},
    { "id": "sd2-21-4", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Organized crime", "definition": "A structured, well-funded criminal group whose attacks are primarily motivated by direct financial gain, such as ransomware operations.", "scenario": "explain the most likely motivation behind a coordinated ransomware attack demanding a large cryptocurrency payment", "distractors": ["Hacktivist", "Nation-state actor", "Unskilled attacker"], "tip": "FINANCIAL gain, structured and well-funded — ransomware operations are the classic modern example." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-4'><title id='dt-sd2-21-4'>Financial gain, structured and well-funded \u2014 ransomware operations are the classic modern example.</title><text x='190' y='16' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat actor sophistication / resourcing</text><rect x='20' y='100' width='62' height='30' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='51.0' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Unskilled</text><text x='51.0' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>attacker</text><rect x='88' y='88' width='62' height='42' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='119.0' y='80' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Hacktivist</text><rect x='156' y='76' width='62' height='54' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='187.0' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Insider</text><text x='187.0' y='68' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>threat</text><rect x='224' y='64' width='62' height='66' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='255.0' y='46' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Organized</text><text x='255.0' y='56' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>crime</text><rect x='292' y='52' width='62' height='78' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='323.0' y='44' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Nation-state</text><text x='190' y='148' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>direct financial gain</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Financial gain, structured and well-funded \u2014 ransomware operations are the</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>classic modern example.</text></svg>"},
    { "id": "sd2-21-5", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Shadow IT", "definition": "Technology, systems, or applications used within an organization without the knowledge or approval of the IT department, creating unmanaged security risk.", "scenario": "explain the risk of a department using an unapproved cloud file-sharing tool that IT has never vetted or secured", "distractors": ["Insider threat", "Supply chain risk", "Zero-day vulnerability"], "tip": "UNAPPROVED but not necessarily malicious — an employee using an unsanctioned app still creates real risk, even with good intentions." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-5'><title id='dt-sd2-21-5'>Technology used within an organization without IT&#39;s knowledge or approval, creating unmanaged risk.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='2'/><text x='95' y='50' font-size='7' fill='var(--amber)' text-anchor='middle' font-weight='700'>Unapproved cloud tool</text><text x='95' y='64' font-size='6.2' fill='var(--amber)' text-anchor='middle'>IT never vetted it</text><rect x='210' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='50' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>IT-approved tools</text><text x='285' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>reviewed &amp; secured</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>UNAPPROVED but not necessarily malicious \u2014 good</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>intentions still create real, unmanaged risk.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Technology used within an organization without IT&#39;s knowledge or approval, creating</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>unmanaged risk.</text></svg>"},
    { "id": "sd2-21-6", "core": "core1", "domain": "sd2", "objective": "2.1", "term": "Unskilled attacker", "definition": "A low-skill threat actor who uses existing tools and scripts written by others rather than developing their own techniques, often motivated by curiosity or notoriety.", "scenario": "explain the profile of an attacker who downloaded a pre-built exploit tool online and ran it against random targets", "distractors": ["Nation-state actor", "Organized crime", "Insider threat"], "tip": "USES existing tools/scripts, doesn't build their own — 'script kiddie' is the common nickname, motivated by curiosity or notoriety over profit." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-21-6'><title id='dt-sd2-21-6'>Uses existing tools/scripts rather than building their own \u2014 the classic &#39;script kiddie&#39;, motivated by curiosity or notoriety.</title><text x='190' y='16' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat actor sophistication / resourcing</text><rect x='20' y='100' width='62' height='30' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='51.0' y='82' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Unskilled</text><text x='51.0' y='92' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>attacker</text><rect x='88' y='88' width='62' height='42' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='119.0' y='80' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Hacktivist</text><rect x='156' y='76' width='62' height='54' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='187.0' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Insider</text><text x='187.0' y='68' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>threat</text><rect x='224' y='64' width='62' height='66' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='255.0' y='46' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Organized</text><text x='255.0' y='56' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>crime</text><rect x='292' y='52' width='62' height='78' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='323.0' y='44' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Nation-state</text><text x='190' y='148' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>curiosity, notoriety</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Uses existing tools/scripts rather than building their own \u2014 the classic</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>&#39;script kiddie&#39;, motivated by curiosity or notoriety.</text></svg>"},

    { "id": "sd2-22-1", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Attack surface", "definition": "The complete set of points where an unauthorized user could try to enter or extract data from a system, including every exposed service, port, and interface.", "scenario": "identify everything that needs to be evaluated before deciding a new internet-facing server is secure", "distractors": ["Attack vector", "Threat vector", "Vulnerability"], "tip": "The TOTAL exposed area — an attack VECTOR is the specific PATH used through part of that surface, a related but distinct concept." , "diagram": "<svg viewBox='0 0 380 195' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-1'><title id='dt-sd2-22-1'>The total exposed area \u2014 an attack VECTOR is the specific path used through part of that surface, a related but distinct idea.</title><circle cx='190' cy='80' r='60' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><circle cx='140' cy='40' r='5' fill='var(--red)'/><text x='140' y='30' font-size='6.3' fill='var(--red)' text-anchor='middle'>open port</text><circle cx='240' cy='40' r='5' fill='var(--red)'/><text x='240' y='30' font-size='6.3' fill='var(--red)' text-anchor='middle'>web app</text><circle cx='140' cy='120' r='5' fill='var(--red)'/><text x='140' y='136' font-size='6.3' fill='var(--red)' text-anchor='middle'>API</text><circle cx='240' cy='120' r='5' fill='var(--red)'/><text x='240' y='136' font-size='6.3' fill='var(--red)' text-anchor='middle'>legacy service</text><circle cx='190' cy='30' r='5' fill='var(--red)'/><text x='190' y='20' font-size='6.3' fill='var(--red)' text-anchor='middle'>VPN</text><text x='190' y='84' font-size='7' fill='var(--muted)' text-anchor='middle'>assets</text><text x='190' y='150' font-size='7.3' fill='var(--text)' text-anchor='middle'>Every exposed point on the boundary is part of the surface.</text><text x='16' y='173' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The total exposed area \u2014 an attack VECTOR is the specific path used through</text><text x='16' y='185' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>part of that surface, a related but distinct idea.</text></svg>"},
    { "id": "sd2-22-2", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Business email compromise (BEC)", "definition": "A social engineering attack vector in which an attacker impersonates an executive or trusted partner via email to trick an employee into transferring funds or sensitive data.", "scenario": "explain how an employee wired funds after receiving an urgent email that appeared to be from the CEO", "distractors": ["Phishing (generic)", "Vishing", "Typosquatting"], "tip": "IMPERSONATES an executive/partner specifically — targets a financial transfer or data handoff, a more targeted variant than generic phishing." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-2'><title id='dt-sd2-22-2'>Impersonates an executive or trusted partner via email to trick an employee into transferring funds.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>&quot;From: CEO&quot;</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>urgent wire request</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='44' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Employee</text><text x='285' y='58' font-size='6.4' fill='var(--muted)' text-anchor='middle'>wires funds,</text><text x='285' y='70' font-size='6.4' fill='var(--muted)' text-anchor='middle'>trusting the sender</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Impersonates an executive or trusted partner via email to trick an employee into</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>transferring funds.</text></svg>"},
    { "id": "sd2-22-3", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Removable media as an attack vector", "definition": "An attack vector where infected USB drives or other removable media are used to introduce malware onto a system, sometimes by deliberately leaving them where a target will find and plug them in.", "scenario": "explain how a system got infected after an employee plugged in a USB drive found in the parking lot", "distractors": ["Wireless attack vector", "Supply chain attack vector", "Message-based vector"], "tip": "PHYSICAL media (USB drives) — the 'dropped USB in the parking lot' scenario is the classic real-world example." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-3'><title id='dt-sd2-22-3'>Infected USB drives or removable media used to introduce malware, sometimes deliberately left to be found.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>USB drive</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>found in parking lot</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Plugged in</text><text x='285' y='58' font-size='6.4' fill='var(--red)' text-anchor='middle'>malware runs</text><text x='285' y='70' font-size='6.4' fill='var(--red)' text-anchor='middle'>PHYSICAL vector</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Infected USB drives or removable media used to introduce malware, sometimes</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>deliberately left to be found.</text></svg>"},
    { "id": "sd2-22-4", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Unsupported systems and applications", "definition": "Software or hardware no longer receiving security updates from its vendor, leaving known vulnerabilities permanently unpatched and exploitable.", "scenario": "explain the risk of continuing to run a critical application on an operating system whose vendor stopped issuing security patches years ago", "distractors": ["Zero-day vulnerability", "Misconfiguration", "Default credential vulnerability"], "tip": "NO MORE PATCHES available at all — different from a zero-day, where a patch simply doesn't exist YET but could still come." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-4'><title id='dt-sd2-22-4'>Software/hardware no longer receiving security updates, leaving known vulnerabilities permanently unpatched.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Unsupported system</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>NO patches will EVER come</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Zero-day</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>no patch YET, but could come</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Software/hardware no longer receiving security updates, leaving known</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>vulnerabilities permanently unpatched.</text></svg>"},
    { "id": "sd2-22-5", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Default credentials", "definition": "An attack vector where devices or software are compromised because factory-default usernames and passwords were never changed after deployment.", "scenario": "explain how an attacker gained admin access to a newly installed router without any password-cracking effort at all", "distractors": ["Zero-day exploit", "Brute-force attack", "Supply chain attack"], "tip": "NEVER CHANGED from factory defaults — an easily preventable gap, unlike a zero-day which has no known fix at all." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-5'><title id='dt-sd2-22-5'>Devices or software compromised because factory-default usernames/passwords were never changed.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='95' y='50' font-size='7.5' fill='var(--red)' text-anchor='middle' font-weight='700'>admin / admin</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>never changed</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='44' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Router</text><text x='285' y='58' font-size='6.4' fill='var(--muted)' text-anchor='middle'>admin access</text><text x='285' y='70' font-size='6' fill='var(--muted)' text-anchor='middle'>zero cracking effort</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Devices or software compromised because factory-default usernames/passwords were</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>never changed.</text></svg>"},
    { "id": "sd2-22-6", "core": "core1", "domain": "sd2", "objective": "2.2", "term": "Supply chain attack vector", "definition": "An attack vector that compromises a target indirectly by first compromising a trusted vendor, software update mechanism, or hardware component in its supply chain.", "scenario": "explain how thousands of customers were compromised at once through a poisoned update from a trusted software vendor", "distractors": ["Business email compromise", "Removable media vector", "Wireless vector"], "tip": "Compromises a TRUSTED VENDOR first — the target is breached indirectly through something they already trust, not attacked head-on." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-22-6'><title id='dt-sd2-22-6'>Compromises a target indirectly by first compromising a trusted vendor or software update mechanism.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Trusted vendor</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>poisoned update</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Thousands of</text><text x='285' y='58' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>customers</text><text x='285' y='70' font-size='6' fill='var(--red)' text-anchor='middle'>compromised at once</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>Breaches indirectly through something ALREADY</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>trusted \u2014 not attacked head-on.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Compromises a target indirectly by first compromising a trusted vendor or software</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>update mechanism.</text></svg>"},

    { "id": "sd2-23-1", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Buffer overflow", "definition": "An application vulnerability where a program writes more data to a memory buffer than it was allocated, potentially overwriting adjacent memory and allowing arbitrary code execution.", "scenario": "explain how an attacker's crafted input allowed them to overwrite adjacent memory and execute their own code", "distractors": ["SQL injection", "Race condition", "Cross-site scripting"], "tip": "WRITES past allocated MEMORY — can run arbitrary code, a memory-safety issue distinct from injection-style web vulnerabilities.", "diagram": "<svg viewBox='0 0 380 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-1'><title id='dt-sd2-23-1'>A memory-safety issue — distinct from injection-style web vulnerabilities like SQL injection or XSS.</title><text x='16' y='18' font-size='8' fill='var(--muted)' font-weight='700'>Allocated buffer (8 bytes)</text><rect x='16' y='26' width='120' height='30' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><rect x='136' y='26' width='90' height='30' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='181' y='46' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>overflow</text><rect x='226' y='26' width='90' height='30' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='271' y='46' font-size='6.5' fill='var(--muted)' text-anchor='middle'>return address</text><line x1='226' y1='26' x2='226' y2='56' stroke='var(--red)' stroke-width='2'/><text x='16' y='80' font-size='7.5' fill='var(--text)'>Crafted input writes PAST the 8-byte boundary,</text><text x='16' y='94' font-size='7.5' fill='var(--red)' font-weight='700'>overwriting the return address next to it —</text><text x='16' y='108' font-size='7.5' fill='var(--red)' font-weight='700'>redirecting execution to the attacker's own code.</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)'>A memory-safety issue — distinct from injection-style</text><text x='16' y='152' font-size='8.5' fill='var(--muted-2)'>web vulnerabilities like SQL injection or XSS.</text></svg>" },
    { "id": "sd2-23-2", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Race condition", "definition": "A vulnerability that occurs when the security of an operation depends on timing, allowing an attacker to exploit the gap between when a condition is checked and when it's acted on.", "scenario": "explain how an attacker swapped a file after it passed a security check but before it was actually used", "distractors": ["Buffer overflow", "Memory leak", "Privilege escalation"], "tip": "TIMING gap between CHECK and ACT — the vulnerability lives in that window, not in the memory itself like a buffer overflow." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-2'><title id='dt-sd2-23-2'>The vulnerability lives in the timing gap between when a condition is checked and when it&#39;s acted on.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='36' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>File passes security check</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>TIMING GAP</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>attacker swaps the file HERE</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>File actually used</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>now malicious</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The vulnerability lives in the timing gap between when a condition is</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>checked and when it&#39;s acted on.</text></svg>"},
    { "id": "sd2-23-3", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "SQL injection", "definition": "A web application vulnerability where unsanitized user input is inserted into a database query, allowing an attacker to manipulate or extract database contents.", "scenario": "explain how an attacker retrieved every user's password hash by entering crafted text into a website's login form", "distractors": ["Cross-site scripting (XSS)", "Buffer overflow", "Cross-site request forgery"], "tip": "Manipulates the DATABASE QUERY — XSS instead injects script that runs in OTHER USERS' browsers, a different target entirely.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-3'><title id='dt-sd2-23-3'>Manipulates the database query directly — XSS instead runs script in other users' browsers, a different target.</title><text x='16' y='18' font-size='8' fill='var(--muted)' font-weight='700'>Normal input</text><rect x='16' y='24' width='150' height='22' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='24' y='39' font-size='6.5' fill='var(--text)'>user = 'alice'</text><line x1='166' y1='35' x2='196' y2='35' stroke='var(--muted)' stroke-width='1.2'/><rect x='196' y='24' width='168' height='22' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='204' y='39' font-size='6' fill='var(--text)'>SELECT * WHERE user='alice'</text><text x='16' y='70' font-size='8' fill='var(--red)' font-weight='700'>Malicious input</text><rect x='16' y='76' width='150' height='22' rx='3' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='24' y='91' font-size='6' fill='var(--red)' font-weight='700'>user = ' OR '1'='1</text><line x1='166' y1='87' x2='196' y2='87' stroke='var(--red)' stroke-width='1.3'/><rect x='196' y='76' width='168' height='22' rx='3' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='204' y='91' font-size='5.7' fill='var(--red)' font-weight='700'>SELECT * WHERE user='' OR '1'='1'</text><text x='16' y='124' font-size='7.5' fill='var(--red)' font-weight='700'>The query now matches EVERY row, not just one —</text><text x='16' y='138' font-size='7.5' fill='var(--red)' font-weight='700'>the crafted text broke out of the intended condition.</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)'>Manipulates the database query directly — XSS instead runs</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)'>script in other users' browsers, a different target.</text></svg>" },
    { "id": "sd2-23-4", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Cross-site scripting (XSS)", "definition": "A web application vulnerability where an attacker injects malicious script into a page viewed by other users, allowing it to run in their browser session.", "scenario": "explain how a malicious comment posted on a forum ran JavaScript in every other visitor's browser", "distractors": ["SQL injection", "Cross-site request forgery", "Directory traversal"], "tip": "Runs in OTHER USERS' browser sessions — SQL injection targets the database backend instead, a different layer of the application.", "diagram": "<svg viewBox='0 0 380 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-4'><title id='dt-sd2-23-4'>A web application vulnerability where an attacker injects malicious script into a page viewed by other users, allowing it to run in their browser session.</title><circle cx='45' cy='50' r='16' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='45' y='75' font-size='7' fill='var(--muted)' text-anchor='middle'>Attacker</text><rect x='90' y='36' width='110' height='30' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='145' y='55' font-size='6.5' fill='var(--red)' text-anchor='middle' font-weight='700'>posts &lt;script&gt; in comment</text><line x1='200' y1='50' x2='230' y2='50' stroke='var(--muted)' stroke-width='1.3'/><rect x='230' y='30' width='130' height='42' rx='5' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='295' y='47' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>Forum page</text><text x='295' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>stores the comment as-is</text><line x1='295' y1='72' x2='295' y2='90' stroke='var(--muted)' stroke-width='1.3'/><circle cx='295' cy='112' r='16' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='295' y='140' font-size='7' fill='var(--muted)' text-anchor='middle'>Victim loads page —</text><text x='295' y='152' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>script runs in THEIR session</text></svg>" },
    { "id": "sd2-23-5", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Zero-day vulnerability", "definition": "A vulnerability that is unknown to the vendor and has no available patch, meaning attackers can exploit it before a fix exists.", "scenario": "explain why a brand-new attack technique against fully patched software still succeeded", "distractors": ["Unsupported system vulnerability", "Misconfiguration", "Default credential vulnerability"], "tip": "UNKNOWN to the vendor, NO patch exists yet — different from an unsupported system, where a patch WOULD exist if still supported." , "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-5'><title id='dt-sd2-23-5'>Unknown to the vendor with no patch available \u2014 attackers can exploit it during the entire window before a fix ever exists.</title><line x1='30' y1='80' x2='350' y2='80' stroke='var(--border)' stroke-width='1.5'/><circle cx='60' cy='80' r='5' fill='var(--muted)'/><text x='60' y='68' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Vuln introduced</text><text x='60' y='100' font-size='6.5' fill='var(--muted)' text-anchor='middle'>in the code</text><circle cx='160' cy='80' r='5' fill='var(--red)'/><text x='160' y='68' font-size='6.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Attacker discovers</text><text x='160' y='100' font-size='6.5' fill='var(--red)' text-anchor='middle'>and exploits it</text><circle cx='260' cy='80' r='5' fill='var(--amber)'/><text x='260' y='68' font-size='6.5' fill='var(--amber)' text-anchor='middle' font-weight='700'>Vendor learns</text><text x='260' y='100' font-size='6.5' fill='var(--amber)' text-anchor='middle'>of the flaw</text><circle cx='340' cy='80' r='5' fill='var(--primary)'/><text x='340' y='68' font-size='6.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Patch released</text><rect x='160' y='108' width='100' height='18' rx='3' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='210' y='121' font-size='6.5' fill='var(--red)' text-anchor='middle' font-weight='700'>zero-day exposure window</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Unknown to the vendor with no patch available \u2014 attackers can exploit it during</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the entire window before a fix ever exists.</text></svg>"},
    { "id": "sd2-23-6", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Misconfiguration", "definition": "A vulnerability that arises when a system, application, or device is set up with insecure settings, such as an open cloud storage bucket or an unnecessarily permissive firewall rule.", "scenario": "explain how sensitive customer data became publicly accessible even though the storage service itself had no software flaw", "distractors": ["Zero-day vulnerability", "Race condition", "Buffer overflow"], "tip": "INSECURE SETTINGS, not a code flaw — an open storage bucket or overly permissive firewall rule, entirely preventable through correct setup." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-6'><title id='dt-sd2-23-6'>A vulnerability from insecure settings, such as an open storage bucket or overly permissive firewall rule.</title><rect x='20' y='24' width='340' height='60' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='190' y='18' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Cloud storage bucket</text><text x='190' y='48' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>set to PUBLIC by mistake</text><text x='190' y='62' font-size='6.4' fill='var(--red)' text-anchor='middle'>no software flaw involved</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>INSECURE SETTINGS, not a code flaw \u2014 entirely</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>preventable through correct setup.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A vulnerability from insecure settings, such as an open storage bucket or</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>overly permissive firewall rule.</text></svg>"},
    { "id": "sd2-23-7", "core": "core1", "domain": "sd2", "objective": "2.3", "term": "Privilege escalation", "definition": "An attack that exploits a vulnerability to gain a higher level of access than originally granted, moving from a limited account to administrative or root access.", "scenario": "explain how an attacker with a low-privilege user account was able to gain full administrative control of the system", "distractors": ["Buffer overflow (alone)", "Lateral movement (alone)", "Pass the hash (alone)"], "tip": "GAINS HIGHER access than originally granted — often the goal a buffer overflow or other exploit is used to achieve, not a technique itself." , "diagram": "<svg viewBox='0 0 380 205' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-23-7'><title id='dt-sd2-23-7'>Gains HIGHER access than originally granted \u2014 often the goal a buffer overflow or other exploit is used to achieve.</title><rect x='130' y='90' width='120' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='109' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Limited user account</text><rect x='130' y='30' width='120' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='190' y='49' font-size='7.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Admin / root access</text><line x1='190' y1='88' x2='190' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 54 L190 61 L194 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><text x='190' y='132' font-size='7.3' fill='var(--text)' text-anchor='middle'>Exploits a vulnerability to jump from a limited</text><text x='190' y='144' font-size='7.3' fill='var(--text)' text-anchor='middle'>account to full administrative control.</text><text x='16' y='183' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Gains HIGHER access than originally granted \u2014 often the goal a buffer overflow</text><text x='16' y='195' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>or other exploit is used to achieve.</text></svg>"},

    { "id": "sd2-24-1", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Ransomware", "definition": "Malware that encrypts a victim's files and demands payment, typically in cryptocurrency, in exchange for the decryption key.", "scenario": "explain why every file on a shared drive suddenly has a new extension and a ransom note appeared", "distractors": ["Spyware", "Rootkit", "Worm"], "tip": "ENCRYPTS and demands PAYMENT — spyware secretly observes instead, and a worm spreads itself; each malware type has a distinct primary goal." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-1'><title id='dt-sd2-24-1'>Encrypts a victim&#39;s files and demands payment, typically in cryptocurrency, for the decryption key.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>file.docx</text><text x='95' y='64' font-size='6.4' fill='var(--red)' text-anchor='middle'>\u2192 file.docx.locked</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Ransom note</text><text x='285' y='58' font-size='6.2' fill='var(--red)' text-anchor='middle'>pay in crypto for</text><text x='285' y='70' font-size='6.2' fill='var(--red)' text-anchor='middle'>the decryption key</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Encrypts a victim&#39;s files and demands payment, typically in cryptocurrency, for the</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>decryption key.</text></svg>"},
    { "id": "sd2-24-2", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Worm", "definition": "Self-replicating malware that spreads automatically across a network without needing to attach to a host file or require user interaction.", "scenario": "explain how malware spread to every unpatched machine on the network overnight without anyone clicking anything", "distractors": ["Trojan", "Ransomware", "Spyware"], "tip": "SELF-REPLICATES with NO user interaction needed — a Trojan requires the user to voluntarily install it, the key mechanical difference." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-2'><title id='dt-sd2-24-2'>Self-replicating malware that spreads automatically across a network with no user interaction needed.</title><circle cx='80' cy='60' r='22' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='80' y='64' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>PC 1</text><line x1='105' y1='60' x2='149' y2='60' stroke='var(--red)' stroke-width='1.5'/><path d='M147 56 L154 60 L147 64' fill='none' stroke='var(--red)' stroke-width='1.5'/><circle cx='180' cy='60' r='22' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='180' y='64' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>PC 2</text><line x1='205' y1='60' x2='249' y2='60' stroke='var(--red)' stroke-width='1.5'/><path d='M247 56 L254 60 L247 64' fill='none' stroke='var(--red)' stroke-width='1.5'/><circle cx='280' cy='60' r='22' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='280' y='64' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>PC 3</text><text x='190' y='20' font-size='6.6' fill='var(--muted)' text-anchor='middle'>no clicks, no user interaction</text><text x='190' y='104' font-size='7.3' fill='var(--text)' text-anchor='middle'>SELF-REPLICATES automatically \u2014 a Trojan instead</text><text x='190' y='116' font-size='7.3' fill='var(--text)' text-anchor='middle'>requires the user to voluntarily install it.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Self-replicating malware that spreads automatically across a network with no</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>user interaction needed.</text></svg>"},
    { "id": "sd2-24-3", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Rootkit", "definition": "Malware designed to gain and maintain privileged access to a system while actively hiding its own presence from the operating system and security tools.", "scenario": "explain why a compromised system shows no signs of infection to standard antivirus scans despite ongoing suspicious network traffic", "distractors": ["Worm", "Trojan", "Spyware"], "tip": "HIDES itself from the OS and security tools — the stealth/persistence factor is the defining trait, unlike a worm's loud, fast spreading." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-3'><title id='dt-sd2-24-3'>Malware that gains and maintains privileged access while actively hiding its presence from security tools.</title><rect x='20' y='24' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7' fill='var(--muted)' text-anchor='middle' font-weight='700'>Antivirus scan: &quot;clean&quot; (wrong)</text><rect x='140' y='36' width='100' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='190' y='55' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>Hidden from OS</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>HIDES from the OS and security tools \u2014 the stealth/</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>persistence factor, unlike a worm&#39;s loud spreading.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Malware that gains and maintains privileged access while actively hiding its</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>presence from security tools.</text></svg>"},
    { "id": "sd2-24-4", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Trojan", "definition": "Malware disguised as or bundled with legitimate, desirable software, tricking the user into installing it voluntarily.", "scenario": "explain how malware got installed after an employee downloaded what looked like a legitimate free utility", "distractors": ["Worm", "Ransomware", "Rootkit"], "tip": "DISGUISED as legitimate software — requires the user to voluntarily install it, unlike a worm which spreads with no such interaction." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-4'><title id='dt-sd2-24-4'>Malware disguised as or bundled with legitimate software, tricking the user into installing it voluntarily.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>&quot;Free utility&quot;</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>looks legitimate</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>User installs</text><text x='285' y='58' font-size='6.4' fill='var(--red)' text-anchor='middle'>voluntarily</text><text x='285' y='70' font-size='6' fill='var(--red)' text-anchor='middle'>malware bundled inside</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Malware disguised as or bundled with legitimate software, tricking the user into</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>installing it voluntarily.</text></svg>"},
    { "id": "sd2-24-5", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Distributed denial-of-service (DDoS)", "definition": "An attack that overwhelms a target with traffic from many distributed sources simultaneously, making it unavailable to legitimate users.", "scenario": "explain why a public website became completely unreachable during a flood of traffic from thousands of different IP addresses at once", "distractors": ["Denial-of-service (single source)", "On-path attack", "DNS poisoning"], "tip": "MANY distributed sources at once — the coordinated version of a single-source denial-of-service attack." , "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-5'><title id='dt-sd2-24-5'>Overwhelms a target with traffic from many distributed sources simultaneously, making it unavailable.</title><circle cx='50' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='50' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><circle cx='100' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='100' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><circle cx='150' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='150' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><circle cx='200' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='200' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><circle cx='250' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='250' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><circle cx='300' cy='34' r='10' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><line x1='300' y1='44' x2='190' y2='78' stroke='var(--red)' stroke-width='1' stroke-dasharray='2 2'/><text x='190' y='20' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>thousands of distributed IPs</text><rect x='140' y='80' width='100' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='99' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>Website: DOWN</text><text x='190' y='128' font-size='7.3' fill='var(--text)' text-anchor='middle'>MANY distributed sources at once \u2014 the coordinated</text><text x='190' y='140' font-size='7.3' fill='var(--text)' text-anchor='middle'>version of a single-source DoS attack.</text><text x='16' y='168' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Overwhelms a target with traffic from many distributed sources simultaneously,</text><text x='16' y='180' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>making it unavailable.</text></svg>"},
    { "id": "sd2-24-6", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Credential stuffing", "definition": "An attack that uses lists of usernames and passwords leaked from other breaches to automatically try logging into many different accounts, relying on password reuse.", "scenario": "explain how attackers successfully logged into several unrelated accounts using a password list stolen from a different company's breach", "distractors": ["Brute-force attack", "Password spraying", "Rainbow table attack"], "tip": "REUSES leaked credentials from OTHER breaches — relies on password reuse across sites, not on guessing new passwords at all.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-6'><title id='dt-sd2-24-6'>Stuffing reuses KNOWN real passwords; spraying guesses ONE common password broadly — neither is a per-account brute force.</title><text x='90' y='16' font-size='8.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Credential stuffing</text><rect x='20' y='24' width='140' height='28' rx='4' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='90' y='42' font-size='6.5' fill='var(--text)' text-anchor='middle'>Leaked list: many real user:pass pairs</text><line x1='60' y1='52' x2='30' y2='72' stroke='var(--red)' stroke-width='1.2'/><line x1='90' y1='52' x2='90' y2='72' stroke='var(--red)' stroke-width='1.2'/><line x1='120' y1='52' x2='150' y2='72' stroke='var(--red)' stroke-width='1.2'/><text x='30' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>Site A</text><text x='90' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>Site B</text><text x='150' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>Site C</text><text x='90' y='100' font-size='6.5' fill='var(--red)' text-anchor='middle' font-weight='700'>works wherever reused</text><line x1='190' y1='20' x2='190' y2='150' stroke='var(--border)' stroke-width='1'/><text x='290' y='16' font-size='8.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Password spraying</text><rect x='220' y='24' width='140' height='28' rx='4' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='290' y='42' font-size='6.5' fill='var(--text)' text-anchor='middle'>One guessed password: \"Summer2024\"</text><line x1='260' y1='52' x2='230' y2='72' stroke='var(--muted-2)' stroke-width='1.2'/><line x1='290' y1='52' x2='290' y2='72' stroke='var(--muted-2)' stroke-width='1.2'/><line x1='320' y1='52' x2='350' y2='72' stroke='var(--muted-2)' stroke-width='1.2'/><text x='230' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>User 1</text><text x='290' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>User 2</text><text x='350' y='84' font-size='6' fill='var(--muted)' text-anchor='middle'>User 3</text><text x='290' y='100' font-size='6.5' fill='var(--muted)' text-anchor='middle'>same site, many accounts</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)'>Stuffing reuses KNOWN real passwords; spraying guesses ONE</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)'>common password broadly — neither is a per-account brute force.</text></svg>" },
    { "id": "sd2-24-7", "core": "core1", "domain": "sd2", "objective": "2.4", "term": "Password spraying", "definition": "An attack that tries one or a few commonly used passwords against many different user accounts, avoiding account lockouts triggered by repeated failed attempts on a single account.", "scenario": "explain an attack technique that tries one common password against thousands of accounts instead of guessing many passwords against one account", "distractors": ["Credential stuffing", "Brute-force attack", "Dictionary attack on one account"], "tip": "FEW passwords against MANY accounts — the reverse of brute-force, and specifically designed to dodge lockout thresholds." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-24-7'><title id='dt-sd2-24-7'>Tries one or a few common passwords against many accounts, avoiding lockouts from repeated failures.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>&quot;Password123&quot;</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>one common password</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>thousands of</text><text x='285' y='58' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>accounts</text><text x='285' y='70' font-size='5.8' fill='var(--red)' text-anchor='middle'>avoids lockout thresholds</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Tries one or a few common passwords against many accounts, avoiding lockouts from</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>repeated failures.</text></svg>"},

    { "id": "sd2-25-1", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Network segmentation", "definition": "Dividing a network into isolated zones so that a compromise in one segment can't easily spread to others.", "scenario": "limit how far a compromised IoT device on a guest network could reach into the finance department's servers", "distractors": ["Patching", "Least privilege", "Encryption"], "tip": "ISOLATES zones so a breach can't spread — a containment strategy, distinct from patching (fixing flaws) or encryption (protecting data)." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-1'><title id='dt-sd2-25-1'>Dividing a network into isolated zones so a compromise in one segment can&#39;t easily spread to others.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Segmentation</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>divides the WHOLE network</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Isolation</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>contains ONE specific asset</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Dividing a network into isolated zones so a compromise in one segment can&#39;t</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>easily spread to others.</text></svg>"},
    { "id": "sd2-25-2", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Least privilege", "definition": "Granting users and systems only the minimum access necessary to perform their function, reducing the potential damage from a compromised account.", "scenario": "limit the damage a compromised help desk account could do by giving it read-only log access instead of full admin rights", "distractors": ["Network segmentation", "Patch management", "Application allow listing"], "tip": "MINIMUM access necessary — limits damage from a compromised ACCOUNT specifically, a different containment angle than segmenting the network." , "diagram": "<svg viewBox='0 0 380 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-2'><title id='dt-sd2-25-2'>Minimum access necessary \u2014 limits damage from a compromised account specifically, a different angle than segmenting the network.</title><rect x='20' y='24' width='150' height='90' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='3 2'/><text x='95' y='44' font-size='8' fill='var(--red)' text-anchor='middle' font-weight='700'>Full access</text><text x='95' y='60' font-size='6.5' fill='var(--red)' text-anchor='middle'>(everything \u2014</text><text x='95' y='72' font-size='6.5' fill='var(--red)' text-anchor='middle'>not needed)</text><rect x='210' y='24' width='150' height='90' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Least privilege</text><rect x='225' y='58' width='120' height='20' rx='3' fill='var(--surface-2)' stroke='var(--primary)' stroke-width='1.5'/><text x='285' y='71' font-size='6.3' fill='var(--text)' text-anchor='middle'>only what the job needs</text><text x='190' y='132' font-size='7.3' fill='var(--text)' text-anchor='middle'>Limits the blast radius of a single compromised account.</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Minimum access necessary \u2014 limits damage from a compromised account</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>specifically, a different angle than segmenting the network.</text></svg>"},
    { "id": "sd2-25-3", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Application allow listing", "definition": "A security technique that permits only explicitly approved applications to run, blocking everything else by default.", "scenario": "prevent unapproved or malicious executables from ever running on a locked-down finance workstation", "distractors": ["Application block listing", "Antivirus scanning alone", "Sandboxing"], "tip": "PERMITS only approved apps, blocks everything else by DEFAULT — the reverse logic of a block list, which denies only known-bad items." , "diagram": "<svg viewBox='0 0 380 140' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-3'><title id='dt-sd2-25-3'>Permits only approved apps, blocks everything else by default \u2014 the reverse logic of a block list, which denies only known-bad items.</title><rect x='20' y='24' width='150' height='70' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='95' y='42' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Allow listed</text><text x='95' y='60' font-size='7' fill='var(--primary)' text-anchor='middle'>\u2713 Approved app A</text><text x='95' y='76' font-size='7' fill='var(--primary)' text-anchor='middle'>\u2713 Approved app B</text><rect x='210' y='24' width='150' height='70' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='285' y='42' font-size='8' fill='var(--red)' text-anchor='middle' font-weight='700'>Everything else</text><text x='285' y='60' font-size='7' fill='var(--red)' text-anchor='middle'>\u2715 blocked by default</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Permits only approved apps, blocks everything else by default \u2014 the reverse</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>logic of a block list, which denies only known-bad items.</text></svg>"},
    { "id": "sd2-25-4", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Patch management", "definition": "The ongoing process of identifying, testing, and deploying software updates that fix known security vulnerabilities.", "scenario": "systematically close known vulnerabilities across the company's servers before attackers can exploit them", "distractors": ["Configuration enforcement", "Vulnerability scanning alone", "Decommissioning"], "tip": "IDENTIFY, TEST, DEPLOY fixes — a full ongoing process, more than just scanning for vulnerabilities without ever fixing them." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-4'><title id='dt-sd2-25-4'>Identify, test, and deploy fixes \u2014 a full ongoing process, more than just scanning without ever fixing.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='28' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Identify vulnerabilities</text><text x='180.0' y='41' font-size='7.5' fill='var(--muted)' text-anchor='middle'>scanning alone stops here</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='82' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Test the fix</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='120' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Deploy across servers</text><text x='180.0' y='133' font-size='7.5' fill='var(--text)' text-anchor='middle'>closes it before exploitation</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Identify, test, and deploy fixes \u2014 a full ongoing process, more than just</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>scanning without ever fixing.</text></svg>"},
    { "id": "sd2-25-5", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Isolation", "definition": "Separating a system, device, or process from the rest of the network or from other processes, often used to contain a known-risky or already-compromised asset.", "scenario": "keep a legacy machine that can't be patched from having any network path to the rest of the environment", "distractors": ["Segmentation (broad zones)", "Encryption", "Hardening"], "tip": "ONE specific compromised asset — segmentation divides the whole network into zones proactively, isolation reacts to contain a SPECIFIC item." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-5'><title id='dt-sd2-25-5'>Separating a system or device from the rest of the network, often to contain a risky or compromised asset.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Legacy machine</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>can&#39;t be patched</text><text x='190' y='44' font-size='6.4' fill='var(--muted)' text-anchor='middle' font-weight='700'>NO network path</text><rect x='210' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Rest of network</text><text x='285' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>fully separated</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>ONE specific asset contained \u2014 segmentation instead</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>proactively divides the whole network into zones.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Separating a system or device from the rest of the network, often to contain a risky</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>or compromised asset.</text></svg>"},
    { "id": "sd2-25-6", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Configuration enforcement", "definition": "The practice of automatically ensuring systems remain compliant with an approved secure baseline configuration, correcting drift when it occurs.", "scenario": "automatically detect and fix a server that drifted away from the company's required secure settings", "distractors": ["Patch management", "Decommissioning", "Application allow listing"], "tip": "AUTOMATICALLY corrects DRIFT from a secure baseline — an ongoing enforcement loop, distinct from patch management's focus on known vulnerabilities." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-6'><title id='dt-sd2-25-6'>Automatically corrects drift from a secure baseline \u2014 an ongoing loop, distinct from patch management&#39;s focus on known flaws.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='28' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Server drifts from baseline</text><text x='180.0' y='41' font-size='7.5' fill='var(--muted)' text-anchor='middle'>insecure setting creeps in</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Enforcement detects drift</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>automatically</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Setting corrected</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>back to compliant</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Automatically corrects drift from a secure baseline \u2014 an ongoing loop,</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>distinct from patch management&#39;s focus on known flaws.</text></svg>"},
    { "id": "sd2-25-7", "core": "core1", "domain": "sd2", "objective": "2.5", "term": "Decommissioning", "definition": "Formally retiring a system or asset and removing its access, accounts, and data so it can no longer be exploited as an unmonitored risk.", "scenario": "make sure an old server that's no longer used can't still be quietly exploited as a forgotten backdoor", "distractors": ["Isolation", "Patch management", "Segmentation"], "tip": "FULLY RETIRES an asset — removes it entirely, unlike isolation which keeps a risky asset around but separated." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd2-25-7'><title id='dt-sd2-25-7'>Formally retiring a system and removing its access, accounts, and data so it can&#39;t be exploited as a forgotten risk.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Decommissioning</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>FULLY retires the asset</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Isolation</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>keeps it, but separated</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Formally retiring a system and removing its access, accounts, and data so it</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>can&#39;t be exploited as a forgotten risk.</text></svg>"},

    { "id": "sd3-31-1", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "Shared responsibility model", "definition": "A cloud security framework defining which security tasks the cloud provider handles and which remain the customer's responsibility, varying by service model.", "scenario": "determine whether the cloud provider or the customer is responsible for patching the guest operating system on a rented virtual machine", "distractors": ["Zero trust model", "Defense in depth", "Least privilege"], "tip": "WHO handles WHAT security task — varies by service model (IaaS/PaaS/SaaS), a cloud-specific division of labor, not a general strategy." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-1'><title id='dt-sd3-31-1'>Defines which security tasks the cloud provider handles vs. what remains the customer&#39;s responsibility.</title><rect x='20' y='24' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7' fill='var(--muted)' text-anchor='middle'>Rented VM (IaaS)</text><rect x='40' y='40' width='130' height='30' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='105' y='59' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>Provider: hardware</text><rect x='210' y='40' width='130' height='30' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='275' y='59' font-size='6.4' fill='var(--blue)' text-anchor='middle' font-weight='700'>Customer: guest OS</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>WHO handles WHAT \u2014 varies by service model</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>(IaaS/PaaS/SaaS), a cloud-specific division of labor.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines which security tasks the cloud provider handles vs. what remains the</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>customer&#39;s responsibility.</text></svg>"},
    { "id": "sd3-31-2", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "Infrastructure as code (IaC)", "definition": "The practice of defining and provisioning infrastructure using machine-readable configuration files rather than manual setup, enabling consistent, repeatable, and auditable deployments.", "scenario": "consistently deploy identical, security-hardened server configurations across dozens of cloud environments using version-controlled templates", "distractors": ["Shared responsibility model", "Virtualization", "Containerization"], "tip": "CONFIG FILES define infrastructure — repeatable and auditable, distinct from virtualization/containerization which are about HOW workloads run." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-2'><title id='dt-sd3-31-2'>Defining and provisioning infrastructure using machine-readable config files instead of manual setup.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Config file</text><text x='95' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>version-controlled</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='44' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Dozens of</text><text x='285' y='58' font-size='6.2' fill='var(--muted)' text-anchor='middle'>identical, hardened</text><text x='285' y='70' font-size='6.2' fill='var(--muted)' text-anchor='middle'>environments</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defining and provisioning infrastructure using machine-readable config files instead</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>of manual setup.</text></svg>"},
    { "id": "sd3-31-3", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "Containerization", "definition": "A virtualization approach that packages an application with its dependencies into a lightweight, portable unit that shares the host operating system's kernel.", "scenario": "package and deploy an application consistently across environments without the overhead of a full separate operating system for each instance", "distractors": ["Virtualization (full VM)", "Sandboxing", "Serverless computing"], "tip": "SHARES the host OS kernel — much lighter than a full VM, which virtualizes an entire separate guest OS." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-3'><title id='dt-sd3-31-3'>Packages an app with its dependencies but shares the host OS kernel \u2014 much lighter than a full VM&#39;s separate guest OS.</title><text x='95' y='16' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Virtual machine</text><rect x='20' y='26' width='150' height='100' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><rect x='30' y='34' width='130' height='22' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='95' y='49' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>App</text><rect x='30' y='62' width='130' height='22' rx='3' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='95' y='77' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Guest OS</text><rect x='30' y='90' width='130' height='22' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='95' y='105' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Hypervisor</text><text x='285' y='16' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Container</text><rect x='210' y='26' width='150' height='100' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><rect x='220' y='34' width='130' height='22' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='285' y='49' font-size='7' fill='var(--text)' text-anchor='middle'>App + dependencies</text><rect x='220' y='62' width='130' height='22' rx='3' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='285' y='77' font-size='6.8' fill='var(--text)' text-anchor='middle' font-weight='700'>Shared host OS kernel</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Packages an app with its dependencies but shares the host OS kernel \u2014 much</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>lighter than a full VM&#39;s separate guest OS.</text></svg>"},
    { "id": "sd3-31-4", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "Industrial control system (ICS) / SCADA", "definition": "Specialized hardware and software used to monitor and control physical industrial processes, such as power grids or manufacturing equipment, often prioritizing availability over confidentiality.", "scenario": "explain the security priorities for the system controlling a water treatment plant's physical valves and pumps", "distractors": ["IoT device", "Embedded system (generic)", "RTOS"], "tip": "PHYSICAL industrial processes — availability often trumps confidentiality here, the opposite priority from typical IT security." , "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-4'><title id='dt-sd3-31-4'>Physical industrial processes \u2014 availability often trumps confidentiality here, the opposite priority from typical IT security.</title><text x='95' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Typical IT priority</text><rect x='30' y='30' width='90' height='14' rx='2' fill='var(--primary)' fill-opacity='0.4' stroke='var(--primary)' stroke-width='1.5'/><text x='20' y='41' font-size='6' fill='var(--muted)' text-anchor='end'>Conf</text><rect x='30' y='50' width='70' height='14' rx='2' fill='var(--blue)' fill-opacity='0.4' stroke='var(--blue)' stroke-width='1.5'/><text x='20' y='61' font-size='6' fill='var(--muted)' text-anchor='end'>Inte</text><rect x='30' y='70' width='50' height='14' rx='2' fill='var(--muted)' fill-opacity='0.4' stroke='var(--muted)' stroke-width='1.5'/><text x='20' y='81' font-size='6' fill='var(--muted)' text-anchor='end'>Avai</text><text x='285' y='18' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>ICS / SCADA priority</text><rect x='220' y='30' width='90' height='14' rx='2' fill='var(--primary)' fill-opacity='0.4' stroke='var(--primary)' stroke-width='1.5'/><text x='210' y='41' font-size='6' fill='var(--muted)' text-anchor='end'>Avai</text><rect x='220' y='50' width='70' height='14' rx='2' fill='var(--blue)' fill-opacity='0.4' stroke='var(--blue)' stroke-width='1.5'/><text x='210' y='61' font-size='6' fill='var(--muted)' text-anchor='end'>Inte</text><rect x='220' y='70' width='40' height='14' rx='2' fill='var(--muted)' fill-opacity='0.4' stroke='var(--muted)' stroke-width='1.5'/><text x='210' y='81' font-size='6' fill='var(--muted)' text-anchor='end'>Conf</text><text x='190' y='108' font-size='7.3' fill='var(--text)' text-anchor='middle'>Keeping the power grid or the assembly line running</text><text x='190' y='120' font-size='7.3' fill='var(--text)' text-anchor='middle'>often outweighs secrecy concerns here.</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Physical industrial processes \u2014 availability often trumps confidentiality here,</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the opposite priority from typical IT security.</text></svg>"},
    { "id": "sd3-31-5", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "Real-time operating system (RTOS)", "definition": "An operating system designed to process inputs and produce outputs within a strict, guaranteed time constraint, commonly used in industrial and embedded control systems.", "scenario": "choose an operating system for a system where a delayed response could cause physical equipment damage", "distractors": ["General-purpose OS", "ICS/SCADA (the broader system)", "Embedded system (generic)"], "tip": "GUARANTEED timing — the OS itself, not the broader industrial system (ICS/SCADA) that might run on top of it." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-5'><title id='dt-sd3-31-5'>Processes inputs/outputs within a strict, guaranteed time constraint, common in industrial control systems.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>RTOS</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>GUARANTEED response time</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>General-purpose OS</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>best-effort timing</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Processes inputs/outputs within a strict, guaranteed time constraint, common in</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>industrial control systems.</text></svg>"},
    { "id": "sd3-31-6", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "High availability", "definition": "An architecture design goal of minimizing downtime through redundancy, such as clustering, failover, and load balancing, so a single component failure doesn't take down the service.", "scenario": "design a system so that one server failing doesn't take the entire application offline", "distractors": ["Disaster recovery (site-level)", "Backup strategy", "Fault tolerance (single-component only)"], "tip": "REDUNDANCY within normal operations — disaster recovery is the broader SITE-LEVEL plan for catastrophic loss, a bigger scope than HA alone." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-6'><title id='dt-sd3-31-6'>Minimizes downtime through redundancy like clustering, failover, and load balancing.</title><rect x='30' y='30' width='90' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='75' y='50' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>Server A</text><text x='75' y='64' font-size='6.4' fill='var(--red)' text-anchor='middle'>\u2715 fails</text><rect x='140' y='30' width='90' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='185' y='50' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Server B</text><text x='185' y='64' font-size='6' fill='var(--primary)' text-anchor='middle'>\u2713 takes over</text><rect x='250' y='30' width='90' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='295' y='50' font-size='6.6' fill='var(--primary)' text-anchor='middle' font-weight='700'>App: ONLINE</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>REDUNDANCY within normal ops \u2014 disaster recovery is</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>the broader SITE-LEVEL plan for catastrophic loss.</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Minimizes downtime through redundancy like clustering, failover, and load balancing.</text></svg>"},
    { "id": "sd3-31-7", "core": "core1", "domain": "sd3", "objective": "3.1", "term": "On-premises vs cloud architecture", "definition": "On-premises architecture is hosted and physically controlled within an organization's own facilities, while cloud architecture is hosted on a third-party provider's infrastructure and accessed over the network.", "scenario": "decide whether a highly regulated system with strict physical control requirements should stay in the company's own data center", "distractors": ["Centralized vs decentralized", "Containerization vs virtualization", "Hybrid vs multi-cloud"], "tip": "WHO physically controls the infrastructure — the core distinction, unrelated to how centralized management is or what virtualization tech runs on top." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-31-7'><title id='dt-sd3-31-7'>On-premises is hosted within an org&#39;s own facilities; cloud is hosted on a third-party provider&#39;s infrastructure.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>On-premises</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>org PHYSICALLY controls it</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Cloud</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>third-party hosted</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>On-premises is hosted within an org&#39;s own facilities; cloud is hosted on a</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>third-party provider&#39;s infrastructure.</text></svg>"},

    { "id": "sd3-32-1", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Security zone", "definition": "A logical grouping of network resources with a defined trust level, such as a DMZ or internal trusted zone, used to control what traffic can flow between zones.", "scenario": "define which traffic is allowed to pass between a public-facing web server area and the internal trusted network", "distractors": ["VLAN (generic segmentation)", "Attack surface", "Air gap"], "tip": "TRUST LEVEL grouping — a VLAN is just generic Layer 2 segmentation, it doesn't inherently imply a trust boundary the way this does." , "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-1'><title id='dt-sd3-32-1'>A trust-level grouping \u2014 a VLAN is just generic Layer 2 segmentation, it doesn&#39;t inherently imply a trust boundary like this.</title><rect x='20' y='30' width='110' height='60' rx='6' fill='var(--surface-2)' stroke='var(--red)' stroke-width='1.6'/><text x='75' y='52' font-size='8.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Untrusted</text><text x='75' y='70' font-size='6.8' fill='var(--muted)' text-anchor='middle'>Internet</text><rect x='142' y='30' width='110' height='60' rx='6' fill='var(--surface-2)' stroke='var(--amber)' stroke-width='1.6'/><text x='197' y='52' font-size='8.5' fill='var(--amber)' text-anchor='middle' font-weight='700'>DMZ</text><text x='197' y='70' font-size='6.8' fill='var(--muted)' text-anchor='middle'>public servers</text><rect x='264' y='30' width='110' height='60' rx='6' fill='var(--surface-2)' stroke='var(--primary)' stroke-width='1.6'/><text x='319' y='52' font-size='8.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Trusted</text><text x='319' y='70' font-size='6.8' fill='var(--muted)' text-anchor='middle'>internal LAN</text><text x='190' y='108' font-size='7.3' fill='var(--text)' text-anchor='middle'>Each zone carries a defined trust level, controlling what</text><text x='190' y='120' font-size='7.3' fill='var(--text)' text-anchor='middle'>traffic is allowed to flow between them.</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A trust-level grouping \u2014 a VLAN is just generic Layer 2 segmentation, it</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>doesn&#39;t inherently imply a trust boundary like this.</text></svg>"},
    { "id": "sd3-32-2", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Demilitarized zone (DMZ)", "definition": "A network segment that hosts public-facing servers, positioned so that a compromise there doesn't directly expose the internal trusted network.", "scenario": "host a public web server so that if it's compromised, the attacker still can't directly reach internal file servers", "distractors": ["Security zone (generic)", "Air gap", "Screened host bastion (a related but distinct concept)"], "tip": "A SPECIFIC kind of security zone for public-facing servers — a security zone is the broader category, this is one specific example of it.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-2'><title id='dt-sd3-32-2'>The DMZ is ONE specific zone type \u2014 \"security zone\" is the general term.</title><rect x='16' y='16' width='348' height='150' rx='8' fill='none' stroke='var(--border)' stroke-width='1.3' stroke-dasharray='4 3'/><text x='190' y='32' font-size='7.5' fill='var(--muted)' text-anchor='middle'>Security zones (the broader category)</text><rect x='34' y='50' width='90' height='90' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='79' y='90' font-size='7.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Untrusted</text><text x='79' y='103' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Internet</text><rect x='145' y='50' width='90' height='90' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='190' y='90' font-size='7.5' fill='var(--amber)' text-anchor='middle' font-weight='700'>DMZ</text><text x='190' y='103' font-size='6.5' fill='var(--text)' text-anchor='middle'>public server</text><text x='190' y='114' font-size='6.5' fill='var(--text)' text-anchor='middle'>lives here</text><rect x='256' y='50' width='90' height='90' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.3'/><text x='301' y='90' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Trusted</text><text x='301' y='103' font-size='6.5' fill='var(--muted)' text-anchor='middle'>internal LAN</text><text x='16' y='182' font-size='8.5' fill='var(--muted-2)'>The DMZ is ONE specific zone type \u2014 \"security zone\" is the general term.</text></svg>" },
    { "id": "sd3-32-3", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Inline vs tap/monitor device placement", "definition": "An inline device sits directly in the traffic path and can actively block traffic, while a tap or monitor-mode device only receives a copy of traffic and can observe but not block it.", "scenario": "choose a device placement that can actually block malicious traffic in real time rather than just observe it", "distractors": ["Active vs passive scanning", "Centralized vs decentralized", "North-south vs east-west traffic"], "tip": "Can it BLOCK, or only WATCH — inline sits in the path and can act, a tap only sees a copy and can never intervene.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-3'><title id='dt-sd3-32-3'>An inline device sits directly in the traffic path and can actively block traffic, while a tap or monitor-mode device only receives a copy of traffic and can observe but not block it.</title><text x='16' y='18' font-size='8' fill='var(--muted)' font-weight='700'>Inline — sits IN the path</text><rect x='16' y='24' width='60' height='24' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='46' y='40' font-size='6.5' fill='var(--text)' text-anchor='middle'>Traffic</text><line x1='76' y1='36' x2='120' y2='36' stroke='var(--primary)' stroke-width='1.5'/><rect x='120' y='24' width='80' height='24' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='160' y='40' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>IPS device</text><line x1='200' y1='36' x2='244' y2='36' stroke='var(--primary)' stroke-width='1.5'/><rect x='244' y='24' width='70' height='24' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='279' y='40' font-size='6.5' fill='var(--text)' text-anchor='middle'>Destination</text><text x='330' y='40' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>can block</text><text x='16' y='84' font-size='8' fill='var(--muted)' font-weight='700'>Tap — sits BESIDE the path</text><rect x='16' y='90' width='60' height='24' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='46' y='106' font-size='6.5' fill='var(--text)' text-anchor='middle'>Traffic</text><line x1='76' y1='102' x2='260' y2='102' stroke='var(--muted)' stroke-width='1.5'/><rect x='260' y='90' width='70' height='24' rx='3' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.2'/><text x='295' y='106' font-size='6.5' fill='var(--text)' text-anchor='middle'>Destination</text><line x1='140' y1='108' x2='140' y2='134' stroke='var(--muted-2)' stroke-width='1.2' stroke-dasharray='2 2'/><rect x='105' y='134' width='70' height='24' rx='3' fill='var(--surface-2)' stroke='var(--muted-2)' stroke-width='1.3'/><text x='140' y='150' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Tap (copy only)</text><text x='245' y='128' font-size='7' fill='var(--muted)' text-anchor='middle' font-weight='700'>observe only, never blocks</text></svg>" },
    { "id": "sd3-32-4", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Intrusion prevention system (IPS)", "definition": "An inline security appliance that actively monitors and can automatically block or drop traffic matching known malicious patterns.", "scenario": "automatically drop packets matching a known exploit signature before they reach the target server", "distractors": ["Intrusion detection system (IDS)", "Firewall (basic packet filter)", "Load balancer"], "tip": "INLINE and ACTIVE — blocks in real time, unlike IDS which only watches and alerts after the fact." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-4'><title id='dt-sd3-32-4'>An inline appliance that actively monitors and can automatically block traffic matching malicious patterns.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>IPS</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>INLINE, actively BLOCKS</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>IDS</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>watches &amp; alerts only</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An inline appliance that actively monitors and can automatically block traffic</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>matching malicious patterns.</text></svg>"},
    { "id": "sd3-32-5", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Web application firewall (WAF)", "definition": "A firewall specifically designed to filter, monitor, and block HTTP/HTTPS traffic to and from a web application, protecting against attacks like SQL injection and XSS.", "scenario": "protect a public web application specifically from SQL injection and cross-site scripting attempts embedded in HTTP requests", "distractors": ["Network firewall (generic)", "Intrusion detection system", "Load balancer"], "tip": "HTTP/HTTPS traffic specifically — a generic network firewall filters by port/protocol broadly, this understands attacks like SQLi and XSS." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-5'><title id='dt-sd3-32-5'>HTTP/HTTPS traffic specifically \u2014 a generic network firewall filters by port/protocol broadly, this understands attacks like SQLi and XSS.</title><rect x='20' y='40' width='90' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='65' y='57' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Web client</text><line x1='115' y1='53' x2='154' y2='53' stroke='var(--muted)' stroke-width='1.5'/><path d='M152 49 L159 53 L152 57' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='160' y='30' width='100' height='46' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='210' y='48' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>WAF</text><text x='210' y='62' font-size='6.5' fill='var(--muted)' text-anchor='middle'>inspects HTTP/S</text><line x1='260' y1='53' x2='299' y2='53' stroke='var(--muted)' stroke-width='1.5'/><path d='M297 49 L304 53 L297 57' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='305' y='40' width='70' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='340' y='57' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Web app</text><text x='190' y='95' font-size='7.3' fill='var(--text)' text-anchor='middle'>Understands SQL injection and XSS patterns \u2014</text><text x='190' y='107' font-size='7.3' fill='var(--text)' text-anchor='middle'>a generic firewall only filters by port/protocol.</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>HTTP/HTTPS traffic specifically \u2014 a generic network firewall filters by</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>port/protocol broadly, this understands attacks like SQLi and XSS.</text></svg>"},
    { "id": "sd3-32-6", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Jump server", "definition": "A hardened, tightly controlled server used as an intermediary access point for administrators to reach other systems in a sensitive network zone.", "scenario": "require administrators to pass through one tightly monitored, hardened host before reaching production database servers", "distractors": ["Reverse proxy for public traffic", "Load balancer", "Proxy server (generic web proxy)"], "tip": "For ADMINISTRATORS reaching sensitive systems — a reverse proxy instead serves PUBLIC traffic inbound to a web app, opposite direction and audience." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-6'><title id='dt-sd3-32-6'>For administrators reaching sensitive systems \u2014 a reverse proxy instead serves public traffic inbound, opposite direction and audience.</title><rect x='20' y='40' width='90' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='65' y='57' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Admin</text><line x1='115' y1='53' x2='159' y2='53' stroke='var(--muted)' stroke-width='1.5'/><path d='M157 49 L164 53 L157 57' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='165' y='30' width='90' height='46' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='210' y='48' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Jump server</text><text x='210' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>hardened, logged</text><line x1='255' y1='53' x2='294' y2='53' stroke='var(--muted)' stroke-width='1.5'/><path d='M292 49 L299 53 L292 57' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='300' y='20' width='70' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='335' y='33' font-size='6.5' fill='var(--text)' text-anchor='middle'>Server A</text><rect x='300' y='66' width='70' height='20' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='335' y='79' font-size='6.5' fill='var(--text)' text-anchor='middle'>Server B</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>The one controlled doorway into a sensitive zone \u2014</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>nobody reaches those servers directly.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>For administrators reaching sensitive systems \u2014 a reverse proxy instead serves</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>public traffic inbound, opposite direction and audience.</text></svg>"},
    { "id": "sd3-32-7", "core": "core1", "domain": "sd3", "objective": "3.2", "term": "Port security", "definition": "A switch feature that restricts which MAC addresses are allowed to communicate through a given port, disabling or restricting it if an unauthorized device appears.", "scenario": "prevent an unauthorized laptop from getting network access by simply plugging into an open wall jack", "distractors": ["802.1X (certificate-based)", "VLAN segmentation", "Firewall ACL"], "tip": "MAC-address allow-list per port — 802.1X is a stronger, certificate-based authentication instead, a higher bar than just checking a MAC address." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-32-7'><title id='dt-sd3-32-7'>A switch feature restricting which MAC addresses may communicate through a given port.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Unknown laptop</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>plugs into wall jack</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Unknown MAC</text><text x='285' y='58' font-size='6.4' fill='var(--red)' text-anchor='middle'>\u2715 port disabled</text><text x='285' y='70' font-size='6.4' fill='var(--red)' text-anchor='middle'>automatically</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A switch feature restricting which MAC addresses may communicate through a given</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>port.</text></svg>"},

    { "id": "sd3-33-1", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data at rest", "definition": "Data that is stored on a physical or virtual medium, such as a hard drive or database, and not actively moving across a network.", "scenario": "choose the right encryption approach for confidential files sitting on a server's hard drive", "distractors": ["Data in transit", "Data in use", "Data in processing"], "tip": "STORED, not moving — encryption at rest protects a stolen drive; it does nothing for data actively crossing a network.", "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-1'><title id='dt-sd3-33-1'>Encrypting a stolen drive protects data at rest — it does nothing for the same data actively moving across a network.</title><defs><marker id='sp-data-arrow' markerWidth='7' markerHeight='7' refX='6' refY='3.5' orient='auto'><path d='M0 0 L7 3.5 L0 7 Z' fill='var(--muted)'/></marker></defs><rect x='10' y='40' width='106' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='63' y='62' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>At rest</text><text x='63' y='76' font-size='6.5' fill='var(--muted)' text-anchor='middle'>On disk / database</text><text x='63' y='88' font-size='6' fill='var(--muted)' text-anchor='middle'>protect: disk encryption</text><line x1='116' y1='70' x2='142' y2='70' stroke='var(--muted)' stroke-width='1.3' marker-end='url(#sp-data-arrow)'/><rect x='142' y='40' width='106' height='60' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='195' y='62' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>In transit</text><text x='195' y='76' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Crossing the network</text><text x='195' y='88' font-size='6' fill='var(--muted)' text-anchor='middle'>protect: TLS</text><line x1='248' y1='70' x2='274' y2='70' stroke='var(--muted)' stroke-width='1.3' marker-end='url(#sp-data-arrow)'/><rect x='274' y='40' width='96' height='60' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='322' y='62' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>In use</text><text x='322' y='76' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Active in memory</text><text x='322' y='88' font-size='6' fill='var(--muted)' text-anchor='middle'>hardest to protect</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)'>Encrypting a stolen drive protects data at rest — it does</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)'>nothing for the same data actively moving across a network.</text></svg>" },
    { "id": "sd3-33-2", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data in transit", "definition": "Data actively moving across a network between systems, such as during a file upload or an API call.", "scenario": "protect customer information as it travels from a user's browser to a web server", "distractors": ["Data at rest", "Data in use", "Data sovereignty"], "tip": "MOVING across a network — TLS is the typical protection here, a different mechanism than at-rest disk encryption." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-2'><title id='dt-sd3-33-2'>Moving across a network \u2014 TLS is the typical protection here, distinct from at-rest disk encryption or in-memory exposure.</title><rect x='30' y='24' width='100' height='70' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='80' y='46' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>At rest</text><text x='80' y='62' font-size='6.8' fill='var(--muted)' text-anchor='middle'>On disk / database</text><text x='80' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>protect:</text><text x='80' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>disk encryption</text><rect x='146' y='24' width='100' height='70' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='196' y='46' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>In transit</text><text x='196' y='62' font-size='6.8' fill='var(--text)' text-anchor='middle'>Crossing the network</text><text x='196' y='82' font-size='6.5' fill='var(--text)' text-anchor='middle'>protect:</text><text x='196' y='92' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>TLS</text><rect x='262' y='24' width='100' height='70' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='312' y='46' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>In use</text><text x='312' y='62' font-size='6.8' fill='var(--muted)' text-anchor='middle'>Active in memory</text><text x='312' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>protect:</text><text x='312' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>hardest to protect</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Moving across a network \u2014 TLS is the typical protection here, distinct from</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>at-rest disk encryption or in-memory exposure.</text></svg>"},
    { "id": "sd3-33-3", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data in use", "definition": "Data actively being processed in a system's memory, such as during a calculation, making it potentially exposed even if encrypted at rest and in transit.", "scenario": "explain why sensitive data could still be exposed in memory even though it's fully encrypted on disk and during transfer", "distractors": ["Data at rest", "Data in transit", "Data masking"], "tip": "In MEMORY being processed — potentially exposed even with strong at-rest and in-transit encryption, since it must be decrypted to be used." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-3'><title id='dt-sd3-33-3'>Active in memory being processed \u2014 potentially exposed even with strong at-rest and in-transit encryption, since it must be decrypted to be used.</title><rect x='30' y='24' width='100' height='70' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='80' y='46' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>At rest</text><text x='80' y='62' font-size='6.8' fill='var(--muted)' text-anchor='middle'>On disk / database</text><text x='80' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>protect:</text><text x='80' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>disk encryption</text><rect x='146' y='24' width='100' height='70' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='196' y='46' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>In transit</text><text x='196' y='62' font-size='6.8' fill='var(--muted)' text-anchor='middle'>Crossing the network</text><text x='196' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>protect:</text><text x='196' y='92' font-size='6.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>TLS</text><rect x='262' y='24' width='100' height='70' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='312' y='46' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>In use</text><text x='312' y='62' font-size='6.8' fill='var(--text)' text-anchor='middle'>Active in memory</text><text x='312' y='82' font-size='6.5' fill='var(--text)' text-anchor='middle'>protect:</text><text x='312' y='92' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>hardest to protect</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Active in memory being processed \u2014 potentially exposed even with strong at-rest</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>and in-transit encryption, since it must be decrypted to be used.</text></svg>"},
    { "id": "sd3-33-4", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data masking", "definition": "A technique that obscures original data values, such as showing only the last four digits of a credit card, while preserving the data's format for testing or display purposes.", "scenario": "let customer service reps see enough of a card number to confirm identity without ever exposing the full number", "distractors": ["Tokenization", "Encryption", "Data classification"], "tip": "OBSCURES but keeps the FORMAT — showing only last 4 digits, useful for testing/display; tokenization swaps in a completely unrelated value." , "diagram": "<svg viewBox='0 0 380 145' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-4'><title id='dt-sd3-33-4'>Obscures but keeps the format \u2014 showing only the last 4 digits, useful for testing/display; tokenization swaps in an unrelated value.</title><text x='95' y='16' font-size='7' fill='var(--muted)' text-anchor='middle' font-family='monospace'>Original: 4111 2222 3333 4444</text><rect x='20' y='26' width='150' height='34' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='40' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Masking</text><text x='95' y='53' font-size='7' fill='var(--text)' text-anchor='middle' font-family='monospace'>**** **** **** 4444</text><rect x='210' y='26' width='150' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='285' y='40' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Tokenization</text><text x='285' y='53' font-size='7' fill='var(--text)' text-anchor='middle' font-family='monospace'>tok_9f8e7d6c</text><text x='190' y='88' font-size='7.3' fill='var(--text)' text-anchor='middle'>Masking keeps the FORMAT and shows partial real data \u2014</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>tokenization swaps in a value with no meaning on its own.</text><text x='16' y='123' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Obscures but keeps the format \u2014 showing only the last 4 digits, useful for</text><text x='16' y='135' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>testing/display; tokenization swaps in an unrelated value.</text></svg>"},
    { "id": "sd3-33-5", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Tokenization", "definition": "Replacing sensitive data with a non-sensitive placeholder token that has no exploitable value on its own, with the real data stored securely elsewhere and mapped back only when needed.", "scenario": "let a payment processor handle transactions without ever storing the customer's actual credit card number", "distractors": ["Data masking", "Hashing", "Encryption"], "tip": "A PLACEHOLDER with no exploitable value on its own — the real data lives elsewhere entirely, unlike masking which just partially obscures it." , "diagram": "<svg viewBox='0 0 380 145' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-5'><title id='dt-sd3-33-5'>A placeholder with no exploitable value on its own \u2014 the real data lives elsewhere entirely, unlike masking&#39;s partial obscuring.</title><text x='95' y='16' font-size='7' fill='var(--muted)' text-anchor='middle' font-family='monospace'>Original: 4111 2222 3333 4444</text><rect x='20' y='26' width='150' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='95' y='40' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Masking</text><text x='95' y='53' font-size='7' fill='var(--text)' text-anchor='middle' font-family='monospace'>**** **** **** 4444</text><rect x='210' y='26' width='150' height='34' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='40' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Tokenization</text><text x='285' y='53' font-size='7' fill='var(--text)' text-anchor='middle' font-family='monospace'>tok_9f8e7d6c</text><text x='190' y='88' font-size='7.3' fill='var(--text)' text-anchor='middle'>Masking keeps the FORMAT and shows partial real data \u2014</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>tokenization swaps in a value with no meaning on its own.</text><text x='16' y='123' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A placeholder with no exploitable value on its own \u2014 the real data lives</text><text x='16' y='135' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>elsewhere entirely, unlike masking&#39;s partial obscuring.</text></svg>"},
    { "id": "sd3-33-6", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data loss prevention (DLP)", "definition": "A technology or process that monitors, detects, and blocks sensitive data from leaving an organization's control, such as through email or removable media.", "scenario": "automatically block an email from being sent externally because it contains what looks like unencrypted credit card numbers", "distractors": ["Data classification", "Data masking", "Access control list"], "tip": "MONITORS and BLOCKS data leaving the org — classification labels sensitivity first, this then acts on those labels to prevent exfiltration." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-6'><title id='dt-sd3-33-6'>Monitors and blocks data leaving the org \u2014 classification labels sensitivity first, this then acts on those labels to prevent exfiltration.</title><rect x='20' y='40' width='90' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='65' y='57' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Employee</text><line x1='115' y1='53' x2='159' y2='53' stroke='var(--muted)' stroke-width='1.5'/><path d='M157 49 L164 53 L157 57' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='165' y='30' width='90' height='46' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='210' y='48' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DLP</text><text x='210' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>scans outbound</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>Blocks sensitive data \u2014 SSNs, card numbers \u2014</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>from leaving via email or removable media.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Monitors and blocks data leaving the org \u2014 classification labels sensitivity</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>first, this then acts on those labels to prevent exfiltration.</text></svg>"},
    { "id": "sd3-33-7", "core": "core1", "domain": "sd3", "objective": "3.3", "term": "Data sovereignty", "definition": "The concept that data is subject to the laws and regulations of the country in which it is physically stored or collected.", "scenario": "determine which country's privacy laws apply to customer data stored in a cloud data center located overseas", "distractors": ["Data classification", "Geolocation restriction (a technical control)", "Data residency policy (an organizational choice)"], "tip": "LEGAL jurisdiction based on physical STORAGE location — a residency policy is the org's own CHOICE about where to store data; this is the external legal reality driving it." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-33-7'><title id='dt-sd3-33-7'>Data is subject to the laws of the country in which it is physically stored or collected.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Data center</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>physically overseas</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>That country&#39;s</text><text x='285' y='58' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>LAWS apply</text><text x='285' y='70' font-size='6.2' fill='var(--primary)' text-anchor='middle'>to the data</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Data is subject to the laws of the country in which it is physically stored or</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>collected.</text></svg>"},

    { "id": "sd3-34-1", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Hot site", "definition": "A fully equipped, ready-to-run disaster recovery facility with live data replication, allowing near-immediate failover with minimal downtime.", "scenario": "fail over critical services to a backup facility within minutes of a primary data center outage", "distractors": ["Warm site", "Cold site", "Mirror backup only"], "tip": "LIVE replication, near-INSTANT failover — the fastest and most expensive of the DR site tiers." , "diagram": "<svg viewBox='0 0 380 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-1'><title id='dt-sd3-34-1'>Same spectrum: recovery speed trades directly against cost \u2014 a hot site is fastest and priciest, a cold site the opposite.</title><rect x='20' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--green)' stroke-width='2.2'/><text x='75' y='40' font-size='9' fill='var(--green)' text-anchor='middle' font-weight='700'>Hot site</text><text x='75' y='58' font-size='6.5' fill='var(--green)' text-anchor='middle'>Live replication</text><text x='75' y='72' font-size='6.5' fill='var(--green)' text-anchor='middle'>Failover in minutes</text><text x='75' y='86' font-size='6.5' fill='var(--green)' text-anchor='middle'>Most expensive</text><rect x='140' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='195' y='40' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Warm site</text><text x='195' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Partial / periodic data</text><text x='195' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Failover in hours</text><text x='195' y='86' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Moderate cost</text><rect x='260' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='315' y='40' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Cold site</text><text x='315' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Empty facility</text><text x='315' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Failover in days</text><text x='315' y='86' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Least expensive</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Same spectrum: recovery speed trades directly against cost \u2014 a hot site is</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>fastest and priciest, a cold site the opposite.</text></svg>"},
    { "id": "sd3-34-2", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Warm site", "definition": "A partially equipped disaster recovery facility with hardware in place but requiring some data restoration and configuration before becoming operational.", "scenario": "recover operations at a backup facility within a day, using hardware that's already installed but needs data restored", "distractors": ["Hot site", "Cold site", "Reciprocal agreement"], "tip": "Hardware READY, data needs restoring — the middle tier between hot (instant) and cold (slowest)." , "diagram": "<svg viewBox='0 0 380 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-2'><title id='dt-sd3-34-2'>Same spectrum: recovery speed trades directly against cost \u2014 a hot site is fastest and priciest, a cold site the opposite.</title><rect x='20' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='40' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Hot site</text><text x='75' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Live replication</text><text x='75' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Failover in minutes</text><text x='75' y='86' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Most expensive</text><rect x='140' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--amber)' stroke-width='2.2'/><text x='195' y='40' font-size='9' fill='var(--amber)' text-anchor='middle' font-weight='700'>Warm site</text><text x='195' y='58' font-size='6.5' fill='var(--amber)' text-anchor='middle'>Partial / periodic data</text><text x='195' y='72' font-size='6.5' fill='var(--amber)' text-anchor='middle'>Failover in hours</text><text x='195' y='86' font-size='6.5' fill='var(--amber)' text-anchor='middle'>Moderate cost</text><rect x='260' y='20' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='315' y='40' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Cold site</text><text x='315' y='58' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Empty facility</text><text x='315' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Failover in days</text><text x='315' y='86' font-size='6.5' fill='var(--muted)' text-anchor='middle'>Least expensive</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Same spectrum: recovery speed trades directly against cost \u2014 a hot site is</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>fastest and priciest, a cold site the opposite.</text></svg>"},
    { "id": "sd3-34-3", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Platform diversity", "definition": "A resilience strategy of using different hardware or software platforms for redundant systems, so a single vulnerability or flaw can't simultaneously compromise every redundant copy.", "scenario": "avoid having a single vulnerability take down both the primary and backup systems by running them on different platforms", "distractors": ["High availability (single-platform redundancy)", "Multi-cloud strategy", "Geographic dispersion"], "tip": "DIFFERENT platforms for redundant copies — a single flaw can't hit every copy at once, unlike HA redundancy that might run the SAME platform everywhere." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-3'><title id='dt-sd3-34-3'>Using different hardware/software platforms for redundant systems so one flaw can&#39;t compromise all copies.</title><rect x='30' y='30' width='130' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Primary</text><text x='95' y='64' font-size='6.4' fill='var(--primary)' text-anchor='middle'>Linux platform</text><rect x='210' y='30' width='130' height='50' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='2'/><text x='275' y='50' font-size='7.5' fill='var(--blue)' text-anchor='middle' font-weight='700'>Backup</text><text x='275' y='64' font-size='6.2' fill='var(--blue)' text-anchor='middle'>DIFFERENT platform</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>A single flaw canNOT hit every copy at once \u2014 unlike</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>HA redundancy that might run the SAME platform.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Using different hardware/software platforms for redundant systems so one flaw can&#39;t</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>compromise all copies.</text></svg>"},
    { "id": "sd3-34-4", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Multi-cloud strategy", "definition": "Using services from more than one cloud provider to reduce dependency on any single vendor and improve resilience against a provider-wide outage.", "scenario": "avoid a single cloud provider's outage taking down the entire company's operations", "distractors": ["Hybrid cloud", "Platform diversity (broader concept)", "On-premises redundancy"], "tip": "MULTIPLE cloud PROVIDERS specifically — platform diversity is the broader concept this is one specific application of." , "diagram": "<svg viewBox='0 0 400 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-4'><title id='dt-sd3-34-4'>Using services from more than one cloud provider to reduce vendor dependency and improve resilience.</title><rect x='30' y='30' width='130' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Provider A</text><rect x='210' y='30' width='130' height='50' rx='6' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='2'/><text x='275' y='50' font-size='7.5' fill='var(--blue)' text-anchor='middle' font-weight='700'>Provider B</text><text x='190' y='20' font-size='6.6' fill='var(--muted)' text-anchor='middle'>one outage does not take down everything</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>MULTIPLE cloud PROVIDERS specifically \u2014 platform</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>diversity is the broader concept this applies.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Using services from more than one cloud provider to reduce vendor dependency and</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>improve resilience.</text></svg>"},
    { "id": "sd3-34-5", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Uninterruptible power supply (UPS)", "definition": "A battery-backed device that provides short-term emergency power to equipment during a power interruption, bridging the gap until backup generators start or power is restored.", "scenario": "keep servers running for the few minutes it takes a backup generator to start after a power outage", "distractors": ["Generator (long-term backup power)", "Power distribution unit", "Redundant power supply"], "tip": "SHORT-TERM battery bridge — a generator provides the LONG-TERM power once it spins up, the two work together in sequence, not as alternatives." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-5'><title id='dt-sd3-34-5'>Short-term battery bridge \u2014 a generator provides long-term power once it spins up, the two work together in sequence.</title><line x1='30' y1='70' x2='350' y2='70' stroke='var(--border)' stroke-width='1.5'/><rect x='30' y='40' width='80' height='20' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='70' y='54' font-size='6.8' fill='var(--text)' text-anchor='middle' font-weight='700'>Utility power</text><rect x='130' y='40' width='90' height='20' rx='3' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='175' y='54' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>UPS bridges gap</text><rect x='240' y='40' width='100' height='20' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='290' y='54' font-size='6.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Generator running</text><text x='130' y='90' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>power cut</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>Short-term battery bridge until generators start</text><text x='190' y='124' font-size='7.3' fill='var(--text)' text-anchor='middle'>or utility power is restored.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Short-term battery bridge \u2014 a generator provides long-term power once it spins</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>up, the two work together in sequence.</text></svg>"},
    { "id": "sd3-34-6", "core": "core1", "domain": "sd3", "objective": "3.4", "term": "Recovery time objective (RTO)", "definition": "The maximum acceptable amount of time a system can be down after a disruption before the impact becomes unacceptable to the business.", "scenario": "define how long the order-processing system is allowed to stay down before the outage becomes unacceptable", "distractors": ["Recovery point objective (RPO)", "Mean time to repair (MTTR)", "Service level agreement"], "tip": "MAX ACCEPTABLE downtime — RPO instead measures max acceptable DATA LOSS (how far back backups need to go), a commonly confused pair." , "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd3-34-6'><title id='dt-sd3-34-6'>Max acceptable downtime \u2014 RPO instead measures max acceptable data loss (how far back backups need to go), a commonly confused pair.</title><line x1='30' y1='60' x2='350' y2='60' stroke='var(--border)' stroke-width='1.5'/><circle cx='60' cy='60' r='4' fill='var(--red)'/><text x='60' y='46' font-size='6.8' fill='var(--red)' text-anchor='middle' font-weight='700'>Disruption</text><rect x='60' y='68' width='220' height='18' rx='3' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='170' y='81' font-size='6.8' fill='var(--text)' text-anchor='middle' font-weight='700'>RTO \u2014 max acceptable downtime</text><circle cx='280' cy='60' r='4' fill='var(--primary)'/><text x='280' y='46' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Back online</text><text x='190' y='110' font-size='7.3' fill='var(--text)' text-anchor='middle'>Past this point, the business impact becomes</text><text x='190' y='122' font-size='7.3' fill='var(--text)' text-anchor='middle'>unacceptable \u2014 not about how much data is lost.</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Max acceptable downtime \u2014 RPO instead measures max acceptable data loss (how</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>far back backups need to go), a commonly confused pair.</text></svg>"},

    { "id": "sd4-41-1", "core": "core1", "domain": "sd4", "objective": "4.1", "term": "Secure baseline", "definition": "A documented, standardized starting configuration for a system that has had unnecessary features, services, and default settings removed or hardened.", "scenario": "define the standard hardened starting configuration every new server must be built from", "distractors": ["Configuration enforcement (ongoing monitoring)", "Patch management", "Change management"], "tip": "The STARTING configuration — configuration enforcement is the ONGOING process of keeping systems matching that baseline over time." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-41-1'><title id='dt-sd4-41-1'>A documented, standardized starting configuration with unnecessary features/services removed or hardened.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Secure baseline</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>the STARTING config</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Config enforcement</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>ONGOING, keeps it matching</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A documented, standardized starting configuration with unnecessary</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>features/services removed or hardened.</text></svg>"},
    { "id": "sd4-41-2", "core": "core1", "domain": "sd4", "objective": "4.1", "term": "Hardening", "definition": "The process of reducing a system's attack surface by disabling unnecessary services, closing unused ports, and applying secure configuration settings.", "scenario": "reduce the number of ways a newly deployed server could be attacked by turning off every service it doesn't actually need", "distractors": ["Patch management", "Segmentation", "Sandboxing"], "tip": "REDUCES the attack surface directly — disabling services and closing ports, distinct from patch management which fixes KNOWN vulnerabilities in what's left running." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-41-2'><title id='dt-sd4-41-2'>Reduces a system&#39;s attack surface by disabling unnecessary services, closing ports, applying secure settings.</title><rect x='20' y='26' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='42' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>\u2713 Disable unused services</text><text x='190' y='58' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>\u2713 Close unused ports</text><text x='190' y='74' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>\u2713 Secure config settings</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>REDUCES attack surface directly \u2014 patch management</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>instead fixes KNOWN flaws in what&#39;s left running.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Reduces a system&#39;s attack surface by disabling unnecessary services, closing</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>ports, applying secure settings.</text></svg>"},
    { "id": "sd4-41-3", "core": "core1", "domain": "sd4", "objective": "4.1", "term": "WPA3", "definition": "The current generation of Wi-Fi Protected Access security, providing stronger encryption and protection against offline password-guessing attacks than WPA2.", "scenario": "choose the strongest widely supported wireless security standard when configuring a new access point", "distractors": ["WEP", "WPA2", "Open authentication"], "tip": "CURRENT standard, strongest against offline guessing — WEP and open authentication are the deliberately weak wrong answers here." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-41-3'><title id='dt-sd4-41-3'>Stronger encryption and protection against offline password-guessing attacks than WPA2.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>WPA3</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>current standard \u2014 use this</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>WPA2 / WEP / Open</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>weak or none</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Stronger encryption and protection against offline password-guessing attacks</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>than WPA2.</text></svg>"},
    { "id": "sd4-41-4", "core": "core1", "domain": "sd4", "objective": "4.1", "term": "Sandboxing", "definition": "Running an application or file in an isolated environment separate from the rest of the system, so that if it turns out to be malicious, it can't affect production systems.", "scenario": "safely observe what an unknown, possibly malicious executable actually does before it ever touches a real workstation", "distractors": ["Application allow listing", "Hardening", "Isolation (network-level)"], "tip": "ISOLATES to test SAFELY — runs something potentially malicious without risking production, a containment-by-observation approach." , "diagram": "<svg viewBox='0 0 380 170' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-41-4'><title id='dt-sd4-41-4'>Running an application or file in an isolated environment so it can&#39;t affect production if malicious.</title><rect x='20' y='24' width='340' height='66' rx='8' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2' stroke-dasharray='3 2'/><text x='190' y='18' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>Isolated boundary</text><rect x='140' y='44' width='100' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='63' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>Unknown .exe</text><text x='190' y='106' font-size='7.3' fill='var(--text)' text-anchor='middle'>Isolates to test SAFELY \u2014 observes what it does</text><text x='190' y='118' font-size='7.3' fill='var(--text)' text-anchor='middle'>before it ever touches production.</text><text x='16' y='148' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Running an application or file in an isolated environment so it can&#39;t affect</text><text x='16' y='160' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>production if malicious.</text></svg>"},
    { "id": "sd4-41-5", "core": "core1", "domain": "sd4", "objective": "4.1", "term": "Mobile device management (MDM)", "definition": "A platform that lets an organization centrally enforce security policies, configurations, and remote wipe capability on employee mobile devices.", "scenario": "remotely wipe a lost company phone and enforce a minimum passcode policy across all employee devices", "distractors": ["Network access control", "Application allow listing", "Data loss prevention"], "tip": "CENTRAL policy enforcement on MOBILE devices specifically — remote wipe is the signature capability, distinct from NAC which gates network access." , "diagram": "<svg viewBox='0 0 380 180' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-41-5'><title id='dt-sd4-41-5'>Lets an org centrally enforce security policies, configurations, and remote wipe on mobile devices.</title><rect x='140' y='20' width='100' height='30' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='40' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>MDM platform</text><line x1='190' y1='52' x2='190' y2='62' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 60 L190 67 L194 60' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='60' y='70' width='260' height='30' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='89' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>Lost phone: remote wipe + passcode policy</text><text x='190' y='118' font-size='7.3' fill='var(--text)' text-anchor='middle'>CENTRAL policy enforcement on MOBILE devices \u2014 NAC</text><text x='190' y='130' font-size='7.3' fill='var(--text)' text-anchor='middle'>instead gates network access broadly.</text><text x='16' y='158' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Lets an org centrally enforce security policies, configurations, and remote</text><text x='16' y='170' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>wipe on mobile devices.</text></svg>"},

    { "id": "sd4-42-1", "core": "core1", "domain": "sd4", "objective": "4.2", "term": "Asset acquisition and procurement", "definition": "The formal process of evaluating, approving, and purchasing hardware and software, including reviewing the security posture of vendors before adoption.", "scenario": "make sure a new software vendor's security practices are vetted before the company adopts their product", "distractors": ["Asset disposal", "Asset monitoring", "Change management"], "tip": "BEFORE adoption — vetting vendor security posture happens at PURCHASE time, the opposite end of the asset lifecycle from disposal." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-42-1'><title id='dt-sd4-42-1'>Vetting vendor security posture happens at PURCHASE time \u2014 the opposite end of the lifecycle from disposal.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='28' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Evaluate vendor</text><text x='180.0' y='41' font-size='7.5' fill='var(--text)' text-anchor='middle'>security posture reviewed</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='74' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Approve</text><text x='180.0' y='87' font-size='7.5' fill='var(--muted)' text-anchor='middle'>formal sign-off</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Purchase</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>adoption begins</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Vetting vendor security posture happens at PURCHASE time \u2014 the opposite end</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>of the lifecycle from disposal.</text></svg>"},
    { "id": "sd4-42-2", "core": "core1", "domain": "sd4", "objective": "4.2", "term": "Data sanitization", "definition": "The process of permanently removing data from storage media so it cannot be recovered, used before media is reused, resold, or disposed of.", "scenario": "make sure a decommissioned hard drive can't have its old customer data recovered before it's resold", "distractors": ["Data destruction (physical)", "Data masking", "Encryption"], "tip": "PERMANENTLY removes data before REUSE — physical destruction is one specific METHOD of sanitization, among several (wiping, degaussing, etc.)." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-42-2'><title id='dt-sd4-42-2'>Permanently removing data from storage media before it&#39;s reused, resold, or disposed of.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Sanitization</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>the broader GOAL</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Physical destruction</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>one specific METHOD</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Permanently removing data from storage media before it&#39;s reused, resold, or</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>disposed of.</text></svg>"},
    { "id": "sd4-42-3", "core": "core1", "domain": "sd4", "objective": "4.2", "term": "Certificate of destruction", "definition": "A formal document confirming that a specific asset's data was destroyed according to an approved method, providing an auditable record for compliance.", "scenario": "provide auditable proof that old hard drives were properly destroyed rather than simply thrown away", "distractors": ["Asset inventory record", "Chain of custody form (evidence-specific)", "Change management record"], "tip": "PROVES destruction happened, for AUDIT/compliance — a chain of custody form instead tracks EVIDENCE handling, a different legal/forensic purpose." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-42-3'><title id='dt-sd4-42-3'>A formal document confirming an asset&#39;s data was destroyed, providing an auditable record for compliance.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Old drives</text><text x='95' y='64' font-size='6.4' fill='var(--muted)' text-anchor='middle'>destroyed</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Certificate</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>auditable proof</text><text x='285' y='70' font-size='6.4' fill='var(--primary)' text-anchor='middle'>for compliance</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A formal document confirming an asset&#39;s data was destroyed, providing an auditable</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>record for compliance.</text></svg>"},
    { "id": "sd4-42-4", "core": "core1", "domain": "sd4", "objective": "4.2", "term": "Asset tracking", "definition": "The ongoing practice of recording and monitoring what hardware and software assets an organization owns, where they are, and who is responsible for them.", "scenario": "know exactly how many laptops the company owns and who currently has each one", "distractors": ["Data sanitization", "Configuration management", "Vulnerability scanning"], "tip": "WHAT exists and WHO owns it — ongoing inventory, distinct from configuration management which tracks SETTINGS rather than ownership/location." , "diagram": "<svg viewBox='0 0 400 120' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-42-4'><title id='dt-sd4-42-4'>The ongoing practice of recording what hardware/software assets an org owns, where, and who&#39;s responsible.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>WHAT exists</text><text x='95' y='64' font-size='6.6' fill='var(--primary)' text-anchor='middle'>+ WHO owns it</text><rect x='210' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Config mgmt</text><text x='285' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>tracks SETTINGS instead</text><text x='16' y='98' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The ongoing practice of recording what hardware/software assets an org owns, where,</text><text x='16' y='110' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>and who&#39;s responsible.</text></svg>"},

    { "id": "sd4-43-1", "core": "core1", "domain": "sd4", "objective": "4.3", "term": "Vulnerability scan", "definition": "An automated process that checks systems for known vulnerabilities and misconfigurations without attempting to actually exploit them.", "scenario": "get a broad, automated list of known vulnerabilities across hundreds of servers on a regular schedule", "distractors": ["Penetration test", "Bug bounty program", "Threat feed"], "tip": "AUTOMATED, no actual exploitation — a pen test goes further and ACTIVELY exploits to prove real-world impact." , "diagram": "<svg viewBox='0 0 390 130' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-43-1'><title id='dt-sd4-43-1'>Automated, no actual exploitation \u2014 a pen test goes further and actively exploits to prove real-world impact.</title><rect x='20' y='24' width='165' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='102' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Vulnerability scan</text><text x='102' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>automated, identifies</text><text x='102' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>NO actual exploitation</text><rect x='195' y='24' width='165' height='60' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='277' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Penetration test</text><text x='277' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>authorized humans</text><text x='277' y='72' font-size='6' fill='var(--muted)' text-anchor='middle'>ACTIVELY exploit to prove impact</text><text x='16' y='108' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Automated, no actual exploitation \u2014 a pen test goes further and actively exploits</text><text x='16' y='120' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>to prove real-world impact.</text></svg>"},
    { "id": "sd4-43-2", "core": "core1", "domain": "sd4", "objective": "4.3", "term": "Penetration test", "definition": "An authorized, simulated attack against a system performed by security professionals to actively exploit vulnerabilities and demonstrate real-world impact.", "scenario": "have security professionals actually attempt to break into the network the way a real attacker would, with permission", "distractors": ["Vulnerability scan", "Vulnerability assessment (passive)", "Security audit"], "tip": "ACTIVELY exploits to prove impact — a vulnerability scan just IDENTIFIES issues automatically without attempting to exploit them." , "diagram": "<svg viewBox='0 0 390 130' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-43-2'><title id='dt-sd4-43-2'>Actively exploits to prove impact \u2014 a vulnerability scan just identifies issues automatically without attempting to exploit them.</title><rect x='20' y='24' width='165' height='60' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='102' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Vulnerability scan</text><text x='102' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>automated, identifies</text><text x='102' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>NO actual exploitation</text><rect x='195' y='24' width='165' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='277' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Penetration test</text><text x='277' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>authorized humans</text><text x='277' y='72' font-size='6' fill='var(--muted)' text-anchor='middle'>ACTIVELY exploit to prove impact</text><text x='16' y='108' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Actively exploits to prove impact \u2014 a vulnerability scan just identifies issues</text><text x='16' y='120' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>automatically without attempting to exploit them.</text></svg>"},
    { "id": "sd4-43-3", "core": "core1", "domain": "sd4", "objective": "4.3", "term": "Common Vulnerability Scoring System (CVSS)", "definition": "A standardized framework for rating the severity of a vulnerability on a numeric scale, helping prioritize which vulnerabilities to fix first.", "scenario": "decide which of a hundred discovered vulnerabilities to patch first based on a standardized severity score", "distractors": ["CVE (an identifier, not a score)", "Risk register", "Exposure factor"], "tip": "A NUMERIC SEVERITY SCORE — CVE is just the IDENTIFIER for a vulnerability, not a rating of how bad it is." , "diagram": "<svg viewBox='0 0 390 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-43-3'><title id='dt-sd4-43-3'>CVE names the vulnerability; CVSS rates how severe that specific CVE entry actually is \u2014 one identifies, the other prioritizes.</title><rect x='30' y='40' width='140' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100' y='62' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CVE-2024-12345</text><text x='100' y='78' font-size='7' fill='var(--muted)' text-anchor='middle'>the IDENTIFIER</text><line x1='170' y1='65' x2='224' y2='65' stroke='var(--muted)' stroke-width='1.5'/><path d='M222 61 L229 65 L222 69' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='230' y='40' width='130' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='295' y='62' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CVSS 9.8</text><text x='295' y='78' font-size='7' fill='var(--muted)' text-anchor='middle'>the SEVERITY score</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>CVE names the vulnerability; CVSS rates how severe that specific CVE entry</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>actually is \u2014 one identifies, the other prioritizes.</text></svg>"},
    { "id": "sd4-43-4", "core": "core1", "domain": "sd4", "objective": "4.3", "term": "Common Vulnerabilities and Exposures (CVE)", "definition": "A publicly maintained, standardized list of known, publicly disclosed cybersecurity vulnerabilities, each with a unique identifier.", "scenario": "reference a specific, publicly known vulnerability by its unique standardized identifier when reporting an issue", "distractors": ["CVSS (a score, not an identifier)", "Risk register", "Threat feed"], "tip": "The IDENTIFIER — CVSS is the separate SCORE that rates how severe a given entry here actually is." , "diagram": "<svg viewBox='0 0 390 155' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-43-4'><title id='dt-sd4-43-4'>CVE names the vulnerability; CVSS rates how severe that specific CVE entry actually is \u2014 one identifies, the other prioritizes.</title><rect x='30' y='40' width='140' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100' y='62' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CVE-2024-12345</text><text x='100' y='78' font-size='7' fill='var(--muted)' text-anchor='middle'>the IDENTIFIER</text><line x1='170' y1='65' x2='224' y2='65' stroke='var(--muted)' stroke-width='1.5'/><path d='M222 61 L229 65 L222 69' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='230' y='40' width='130' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='295' y='62' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>CVSS 9.8</text><text x='295' y='78' font-size='7' fill='var(--muted)' text-anchor='middle'>the SEVERITY score</text><text x='16' y='133' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>CVE names the vulnerability; CVSS rates how severe that specific CVE entry</text><text x='16' y='145' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>actually is \u2014 one identifies, the other prioritizes.</text></svg>"},
    { "id": "sd4-43-5", "core": "core1", "domain": "sd4", "objective": "4.3", "term": "Patch validation", "definition": "The process of confirming, after deployment, that a patch was successfully applied and actually resolved the vulnerability it targeted.", "scenario": "confirm that a critical patch pushed to five hundred servers last night actually installed and closed the vulnerability", "distractors": ["Vulnerability scan (initial discovery)", "Patch management (the overall process)", "Configuration enforcement"], "tip": "CONFIRMS AFTER deployment that the fix actually worked — patch management is the whole broader process this validation step is just one part of." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-43-5'><title id='dt-sd4-43-5'>Confirms AFTER deployment that a patch actually resolved the vulnerability \u2014 one step within the broader patch process.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='28' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Patch deployed</text><text x='180.0' y='41' font-size='7.5' fill='var(--muted)' text-anchor='middle'>to 500 servers</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Validation check</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>confirm it actually installed</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Vulnerability confirmed closed</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>not just assumed</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Confirms AFTER deployment that a patch actually resolved the vulnerability</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>\u2014 one step within the broader patch process.</text></svg>"},

    { "id": "sd4-44-1", "core": "core1", "domain": "sd4", "objective": "4.4", "term": "Security information and event management (SIEM)", "definition": "A platform that aggregates, correlates, and analyzes log data from across an organization's systems to detect and alert on potential security incidents.", "scenario": "correlate login attempts from a firewall, a server, and a VPN concentrator into a single alert showing a coordinated attack", "distractors": ["Security orchestration, automation, and response (SOAR)", "Log aggregation alone", "Antivirus platform"], "tip": "AGGREGATES AND ANALYZES for alerting — SOAR goes a step further and can AUTOMATE the response, not just detect and alert." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-44-1'><title id='dt-sd4-44-1'>Aggregates and analyzes for alerting \u2014 SOAR goes a step further and can automate the response, not just detect and alert.</title><rect x='20' y='20' width='80' height='22' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='60' y='34' font-size='6.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Firewall logs</text><line x1='60' y1='42' x2='60' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M56 52 L60 59 L64 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='110' y='20' width='80' height='22' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='150' y='34' font-size='6.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Endpoint logs</text><line x1='150' y1='42' x2='150' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M146 52 L150 59 L154 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='200' y='20' width='80' height='22' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='240' y='34' font-size='6.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Server logs</text><line x1='240' y1='42' x2='240' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M236 52 L240 59 L244 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='290' y='20' width='80' height='22' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='330' y='34' font-size='6.3' fill='var(--text)' text-anchor='middle' font-weight='700'>App logs</text><line x1='330' y1='42' x2='330' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M326 52 L330 59 L334 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='90' y='62' width='200' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='82' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>SIEM \u2014 aggregates + correlates</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>Detects and alerts on potential incidents \u2014 SOAR goes</text><text x='190' y='124' font-size='7.3' fill='var(--text)' text-anchor='middle'>further and can automate the response.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Aggregates and analyzes for alerting \u2014 SOAR goes a step further and can</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>automate the response, not just detect and alert.</text></svg>"},
    { "id": "sd4-44-2", "core": "core1", "domain": "sd4", "objective": "4.4", "term": "Log aggregation", "definition": "The process of collecting log data from many different systems into a single centralized location for easier searching and correlation.", "scenario": "search log data from every network device in one place instead of checking each device individually", "distractors": ["SIEM (analysis and alerting on top of aggregation)", "NetFlow", "Vulnerability scanning"], "tip": "Just COLLECTS logs centrally — SIEM adds the analysis/correlation/alerting layer on TOP of this, a related but more advanced capability." , "diagram": "<svg viewBox='0 0 380 165' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-44-2'><title id='dt-sd4-44-2'>Collecting log data from many different systems into a single centralized location.</title><rect x='30' y='20' width='76' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='68' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle' font-weight='700'>Firewall</text><line x1='68' y1='44' x2='68' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M64 52 L68 59 L72 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='114' y='20' width='76' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='152' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle' font-weight='700'>Router</text><line x1='152' y1='44' x2='152' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M148 52 L152 59 L156 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='198' y='20' width='76' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='236' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle' font-weight='700'>Server</text><line x1='236' y1='44' x2='236' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M232 52 L236 59 L240 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='282' y='20' width='76' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='320' y='36' font-size='6.4' fill='var(--text)' text-anchor='middle' font-weight='700'>Switch</text><line x1='320' y1='44' x2='320' y2='54' stroke='var(--muted)' stroke-width='1.5'/><path d='M316 52 L320 59 L324 52' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='60' y='62' width='260' height='28' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='80' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Centralized log storage</text><text x='190' y='106' font-size='7.3' fill='var(--text)' text-anchor='middle'>Just COLLECTS logs \u2014 SIEM adds analysis/correlation/</text><text x='190' y='118' font-size='7.3' fill='var(--text)' text-anchor='middle'>alerting on TOP of this.</text><text x='16' y='143' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Collecting log data from many different systems into a single centralized</text><text x='16' y='155' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>location.</text></svg>"},
    { "id": "sd4-44-3", "core": "core1", "domain": "sd4", "objective": "4.4", "term": "NetFlow", "definition": "A protocol that exports summarized traffic flow data from routers and switches, showing who is talking to whom, over what protocol, and how much traffic is involved.", "scenario": "identify which internal host is generating an unusual spike in outbound traffic without capturing every packet", "distractors": ["SIEM", "Log aggregation (raw logs, not flow summaries)", "SNMP trap"], "tip": "TRAFFIC FLOW summaries (who/what/how much) — not raw log messages, a different, more summarized kind of network visibility data." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-44-3'><title id='dt-sd4-44-3'>Exports summarized traffic flow data \u2014 who&#39;s talking to whom, over what protocol, how much traffic.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Router / switch</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>exports flow data</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>who \u2192 whom</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>protocol, volume</text><text x='285' y='70' font-size='6' fill='var(--primary)' text-anchor='middle'>SUMMARY, not content</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Exports summarized traffic flow data \u2014 who&#39;s talking to whom, over what protocol,</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>how much traffic.</text></svg>"},
    { "id": "sd4-44-4", "core": "core1", "domain": "sd4", "objective": "4.4", "term": "SNMP trap", "definition": "An unsolicited alert message sent from a managed network device to a monitoring system when a significant event occurs, without waiting to be polled.", "scenario": "get immediately notified the moment a switch interface goes down, rather than waiting for the next scheduled poll", "distractors": ["NetFlow", "Syslog message (a distinct protocol)", "SIEM correlation rule"], "tip": "UNSOLICITED, event-driven — pushed immediately when something happens, rather than waiting to be polled like standard SNMP queries." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-44-4'><title id='dt-sd4-44-4'>An unsolicited alert sent when a significant event occurs, without waiting to be polled.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='2'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Switch port</text><text x='95' y='64' font-size='6.4' fill='var(--red)' text-anchor='middle'>goes DOWN</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--red)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--red)' stroke-width='1.5'/><text x='190' y='44' font-size='6.2' fill='var(--muted)' text-anchor='middle'>pushed immediately</text><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Monitoring</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>system alerted</text><text x='285' y='70' font-size='5.8' fill='var(--primary)' text-anchor='middle'>not waiting to be polled</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>An unsolicited alert sent when a significant event occurs, without waiting to be</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>polled.</text></svg>"},
    { "id": "sd4-44-5", "core": "core1", "domain": "sd4", "objective": "4.4", "term": "Security Content Automation Protocol (SCAP)", "definition": "A standardized set of specifications used to automate vulnerability management, measurement, and policy compliance checking against benchmarks.", "scenario": "automatically check hundreds of servers against a standardized secure configuration benchmark instead of manually reviewing each one", "distractors": ["SIEM", "CVSS", "Log aggregation"], "tip": "AUTOMATES compliance checking against BENCHMARKS — a standardized specification set, not itself a monitoring platform or a severity score." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-44-5'><title id='dt-sd4-44-5'>Automates vulnerability management and policy compliance checking against standardized benchmarks.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>500 servers</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>checked automatically</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>SCAP benchmark</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>standardized</text><text x='285' y='70' font-size='6.4' fill='var(--primary)' text-anchor='middle'>compliance check</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Automates vulnerability management and policy compliance checking against</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>standardized benchmarks.</text></svg>"},

    { "id": "sd4-45-1", "core": "core1", "domain": "sd4", "objective": "4.5", "term": "DNS filtering", "definition": "A security control that blocks access to known-malicious or policy-violating domains at the DNS resolution level, before a connection is even established.", "scenario": "block employees from ever connecting to a known phishing domain, at the moment their computer tries to resolve its name", "distractors": ["Web application firewall", "Email gateway filtering", "Data loss prevention"], "tip": "Blocks at the DNS RESOLUTION step — before a connection even gets established, the earliest possible point to stop a malicious destination." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-45-1'><title id='dt-sd4-45-1'>Blocks known-malicious or policy-violating domains at DNS resolution, before a connection is even established.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='36' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>User clicks phishing link</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>DNS resolution attempted</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>blocked HERE, earliest point</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Connection never established</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>malicious site unreachable</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Blocks known-malicious or policy-violating domains at DNS resolution,</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>before a connection is even established.</text></svg>"},
    { "id": "sd4-45-2", "core": "core1", "domain": "sd4", "objective": "4.5", "term": "SPF (Sender Policy Framework)", "definition": "An email authentication standard that lets a domain owner specify which mail servers are authorized to send email on their behalf, helping receivers detect spoofed senders.", "scenario": "let a receiving mail server verify that an email claiming to be from a company actually came from that company's authorized servers", "distractors": ["DKIM", "DMARC", "S/MIME"], "tip": "Which SERVERS can send for a domain — DKIM instead proves the MESSAGE wasn't altered via a signature, a different verification mechanism entirely." , "diagram": "<svg viewBox='0 0 380 205' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-45-2'><title id='dt-sd4-45-2'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message content, DMARC is the policy layer tying both together.</title><rect x='20' y='20' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--primary)' stroke-width='2.2'/><text x='75' y='41' font-size='9' fill='var(--primary)' text-anchor='middle' font-weight='700'>SPF</text><text x='130' y='41' font-size='6.8' fill='var(--primary)' text-anchor='start'>Which SERVERS can send for this domain</text><rect x='20' y='62' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='83' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>DKIM</text><text x='130' y='83' font-size='6.8' fill='var(--muted)' text-anchor='start'>SIGNS the message \u2014 proves it wasn&#39;t altered</text><rect x='20' y='104' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='125' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>DMARC</text><text x='130' y='125' font-size='6.8' fill='var(--muted)' text-anchor='start'>POLICY: what to do if SPF/DKIM fail + reports</text><text x='16' y='183' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message</text><text x='16' y='195' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>content, DMARC is the policy layer tying both together.</text></svg>"},
    { "id": "sd4-45-3", "core": "core1", "domain": "sd4", "objective": "4.5", "term": "DKIM (DomainKeys Identified Mail)", "definition": "An email authentication standard that adds a digital signature to outgoing messages, letting receivers verify the message wasn't altered in transit and genuinely came from the claimed domain.", "scenario": "let a receiving mail server verify that an email's content wasn't tampered with after it left the sending domain", "distractors": ["SPF", "DMARC", "TLS (transport encryption, not message signing)"], "tip": "SIGNS the message content — SPF instead just checks which SERVER sent it, two different, complementary email authentication checks." , "diagram": "<svg viewBox='0 0 380 205' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-45-3'><title id='dt-sd4-45-3'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message content, DMARC is the policy layer tying both together.</title><rect x='20' y='20' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='41' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>SPF</text><text x='130' y='41' font-size='6.8' fill='var(--muted)' text-anchor='start'>Which SERVERS can send for this domain</text><rect x='20' y='62' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--blue)' stroke-width='2.2'/><text x='75' y='83' font-size='9' fill='var(--blue)' text-anchor='middle' font-weight='700'>DKIM</text><text x='130' y='83' font-size='6.8' fill='var(--blue)' text-anchor='start'>SIGNS the message \u2014 proves it wasn&#39;t altered</text><rect x='20' y='104' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='125' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>DMARC</text><text x='130' y='125' font-size='6.8' fill='var(--muted)' text-anchor='start'>POLICY: what to do if SPF/DKIM fail + reports</text><text x='16' y='183' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message</text><text x='16' y='195' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>content, DMARC is the policy layer tying both together.</text></svg>"},
    { "id": "sd4-45-4", "core": "core1", "domain": "sd4", "objective": "4.5", "term": "DMARC", "definition": "An email authentication policy standard that tells receiving mail servers what to do with messages that fail SPF or DKIM checks, and provides reporting back to the domain owner.", "scenario": "tell receiving mail servers to reject or quarantine emails that fail authentication checks, and get reports on spoofing attempts", "distractors": ["SPF (checks sender IP only)", "DKIM (checks signature only)", "Email gateway (a device, not a policy standard)"], "tip": "The POLICY layer on top of both — tells receivers what to DO when SPF or DKIM fails, plus sends reports back to the domain owner." , "diagram": "<svg viewBox='0 0 380 205' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-45-4'><title id='dt-sd4-45-4'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message content, DMARC is the policy layer tying both together.</title><rect x='20' y='20' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='41' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>SPF</text><text x='130' y='41' font-size='6.8' fill='var(--muted)' text-anchor='start'>Which SERVERS can send for this domain</text><rect x='20' y='62' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='83' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>DKIM</text><text x='130' y='83' font-size='6.8' fill='var(--muted)' text-anchor='start'>SIGNS the message \u2014 proves it wasn&#39;t altered</text><rect x='20' y='104' width='340' height='34' rx='5' fill='var(--surface-3)' stroke='var(--amber)' stroke-width='2.2'/><text x='75' y='125' font-size='9' fill='var(--amber)' text-anchor='middle' font-weight='700'>DMARC</text><text x='130' y='125' font-size='6.8' fill='var(--amber)' text-anchor='start'>POLICY: what to do if SPF/DKIM fail + reports</text><text x='16' y='183' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Three layered checks \u2014 SPF checks the sending server, DKIM signs the message</text><text x='16' y='195' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>content, DMARC is the policy layer tying both together.</text></svg>"},
    { "id": "sd4-45-5", "core": "core1", "domain": "sd4", "objective": "4.5", "term": "Endpoint detection and response (EDR)", "definition": "A security tool that continuously monitors endpoint activity, detects suspicious behavior, and enables rapid investigation and response directly on the device.", "scenario": "detect and automatically contain a suspicious process behaving like ransomware directly on an employee's laptop", "distractors": ["Traditional antivirus (signature-based only)", "SIEM (centralized, not endpoint-resident)", "DLP"], "tip": "BEHAVIOR-based, ON the endpoint — traditional antivirus only catches known SIGNATURES, missing novel attacks this is built to detect." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-45-5'><title id='dt-sd4-45-5'>Continuously monitors endpoint activity, detects suspicious behavior, and enables rapid response on the device.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>EDR</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>BEHAVIOR-based, on endpoint</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Traditional AV</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>known signatures only</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Continuously monitors endpoint activity, detects suspicious behavior, and</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>enables rapid response on the device.</text></svg>"},

    { "id": "sd4-46-1", "core": "core1", "domain": "sd4", "objective": "4.6", "term": "Role-based access control (RBAC)", "definition": "An access control model where permissions are assigned to roles rather than individuals, and users are granted access by being assigned to the appropriate role.", "scenario": "grant every member of the helpdesk team the same standard set of permissions by assigning them all to one role", "distractors": ["Discretionary access control (DAC)", "Mandatory access control (MAC)", "Attribute-based access control (ABAC)"], "tip": "Permissions via ROLE assignment — DAC instead lets the RESOURCE OWNER personally decide who gets access, no centralized role structure involved.", "diagram": "<svg viewBox='0 0 380 190' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-46-1'><title id='dt-sd4-46-1'>Who decides is the axis: a role structure, the system itself, or the individual owner — no centralized role structure in DAC at all.</title><rect x='10' y='24' width='114' height='120' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='67' y='42' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>RBAC</text><text x='67' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>Permission tied</text><text x='67' y='73' font-size='6.3' fill='var(--muted)' text-anchor='middle'>to a ROLE</text><text x='67' y='94' font-size='6' fill='var(--text)' text-anchor='middle'>\"Helpdesk role</text><text x='67' y='104' font-size='6' fill='var(--text)' text-anchor='middle'>→ ticket access\"</text><rect x='133' y='24' width='114' height='120' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='190' y='42' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>MAC</text><text x='190' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>System-enforced</text><text x='190' y='73' font-size='6.3' fill='var(--muted)' text-anchor='middle'>by classification</text><text x='190' y='94' font-size='6' fill='var(--text)' text-anchor='middle'>\"Secret clearance</text><text x='190' y='104' font-size='6' fill='var(--text)' text-anchor='middle'>required\"</text><rect x='256' y='24' width='114' height='120' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='313' y='42' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DAC</text><text x='313' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>Resource OWNER</text><text x='313' y='73' font-size='6.3' fill='var(--muted)' text-anchor='middle'>decides directly</text><text x='313' y='94' font-size='6' fill='var(--text)' text-anchor='middle'>\"File owner grants</text><text x='313' y='104' font-size='6' fill='var(--text)' text-anchor='middle'>Bob access\"</text><text x='16' y='166' font-size='8.5' fill='var(--muted-2)'>Who decides is the axis: a role structure, the system itself, or the</text><text x='16' y='178' font-size='8.5' fill='var(--muted-2)'>individual owner — no centralized role structure in DAC at all.</text></svg>" },
    { "id": "sd4-46-2", "core": "core1", "domain": "sd4", "objective": "4.6", "term": "Mandatory access control (MAC)", "definition": "An access control model where a central authority assigns security labels to both users and resources, and access is granted only when those labels match a strict policy, with no user discretion.", "scenario": "enforce a strict, centrally controlled policy in a classified environment where users can never grant others access on their own", "distractors": ["Discretionary access control (DAC)", "Role-based access control (RBAC)", "Rule-based access control"], "tip": "CENTRAL AUTHORITY assigns labels, NO user discretion — the strictest model, unlike DAC where the resource owner decides." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-46-2'><title id='dt-sd4-46-2'>Who decides is the axis: a role structure, the system itself by classification, or the individual resource owner \u2014 three different models.</title><rect x='20' y='24' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='44' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>RBAC</text><text x='75' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>Permission tied</text><text x='75' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>to a ROLE</text><text x='75' y='96' font-size='6' fill='var(--muted)' text-anchor='middle'>&quot;Helpdesk role \u2192 ticket access&quot;</text><rect x='140' y='24' width='110' height='90' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='195' y='44' font-size='9.5' fill='var(--text)' text-anchor='middle' font-weight='700'>MAC</text><text x='195' y='62' font-size='6.3' fill='var(--text)' text-anchor='middle'>System-enforced</text><text x='195' y='72' font-size='6.3' fill='var(--text)' text-anchor='middle'>by classification</text><text x='195' y='96' font-size='6' fill='var(--text)' text-anchor='middle'>&quot;Secret clearance required&quot;</text><rect x='260' y='24' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='315' y='44' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>DAC</text><text x='315' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>Resource OWNER</text><text x='315' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>decides directly</text><text x='315' y='96' font-size='6' fill='var(--muted)' text-anchor='middle'>&quot;File owner grants Bob access&quot;</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Who decides is the axis: a role structure, the system itself by classification,</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>or the individual resource owner \u2014 three different models.</text></svg>"},
    { "id": "sd4-46-3", "core": "core1", "domain": "sd4", "objective": "4.6", "term": "Discretionary access control (DAC)", "definition": "An access control model where the owner of a resource decides who else is allowed to access it.", "scenario": "let a file's owner personally decide which specific coworkers can view or edit it", "distractors": ["Mandatory access control (MAC)", "Role-based access control (RBAC)", "Attribute-based access control (ABAC)"], "tip": "The OWNER decides — the most flexible/permissive model, the opposite of MAC's centrally-dictated, no-discretion approach." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-46-3'><title id='dt-sd4-46-3'>Who decides is the axis: a role structure, the system itself by classification, or the individual resource owner \u2014 three different models.</title><rect x='20' y='24' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='75' y='44' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>RBAC</text><text x='75' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>Permission tied</text><text x='75' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>to a ROLE</text><text x='75' y='96' font-size='6' fill='var(--muted)' text-anchor='middle'>&quot;Helpdesk role \u2192 ticket access&quot;</text><rect x='140' y='24' width='110' height='90' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='195' y='44' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>MAC</text><text x='195' y='62' font-size='6.3' fill='var(--muted)' text-anchor='middle'>System-enforced</text><text x='195' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>by classification</text><text x='195' y='96' font-size='6' fill='var(--muted)' text-anchor='middle'>&quot;Secret clearance required&quot;</text><rect x='260' y='24' width='110' height='90' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='315' y='44' font-size='9.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DAC</text><text x='315' y='62' font-size='6.3' fill='var(--text)' text-anchor='middle'>Resource OWNER</text><text x='315' y='72' font-size='6.3' fill='var(--text)' text-anchor='middle'>decides directly</text><text x='315' y='96' font-size='6' fill='var(--text)' text-anchor='middle'>&quot;File owner grants Bob access&quot;</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Who decides is the axis: a role structure, the system itself by classification,</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>or the individual resource owner \u2014 three different models.</text></svg>"},
    { "id": "sd4-46-4", "core": "core1", "domain": "sd4", "objective": "4.6", "term": "Federation", "definition": "A system that allows identity and authentication information to be trusted and shared across separate organizations or domains, letting users access external systems using their home organization's credentials.", "scenario": "let a university student log into a partner research library's system using their own university credentials", "distractors": ["Single sign-on (within one organization)", "Multifactor authentication", "Privileged access management"], "tip": "ACROSS separate organizations — SSO is the same convenience concept but scoped to ONE organization's own systems." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-46-4'><title id='dt-sd4-46-4'>Lets identity/auth info be trusted across separate organizations \u2014 SSO is the same idea within ONE org.</title><rect x='30' y='30' width='130' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Student</text><text x='95' y='64' font-size='6' fill='var(--muted)' text-anchor='middle'>university credentials</text><line x1='165' y1='55' x2='214' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M212 51 L219 55 L212 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='220' y='24' width='140' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='290' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Partner library</text><text x='290' y='58' font-size='6.2' fill='var(--primary)' text-anchor='middle'>trusts university\u2019s</text><text x='290' y='70' font-size='6' fill='var(--primary)' text-anchor='middle'>identity, no new account</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Lets identity/auth info be trusted across separate organizations \u2014 SSO is the same</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>idea within ONE org.</text></svg>"},
    { "id": "sd4-46-5", "core": "core1", "domain": "sd4", "objective": "4.6", "term": "Privileged access management (PAM)", "definition": "A set of tools and practices for securing, controlling, and monitoring accounts with elevated administrative access, often including just-in-time access and session recording.", "scenario": "require administrators to check out temporary elevated credentials for a limited window instead of holding standing admin rights permanently", "distractors": ["Role-based access control", "Federation", "Single sign-on"], "tip": "ELEVATED/ADMIN accounts specifically — just-in-time access and session recording are the signature features, not general user access control." , "diagram": "<svg viewBox='0 0 400 145' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-46-5'><title id='dt-sd4-46-5'>Elevated/admin accounts specifically \u2014 just-in-time access and session recording are the signature features of PAM.</title><rect x='20' y='30' width='90' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='65' y='47' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Admin</text><line x1='115' y1='43' x2='159' y2='43' stroke='var(--muted)' stroke-width='1.5'/><path d='M157 39 L164 43 L157 47' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='165' y='20' width='100' height='46' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='215' y='38' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>PAM vault</text><text x='215' y='52' font-size='6.3' fill='var(--muted)' text-anchor='middle'>just-in-time access</text><line x1='265' y1='43' x2='304' y2='43' stroke='var(--muted)' stroke-width='1.5'/><path d='M302 39 L309 43 L302 47' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='310' y='30' width='60' height='26' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='340' y='47' font-size='6.8' fill='var(--text)' text-anchor='middle'>Server</text><text x='190' y='92' font-size='7.3' fill='var(--text)' text-anchor='middle'>Session recorded, access granted only for the</text><text x='190' y='104' font-size='7.3' fill='var(--text)' text-anchor='middle'>time actually needed, then automatically revoked.</text><text x='16' y='123' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Elevated/admin accounts specifically \u2014 just-in-time access and session recording are</text><text x='16' y='135' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the signature features of PAM.</text></svg>"},

    { "id": "sd4-47-1", "core": "core1", "domain": "sd4", "objective": "4.7", "term": "Security orchestration, automation, and response (SOAR)", "definition": "A platform that automates repetitive security operations tasks and coordinates response actions across multiple security tools, often triggered by SIEM alerts.", "scenario": "automatically isolate a compromised endpoint and open a ticket the instant a SIEM alert crosses a certain severity threshold", "distractors": ["SIEM (detection and correlation, not automated response)", "EDR (endpoint-only)", "Log aggregation"], "tip": "AUTOMATES the RESPONSE — SIEM detects and correlates but doesn't itself take automated action, this is the step beyond that." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-47-1'><title id='dt-sd4-47-1'>Automates the RESPONSE \u2014 SIEM detects/correlates but doesn&#39;t itself take automated action, this is the step beyond that.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='36' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>SIEM alert crosses severity threshold</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>SOAR triggers automatically</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>isolates endpoint, opens ticket</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Response completed</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>no human needed to start it</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Automates the RESPONSE \u2014 SIEM detects/correlates but doesn&#39;t itself take</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>automated action, this is the step beyond that.</text></svg>"},
    { "id": "sd4-47-2", "core": "core1", "domain": "sd4", "objective": "4.7", "term": "Automated user provisioning", "definition": "The automatic creation, modification, and removal of user accounts and access rights based on defined triggers, such as HR system events.", "scenario": "automatically create a new employee's accounts and access the moment they're added to the HR system, and remove them the moment they leave", "distractors": ["Manual account creation", "Privileged access management", "Federation"], "tip": "TRIGGERED by events (like HR system changes) — removes the lag and human error of manually creating/removing accounts." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-47-2'><title id='dt-sd4-47-2'>Automatic creation, modification, and removal of accounts based on defined triggers like HR system events.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='95' y='50' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>HR system event</text><text x='95' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>new hire added</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='285' y='44' font-size='7' fill='var(--text)' text-anchor='middle' font-weight='700'>Accounts created</text><text x='285' y='58' font-size='6.4' fill='var(--muted)' text-anchor='middle'>automatically</text><text x='285' y='70' font-size='5.8' fill='var(--muted)' text-anchor='middle'>no lag, no manual step</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Automatic creation, modification, and removal of accounts based on defined triggers</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>like HR system events.</text></svg>"},
    { "id": "sd4-47-3", "core": "core1", "domain": "sd4", "objective": "4.7", "term": "CI/CD pipeline security", "definition": "The practice of embedding automated security testing and checks directly into the software build and deployment pipeline, catching issues before code reaches production.", "scenario": "automatically scan every code change for known vulnerable dependencies before it's ever deployed to production", "distractors": ["Manual code review only", "Penetration testing (periodic, not continuous)", "Change management (broader process)"], "tip": "CONTINUOUS and AUTOMATED, built into the pipeline — catches issues before production, unlike periodic manual reviews or occasional pen tests." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-47-3'><title id='dt-sd4-47-3'>Continuous, automated checks built into the pipeline \u2014 catches issues before production, unlike periodic manual review.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='36' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Code change committed</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='74' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Automated security scan</text><text x='180.0' y='87' font-size='7.5' fill='var(--text)' text-anchor='middle'>checks dependencies, catches issues</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Deploy to production</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>only if scan passes</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Continuous, automated checks built into the pipeline \u2014 catches issues</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>before production, unlike periodic manual review.</text></svg>"},
    { "id": "sd4-47-4", "core": "core1", "domain": "sd4", "objective": "4.7", "term": "Guard rails (automation)", "definition": "Predefined automated policies that constrain what actions a system or user can take, preventing unsafe configurations even during automated processes.", "scenario": "prevent an automated provisioning script from ever being able to create a publicly exposed storage bucket by mistake", "distractors": ["Application allow listing", "Configuration enforcement", "Change management approval (manual, not automated)"], "tip": "PREVENTS unsafe actions AUTOMATICALLY, even during automation itself — a safety net for automated processes, not a manual approval gate." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-47-4'><title id='dt-sd4-47-4'>Predefined automated policies that constrain what actions a system can take, even during automation itself.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Auto script tries:</text><text x='95' y='64' font-size='6' fill='var(--red)' text-anchor='middle'>public storage bucket</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--primary)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--primary)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='6.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Guard rail blocks it</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>automatically</text><text x='285' y='70' font-size='5.6' fill='var(--primary)' text-anchor='middle'>not a manual approval gate</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Predefined automated policies that constrain what actions a system can take, even</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>during automation itself.</text></svg>"},

    { "id": "sd4-48-1", "core": "core1", "domain": "sd4", "objective": "4.8", "term": "Incident response process", "definition": "The structured sequence of preparation, detection, analysis, containment, eradication, recovery, and lessons learned used to handle a security incident.", "scenario": "follow a consistent, structured process from first detecting a breach through fully recovering and documenting lessons learned", "distractors": ["Change management process", "Vulnerability management process", "Business continuity process"], "tip": "The FULL 7-phase sequence — prep through lessons learned, specifically for SECURITY incidents, not general infrastructure changes." , "diagram": "<svg viewBox='0 0 380 287' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-48-1'><title id='dt-sd4-48-1'>Incident response process \u2014 full sequence</title><rect x='20' y='14' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='33.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Preparation</text><line x1='190' y1='44' x2='190' y2='46' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 44 L190 51 L194 44' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='52' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='71.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Identification</text><line x1='190' y1='82' x2='190' y2='84' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 82 L190 89 L194 82' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='90' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='109.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Containment</text><line x1='190' y1='120' x2='190' y2='122' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 120 L190 127 L194 120' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='128' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='147.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Eradication</text><line x1='190' y1='158' x2='190' y2='160' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 158 L190 165 L194 158' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='166' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='185.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Recovery</text><line x1='190' y1='196' x2='190' y2='198' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 196 L190 203 L194 196' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='204' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='223.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Lessons learned</text><text x='16' y='277' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The full sequence for handling a security incident, always in this order.</text></svg>"},
    { "id": "sd4-48-2", "core": "core1", "domain": "sd4", "objective": "4.8", "term": "Containment", "definition": "The incident response phase focused on limiting the scope and spread of an active incident before it can cause further damage.", "scenario": "immediately isolate an infected workstation from the network to stop malware from spreading further while investigation continues", "distractors": ["Eradication", "Recovery", "Preparation"], "tip": "LIMITS the SPREAD — comes before eradication (removing the cause) in the sequence, stopping things from getting worse first.", "diagram": "<svg viewBox='0 0 220 300' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-48-2'><title id='dt-sd4-48-2'>Stops the spread before eradication even attempts to remove the cause.</title><defs><marker id='sp-ir-arrow' markerWidth='7' markerHeight='7' refX='3.5' refY='3.5' orient='auto'><path d='M0 0 L7 3.5 L0 7 Z' fill='var(--muted)'/></marker></defs><rect x='10' y='10' width='200' height='30' rx='5' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='110' y='30' font-size='8' text-anchor='middle' fill='var(--text)' font-weight='700'>Preparation</text><line x1='110' y1='40' x2='110' y2='52' stroke='var(--muted)' stroke-width='1.2' marker-end='url(#sp-ir-arrow)'/><rect x='10' y='52' width='200' height='30' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.3'/><text x='110' y='72' font-size='8' text-anchor='middle' fill='var(--text)' font-weight='700'>Identification</text><line x1='110' y1='82' x2='110' y2='94' stroke='var(--muted)' stroke-width='1.2' marker-end='url(#sp-ir-arrow)'/><rect x='10' y='94' width='200' height='30' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.8'/><text x='110' y='114' font-size='8.5' text-anchor='middle' fill='var(--text)' font-weight='700'>Containment</text><line x1='110' y1='124' x2='110' y2='136' stroke='var(--muted)' stroke-width='1.2' marker-end='url(#sp-ir-arrow)'/><rect x='10' y='136' width='200' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.3'/><text x='110' y='156' font-size='8' text-anchor='middle' fill='var(--text)' font-weight='700'>Eradication</text><line x1='110' y1='166' x2='110' y2='178' stroke='var(--muted)' stroke-width='1.2' marker-end='url(#sp-ir-arrow)'/><rect x='10' y='178' width='200' height='30' rx='5' fill='var(--violet)' fill-opacity='.16' stroke='var(--violet)' stroke-width='1.3'/><text x='110' y='198' font-size='8' text-anchor='middle' fill='var(--text)' font-weight='700'>Recovery</text><line x1='110' y1='208' x2='110' y2='220' stroke='var(--muted)' stroke-width='1.2' marker-end='url(#sp-ir-arrow)'/><rect x='10' y='220' width='200' height='30' rx='5' fill='var(--green)' fill-opacity='.14' stroke='var(--green)' stroke-width='1.3'/><text x='110' y='237' font-size='7.5' text-anchor='middle' fill='var(--text)' font-weight='700'>Lessons learned</text><text x='10' y='266' font-size='7.5' fill='var(--muted-2)'>Stops the spread before eradication</text><text x='10' y='278' font-size='7.5' fill='var(--muted-2)'>even attempts to remove the cause.</text></svg>" },
    { "id": "sd4-48-3", "core": "core1", "domain": "sd4", "objective": "4.8", "term": "Eradication", "definition": "The incident response phase focused on completely removing the cause of an incident, such as malware or an attacker's persistence mechanism, from affected systems.", "scenario": "make sure every trace of the malware and any backdoor the attacker planted is fully removed before systems are trusted again", "distractors": ["Containment", "Recovery", "Lessons learned"], "tip": "COMPLETELY REMOVES the cause — comes after containment (which just limits spread) and before recovery (restoring normal operation)." , "diagram": "<svg viewBox='0 0 380 287' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-48-3'><title id='dt-sd4-48-3'>Eradication</title><rect x='20' y='14' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='33.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Preparation</text><line x1='190' y1='44' x2='190' y2='46' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 44 L190 51 L194 44' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='52' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='71.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Identification</text><line x1='190' y1='82' x2='190' y2='84' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 82 L190 89 L194 82' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='90' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='109.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Containment</text><line x1='190' y1='120' x2='190' y2='122' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 120 L190 127 L194 120' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='128' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--red)' stroke-width='2.4'/><text x='190' y='147.0' font-size='9.5' fill='var(--red)' text-anchor='middle' font-weight='700'>Eradication</text><line x1='190' y1='158' x2='190' y2='160' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 158 L190 165 L194 158' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='166' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='185.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Recovery</text><line x1='190' y1='196' x2='190' y2='198' stroke='var(--muted)' stroke-width='1.5'/><path d='M186 196 L190 203 L194 196' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='20' y='204' width='340' height='30' rx='6' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.3'/><text x='190' y='223.0' font-size='9.5' fill='var(--muted)' text-anchor='middle' font-weight='700'>Lessons learned</text><text x='16' y='265' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Completely removes the cause \u2014 comes after containment (limits spread) and</text><text x='16' y='277' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>before recovery (restores normal operation).</text></svg>"},
    { "id": "sd4-48-4", "core": "core1", "domain": "sd4", "objective": "4.8", "term": "Root cause analysis", "definition": "A structured investigation technique used after an incident to identify the true underlying cause, rather than just the immediate symptom, so it can be permanently fixed.", "scenario": "determine the actual underlying reason a breach happened instead of just patching the one symptom that was noticed first", "distractors": ["Threat hunting", "Digital forensics", "Vulnerability scanning"], "tip": "Finds the TRUE underlying cause, not just the symptom — happens AFTER an incident, distinct from threat hunting which proactively searches BEFORE." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-48-4'><title id='dt-sd4-48-4'>Finds the TRUE underlying cause after an incident, not just the symptom noticed first.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Root cause analysis</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>AFTER an incident</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat hunting</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>BEFORE, proactive</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Finds the TRUE underlying cause after an incident, not just the symptom noticed</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>first.</text></svg>"},
    { "id": "sd4-48-5", "core": "core1", "domain": "sd4", "objective": "4.8", "term": "Threat hunting", "definition": "A proactive practice of actively searching for signs of undetected threats or attackers already present in an environment, rather than waiting for an alert.", "scenario": "proactively search the network for signs of a stealthy attacker that hasn't triggered any existing alerts yet", "distractors": ["Incident response (reactive, triggered by an alert)", "Vulnerability scanning", "Penetration testing"], "tip": "PROACTIVE, not triggered by an alert — actively searches for undetected threats already present, the opposite posture from reactive incident response." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-48-5'><title id='dt-sd4-48-5'>Actively searches for signs of undetected threats already present, rather than waiting for an alert.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Threat hunting</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>PROACTIVE, no alert needed</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Incident response</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>REACTIVE, alert-triggered</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Actively searches for signs of undetected threats already present, rather than</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>waiting for an alert.</text></svg>"},

    { "id": "sd4-49-1", "core": "core1", "domain": "sd4", "objective": "4.9", "term": "Packet capture", "definition": "A recording of raw network traffic, frame by frame, used to examine exactly what data was exchanged during an incident.", "scenario": "examine the exact contents of the network traffic exchanged during a suspected data exfiltration event", "distractors": ["NetFlow (summary only, not full content)", "Firewall log", "SIEM dashboard"], "tip": "FULL raw content, frame by frame — NetFlow only gives a SUMMARY of who talked to whom, not the actual data exchanged." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-49-1'><title id='dt-sd4-49-1'>A recording of raw network traffic, frame by frame, used to examine exactly what data was exchanged.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Packet capture</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>FULL raw content</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>NetFlow</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>summary only</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A recording of raw network traffic, frame by frame, used to examine exactly</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>what data was exchanged.</text></svg>"},
    { "id": "sd4-49-2", "core": "core1", "domain": "sd4", "objective": "4.9", "term": "Firewall log", "definition": "A record of traffic that a firewall allowed or denied, including source, destination, port, and action taken, useful for investigating network-based incidents.", "scenario": "determine exactly which external IP addresses were blocked or allowed through the perimeter firewall during an attack window", "distractors": ["Endpoint log", "Application log", "Packet capture (full content, not summarized decisions)"], "tip": "ALLOW/DENY DECISIONS with metadata — packet capture instead has the FULL CONTENT, this just records what happened, not what was inside." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-49-2'><title id='dt-sd4-49-2'>A record of traffic a firewall allowed or denied, including source, destination, port, and action taken.</title><rect x='20' y='24' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7' fill='var(--muted)' text-anchor='middle'>Firewall log entries</text><text x='190' y='44' font-size='7' fill='var(--green)' text-anchor='middle' font-weight='700'>ALLOW 203.0.113.5 \u2192 :443</text><text x='190' y='62' font-size='7' fill='var(--red)' text-anchor='middle' font-weight='700'>DENY 198.51.100.9 \u2192 :22</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>ALLOW/DENY decisions with metadata \u2014 packet capture</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>instead has the FULL content of what crossed.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A record of traffic a firewall allowed or denied, including source,</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>destination, port, and action taken.</text></svg>"},
    { "id": "sd4-49-3", "core": "core1", "domain": "sd4", "objective": "4.9", "term": "Endpoint log", "definition": "A record of activity generated by an individual device's operating system or security agent, such as process starts, logins, and file changes.", "scenario": "determine exactly which process launched and what files it touched on a specific compromised laptop", "distractors": ["Firewall log", "NetFlow", "Vulnerability scan report"], "tip": "FROM the DEVICE itself (process starts, logins, file changes) — a firewall log instead only sees what crossed the network boundary." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-49-3'><title id='dt-sd4-49-3'>A record of activity from an individual device&#39;s OS or security agent: process starts, logins, file changes.</title><rect x='20' y='24' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7' fill='var(--muted)' text-anchor='middle'>From the DEVICE itself</text><text x='190' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>process.exe started</text><text x='190' y='62' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>file.docx modified</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>A firewall log instead only sees what crossed the</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>network boundary, not what happened on-device.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A record of activity from an individual device&#39;s OS or security agent: process</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>starts, logins, file changes.</text></svg>"},
    { "id": "sd4-49-4", "core": "core1", "domain": "sd4", "objective": "4.9", "term": "Security dashboard", "definition": "A visual, often real-time summary view that aggregates key security metrics and alerts from underlying data sources for quick situational awareness.", "scenario": "get a quick, at-a-glance view of current alert volume and severity without digging through raw logs first", "distractors": ["Raw packet capture", "Firewall log", "Automated vulnerability report"], "tip": "VISUAL SUMMARY for quick awareness — aggregates from underlying raw sources like logs and captures, not a raw data source itself." , "diagram": "<svg viewBox='0 0 380 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd4-49-4'><title id='dt-sd4-49-4'>A visual, real-time summary aggregating key security metrics and alerts for quick situational awareness.</title><rect x='20' y='24' width='340' height='70' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Security dashboard \u2014 visual summary</text><text x='60' y='46' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Alerts</text><text x='60' y='68' font-size='11' fill='var(--primary)' text-anchor='middle' font-weight='700'>14</text><text x='190' y='46' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Critical</text><text x='190' y='68' font-size='11' fill='var(--primary)' text-anchor='middle' font-weight='700'>2</text><text x='320' y='46' font-size='6.4' fill='var(--muted)' text-anchor='middle'>Trend</text><text x='320' y='68' font-size='11' fill='var(--primary)' text-anchor='middle' font-weight='700'>\u2193</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A visual, real-time summary aggregating key security metrics and alerts for</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>quick situational awareness.</text></svg>"},

    { "id": "sd5-51-1", "core": "core1", "domain": "sd5", "objective": "5.1", "term": "Acceptable use policy (AUP)", "definition": "A policy that defines the rules and boundaries for how employees are permitted to use an organization's systems, networks, and data.", "scenario": "formally document what employees are and aren't allowed to do with their company laptop and internet access", "distractors": ["Business continuity plan", "Incident response policy", "Change management policy"], "tip": "RULES for how employees use company resources — an agreement about ACCEPTABLE USE, unrelated to business continuity or incident handling." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-51-1'><title id='dt-sd5-51-1'>Defines the rules and boundaries for how employees are permitted to use systems, networks, and data.</title><rect x='20' y='24' width='340' height='60' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='190' y='18' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>Acceptable Use Policy</text><text x='190' y='48' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Rules for company laptops,</text><text x='190' y='62' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>network, and data access</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>RULES for how employees use company resources \u2014</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>unrelated to business continuity or incident handling.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines the rules and boundaries for how employees are permitted to use</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>systems, networks, and data.</text></svg>"},
    { "id": "sd5-51-2", "core": "core1", "domain": "sd5", "objective": "5.1", "term": "Business continuity plan (BCP)", "definition": "A documented plan describing how an organization will continue critical business functions during and after a disruptive event.", "scenario": "make sure order processing can keep running, even in a degraded form, during a major outage", "distractors": ["Disaster recovery plan (IT systems specifically)", "Incident response plan", "Acceptable use policy"], "tip": "CRITICAL BUSINESS FUNCTIONS broadly — a disaster recovery plan is the narrower IT-SYSTEMS-specific subset of this bigger picture." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-51-2'><title id='dt-sd5-51-2'>Describes how an organization will continue critical business functions during and after a disruptive event.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>BCP</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>ALL critical business functions</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>DR plan</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>IT systems specifically</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Describes how an organization will continue critical business functions during</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>and after a disruptive event.</text></svg>"},
    { "id": "sd5-51-3", "core": "core1", "domain": "sd5", "objective": "5.1", "term": "Software development lifecycle (SDLC) policy", "definition": "A governance policy that defines security requirements and checkpoints at each stage of building and deploying software, from design through retirement.", "scenario": "require a formal security review before any new application code is approved for production release", "distractors": ["Change management policy (infrastructure changes generally)", "Acceptable use policy", "Data classification policy"], "tip": "Security checkpoints THROUGHOUT software development — design to retirement, distinct from change management which covers infra changes generally." , "diagram": "<svg viewBox='0 0 360 236' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-51-3'><title id='dt-sd5-51-3'>Defines security requirements and checkpoints at each stage of building software, from design through retirement.</title><rect x='16' y='16' width='328' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='27' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Design</text><text x='180.0' y='40' font-size='7.5' fill='var(--muted)' text-anchor='middle'>security requirements set</text><line x1='180.0' y1='48' x2='180.0' y2='52' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 50 L180.0 57 L184.0 50' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='58' width='328' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='69' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Build &amp; test</text><text x='180.0' y='82' font-size='7.5' fill='var(--muted)' text-anchor='middle'>checkpoints along the way</text><line x1='180.0' y1='90' x2='180.0' y2='94' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 92 L180.0 99 L184.0 92' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='100' width='328' height='32' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='111' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Security review</text><text x='180.0' y='124' font-size='7.5' fill='var(--text)' text-anchor='middle'>required before release</text><line x1='180.0' y1='132' x2='180.0' y2='136' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 134 L180.0 141 L184.0 134' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='142' width='328' height='32' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='153' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Deploy \u2192 retirement</text><text x='180.0' y='166' font-size='7.5' fill='var(--muted)' text-anchor='middle'>lifecycle continues</text><text x='16' y='214' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines security requirements and checkpoints at each stage of building</text><text x='16' y='226' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>software, from design through retirement.</text></svg>"},
    { "id": "sd5-51-4", "core": "core1", "domain": "sd5", "objective": "5.1", "term": "Data classification policy", "definition": "A governance policy that defines categories for organizational data, such as public, internal, confidential, and restricted, and the handling requirements for each.", "scenario": "define which handling rules apply to a document labeled confidential versus one labeled public", "distractors": ["Acceptable use policy", "Business continuity plan", "Change management policy"], "tip": "DEFINES sensitivity CATEGORIES (public/internal/confidential/restricted) — the labeling system other controls like DLP then act upon." , "diagram": "<svg viewBox='0 0 380 140' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-51-4'><title id='dt-sd5-51-4'>Defines categories for organizational data and the handling requirements for each.</title><rect x='30' y='26' width='80' height='30' rx='5' fill='var(--green-soft)' stroke='var(--green)' stroke-width='1.5'/><text x='70' y='45' font-size='6.6' fill='var(--green)' text-anchor='middle' font-weight='700'>Public</text><rect x='118' y='26' width='80' height='30' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='158' y='45' font-size='6.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Internal</text><rect x='206' y='26' width='80' height='30' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='246' y='45' font-size='6.6' fill='var(--amber)' text-anchor='middle' font-weight='700'>Confidential</text><rect x='294' y='26' width='80' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='334' y='45' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Restricted</text><text x='190' y='78' font-size='7.3' fill='var(--text)' text-anchor='middle'>DEFINES sensitivity categories \u2014 the labeling system</text><text x='190' y='90' font-size='7.3' fill='var(--text)' text-anchor='middle'>other controls like DLP then act upon.</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines categories for organizational data and the handling requirements for</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>each.</text></svg>"},
    { "id": "sd5-51-5", "core": "core1", "domain": "sd5", "objective": "5.1", "term": "Regulatory considerations", "definition": "External legal and industry requirements, such as government regulations or industry standards, that an organization's security policies must account for.", "scenario": "make sure a healthcare company's security policies account for the specific legal handling requirements of patient data", "distractors": ["Internal governance structure", "Risk appetite", "Business impact analysis"], "tip": "EXTERNAL legal/industry requirements — imposed from outside the organization, unlike risk appetite which is an INTERNAL leadership decision." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-51-5'><title id='dt-sd5-51-5'>External legal and industry requirements that security policies must account for.</title><rect x='20' y='24' width='340' height='60' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='6.8' fill='var(--muted)' text-anchor='middle'>Outside the organization</text><rect x='40' y='40' width='130' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='105' y='59' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Government law</text><rect x='210' y='40' width='130' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='275' y='59' font-size='6.6' fill='var(--red)' text-anchor='middle' font-weight='700'>Industry standard</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>EXTERNAL requirements \u2014 unlike risk appetite, which is</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>an INTERNAL leadership decision.</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>External legal and industry requirements that security policies must account</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>for.</text></svg>"},

    { "id": "sd5-52-1", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Risk register", "definition": "A documented, maintained log of identified risks, including their likelihood, impact, and assigned owner, used to track and manage risk over time.", "scenario": "maintain a single, ongoing record of every identified risk, its severity, and who is responsible for addressing it", "distractors": ["Business impact analysis", "Vulnerability scan report", "Audit report"], "tip": "A LIVING LOG of risks with likelihood/impact/owner — ongoing tracking, not a one-time assessment snapshot like a BIA." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-1'><title id='dt-sd5-52-1'>A documented, maintained log of identified risks, including likelihood, impact, and assigned owner.</title><rect x='20' y='20' width='340' height='24' rx='4' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='80' y='36' font-size='6.6' fill='var(--muted)' text-anchor='start' font-weight='700'>Risk</text><text x='190' y='36' font-size='6.6' fill='var(--muted)' text-anchor='middle' font-weight='700'>Likelihood</text><text x='280' y='36' font-size='6.6' fill='var(--muted)' text-anchor='middle' font-weight='700'>Owner</text><rect x='20' y='50' width='340' height='20' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='80' y='64' font-size='6.4' fill='var(--primary)' text-anchor='start' font-weight='700'>Vendor breach</text><text x='190' y='64' font-size='6.4' fill='var(--primary)' text-anchor='middle'>Medium</text><text x='280' y='64' font-size='6.4' fill='var(--primary)' text-anchor='middle'>J. Lee</text><rect x='20' y='74' width='340' height='20' rx='3' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='80' y='88' font-size='6.4' fill='var(--primary)' text-anchor='start' font-weight='700'>Unpatched server</text><text x='190' y='88' font-size='6.4' fill='var(--primary)' text-anchor='middle'>High</text><text x='280' y='88' font-size='6.4' fill='var(--primary)' text-anchor='middle'>IT team</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>A LIVING LOG tracked over time \u2014 not a one-time</text><text x='190' y='124' font-size='7.3' fill='var(--text)' text-anchor='middle'>snapshot assessment like a BIA.</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A documented, maintained log of identified risks, including likelihood, impact,</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>and assigned owner.</text></svg>"},
    { "id": "sd5-52-2", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Risk appetite", "definition": "The overall level and type of risk an organization is willing to accept in pursuit of its objectives, set by leadership and used to guide risk decisions.", "scenario": "decide whether a moderately risky but cost-saving new vendor relationship falls within what leadership considers acceptable", "distractors": ["Risk tolerance (a specific, narrower threshold)", "Risk register", "Exposure factor"], "tip": "The OVERALL level leadership accepts — risk tolerance is a narrower, more SPECIFIC threshold within that broader appetite." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-2'><title id='dt-sd5-52-2'>The overall level and type of risk an organization is willing to accept, set by leadership.</title><rect x='20' y='30' width='340' height='30' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='190' y='50' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Risk APPETITE \u2014 overall level leadership accepts</text><rect x='110' y='68' width='160' height='24' rx='12' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='190' y='84' font-size='6.6' fill='var(--blue)' text-anchor='middle' font-weight='700'>Risk TOLERANCE (narrower)</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>Tolerance is a specific, narrower threshold WITHIN</text><text x='190' y='124' font-size='7.3' fill='var(--text)' text-anchor='middle'>that broader appetite set by leadership.</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The overall level and type of risk an organization is willing to accept, set by</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>leadership.</text></svg>"},
    { "id": "sd5-52-3", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Qualitative risk analysis", "definition": "A risk assessment approach that rates risks using descriptive categories, such as low, medium, or high, rather than precise numeric values.", "scenario": "quickly rank a list of risks as low, medium, or high without needing exact dollar-value calculations", "distractors": ["Quantitative risk analysis", "Business impact analysis", "Risk register"], "tip": "DESCRIPTIVE categories (low/medium/high) — quantitative analysis instead uses actual NUMBERS and dollar values." , "diagram": "<svg viewBox='0 0 390 135' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-3'><title id='dt-sd5-52-3'>Descriptive categories (low/medium/high) \u2014 quantitative analysis instead uses actual numbers and dollar values.</title><rect x='20' y='24' width='165' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='102' y='44' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Qualitative</text><rect x='35' y='54' width='40' height='16' rx='3' fill='var(--green)' fill-opacity='0.3' stroke='var(--green)' stroke-width='1.5'/><text x='55' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>Low</text><rect x='80' y='54' width='50' height='16' rx='3' fill='var(--amber)' fill-opacity='0.3' stroke='var(--amber)' stroke-width='1.5'/><text x='105' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>Medium</text><rect x='135' y='54' width='45' height='16' rx='3' fill='var(--red)' fill-opacity='0.3' stroke='var(--red)' stroke-width='1.5'/><text x='157' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>High</text><text x='102' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>descriptive categories</text><rect x='195' y='24' width='165' height='66' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='277' y='44' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Quantitative</text><text x='277' y='62' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700' font-family='monospace'>ALE = SLE \u00d7 ARO</text><text x='277' y='82' font-size='6.3' fill='var(--muted)' text-anchor='middle'>actual numbers, dollar values</text><text x='16' y='113' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Descriptive categories (low/medium/high) \u2014 quantitative analysis instead uses</text><text x='16' y='125' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>actual numbers and dollar values.</text></svg>"},
    { "id": "sd5-52-4", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Quantitative risk analysis", "definition": "A risk assessment approach that assigns specific numeric and monetary values to risk, such as calculating annualized loss expectancy.", "scenario": "calculate the specific expected dollar-value annual loss from a particular risk to justify a security budget request", "distractors": ["Qualitative risk analysis", "Risk appetite", "Risk register"], "tip": "NUMERIC and MONETARY — annualized loss expectancy calculations live here, unlike qualitative analysis's simple low/medium/high labels." , "diagram": "<svg viewBox='0 0 390 135' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-4'><title id='dt-sd5-52-4'>Numeric and monetary \u2014 annualized loss expectancy calculations live here, unlike qualitative&#39;s simple low/medium/high labels.</title><rect x='20' y='24' width='165' height='66' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='102' y='44' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Qualitative</text><rect x='35' y='54' width='40' height='16' rx='3' fill='var(--green)' fill-opacity='0.3' stroke='var(--green)' stroke-width='1.5'/><text x='55' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>Low</text><rect x='80' y='54' width='50' height='16' rx='3' fill='var(--amber)' fill-opacity='0.3' stroke='var(--amber)' stroke-width='1.5'/><text x='105' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>Medium</text><rect x='135' y='54' width='45' height='16' rx='3' fill='var(--red)' fill-opacity='0.3' stroke='var(--red)' stroke-width='1.5'/><text x='157' y='65' font-size='6.3' fill='var(--text)' text-anchor='middle'>High</text><text x='102' y='82' font-size='6.5' fill='var(--muted)' text-anchor='middle'>descriptive categories</text><rect x='195' y='24' width='165' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='277' y='44' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Quantitative</text><text x='277' y='62' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700' font-family='monospace'>ALE = SLE \u00d7 ARO</text><text x='277' y='82' font-size='6.3' fill='var(--muted)' text-anchor='middle'>actual numbers, dollar values</text><text x='16' y='113' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Numeric and monetary \u2014 annualized loss expectancy calculations live here, unlike</text><text x='16' y='125' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>qualitative&#39;s simple low/medium/high labels.</text></svg>"},
    { "id": "sd5-52-5", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Annualized loss expectancy (ALE)", "definition": "A calculated value representing the expected yearly financial loss from a specific risk, found by multiplying the single loss expectancy by the annualized rate of occurrence.", "scenario": "calculate the expected yearly dollar cost of a specific risk to help justify a proposed security control's budget", "distractors": ["Single loss expectancy (one-time only)", "Risk appetite", "Exposure factor (a percentage, not a dollar total)"], "tip": "YEARLY expected loss — multiplies single loss expectancy (ONE occurrence) by how often it's expected to happen per year." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-5'><title id='dt-sd5-52-5'>Yearly expected loss \u2014 multiplies single loss expectancy (one occurrence) by how often it&#39;s expected to happen per year.</title><rect x='20' y='30' width='100' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='70' y='47' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>SLE</text><text x='70' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>single loss ($)</text><text x='135' y='50' font-size='12' fill='var(--muted)' text-anchor='middle'>\u00d7</text><rect x='150' y='30' width='100' height='34' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='200' y='47' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>ARO</text><text x='200' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>times per year</text><text x='265' y='50' font-size='12' fill='var(--muted)' text-anchor='middle'>=</text><rect x='280' y='30' width='100' height='34' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='330' y='47' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>ALE</text><text x='330' y='60' font-size='6.3' fill='var(--text)' text-anchor='middle'>yearly expected loss</text><text x='190' y='96' font-size='7.3' fill='var(--text)' text-anchor='middle'>Multiplies the cost of ONE occurrence by how often</text><text x='190' y='108' font-size='7.3' fill='var(--text)' text-anchor='middle'>it&#39;s expected to happen per year.</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Yearly expected loss \u2014 multiplies single loss expectancy (one occurrence) by how</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>often it&#39;s expected to happen per year.</text></svg>"},
    { "id": "sd5-52-6", "core": "core1", "domain": "sd5", "objective": "5.2", "term": "Risk transfer", "definition": "A risk management strategy that shifts the financial impact of a risk to a third party, most commonly through purchasing insurance.", "scenario": "protect the company financially against the cost of a major data breach by purchasing a cyber insurance policy", "distractors": ["Risk acceptance", "Risk avoidance", "Risk mitigation"], "tip": "Shifts the FINANCIAL impact to a THIRD PARTY — insurance is the classic example, distinct from mitigation or acceptance." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-52-6'><title id='dt-sd5-52-6'>Shifts the financial impact of a risk to a third party, most commonly through purchasing insurance.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>Data breach risk</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>financial impact</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><text x='190' y='44' font-size='6.2' fill='var(--muted)' text-anchor='middle'>transferred to</text><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Cyber insurance</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>third party</text><text x='285' y='70' font-size='6.4' fill='var(--primary)' text-anchor='middle'>absorbs the cost</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Shifts the financial impact of a risk to a third party, most commonly through</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>purchasing insurance.</text></svg>"},

    { "id": "sd5-53-1", "core": "core1", "domain": "sd5", "objective": "5.3", "term": "Vendor risk assessment", "definition": "The process of evaluating a third-party vendor's security posture and practices before and during a business relationship to understand the risk they introduce.", "scenario": "evaluate a new cloud vendor's security certifications and practices before signing a contract", "distractors": ["Penetration test", "Business impact analysis", "Internal audit"], "tip": "Evaluates a THIRD-PARTY vendor specifically — before and during the relationship, not an assessment of your own internal systems." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-53-1'><title id='dt-sd5-53-1'>Evaluating a third-party vendor&#39;s security posture before and during a business relationship.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Your org</text><text x='95' y='64' font-size='6' fill='var(--muted)' text-anchor='middle'>evaluates before signing</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Cloud vendor</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle'>security certs</text><text x='285' y='70' font-size='6.4' fill='var(--primary)' text-anchor='middle'>&amp; practices</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Evaluating a third-party vendor&#39;s security posture before and during a business</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>relationship.</text></svg>"},
    { "id": "sd5-53-2", "core": "core1", "domain": "sd5", "objective": "5.3", "term": "Service level agreement (SLA)", "definition": "A formal agreement between a provider and a customer that defines expected service levels, such as uptime and response times, along with remedies if they aren't met.", "scenario": "formally commit a vendor to 99.9% uptime with defined penalties if they fall short", "distractors": ["Memorandum of understanding (MOU)", "Non-disclosure agreement (NDA)", "Business partnership agreement (BPA)"], "tip": "Defines SERVICE LEVELS with REMEDIES if unmet — an MOU is a softer, less formally binding mutual understanding without those enforcement teeth." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-53-2'><title id='dt-sd5-53-2'>Defines expected service levels, such as uptime and response times, along with remedies if not met.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>SLA</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>service levels + REMEDIES</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>MOU</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>softer, no enforcement teeth</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines expected service levels, such as uptime and response times, along with</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>remedies if not met.</text></svg>"},
    { "id": "sd5-53-3", "core": "core1", "domain": "sd5", "objective": "5.3", "term": "Non-disclosure agreement (NDA)", "definition": "A legal agreement that obligates a party to keep specified information confidential and not disclose it to unauthorized parties.", "scenario": "legally bind a contractor to keep proprietary source code confidential before giving them access to it", "distractors": ["Service level agreement", "Memorandum of understanding", "Rules of engagement"], "tip": "CONFIDENTIALITY obligation specifically — unrelated to service performance (SLA) or engagement scope (rules of engagement)." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-53-3'><title id='dt-sd5-53-3'>A legal agreement obligating a party to keep specified information confidential.</title><rect x='30' y='30' width='140' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='100' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Contractor</text><text x='100' y='64' font-size='6' fill='var(--muted)' text-anchor='middle'>gets source code access</text><rect x='210' y='30' width='140' height='50' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='280' y='50' font-size='7.5' fill='var(--primary)' text-anchor='middle' font-weight='700'>NDA signed</text><text x='280' y='64' font-size='6.2' fill='var(--primary)' text-anchor='middle'>legally confidential</text><text x='190' y='100' font-size='7.3' fill='var(--text)' text-anchor='middle'>CONFIDENTIALITY obligation specifically \u2014 unrelated to</text><text x='190' y='112' font-size='7.3' fill='var(--text)' text-anchor='middle'>service performance (SLA) or scope (rules of engagement).</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A legal agreement obligating a party to keep specified information confidential.</text></svg>"},
    { "id": "sd5-53-4", "core": "core1", "domain": "sd5", "objective": "5.3", "term": "Rules of engagement", "definition": "A formal document defining the scope, boundaries, timing, and permitted techniques for an authorized security assessment such as a penetration test.", "scenario": "define exactly which systems a hired penetration tester is and isn't allowed to attack, and during what hours", "distractors": ["Non-disclosure agreement", "Service level agreement", "Vendor risk assessment"], "tip": "SCOPE and BOUNDARIES for an authorized assessment — defines exactly what a pen tester IS and ISN'T allowed to do." , "diagram": "<svg viewBox='0 0 380 160' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-53-4'><title id='dt-sd5-53-4'>Defines the scope, boundaries, timing, and permitted techniques for an authorized security assessment.</title><rect x='20' y='24' width='340' height='70' rx='8' fill='var(--surface-2)' stroke='var(--border)' stroke-width='1.5'/><text x='190' y='18' font-size='7' fill='var(--muted)' text-anchor='middle'>Pen test authorization document</text><rect x='40' y='38' width='140' height='24' rx='4' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='110' y='54' font-size='6.4' fill='var(--primary)' text-anchor='middle' font-weight='700'>IN scope: web app</text><rect x='200' y='38' width='140' height='24' rx='4' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='270' y='54' font-size='6.4' fill='var(--red)' text-anchor='middle' font-weight='700'>OUT: payroll system</text><text x='190' y='74' font-size='6.4' fill='var(--muted)' text-anchor='middle'>hours: 10pm\u20132am only</text><text x='16' y='138' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Defines the scope, boundaries, timing, and permitted techniques for an</text><text x='16' y='150' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>authorized security assessment.</text></svg>"},

    { "id": "sd5-54-1", "core": "core1", "domain": "sd5", "objective": "5.4", "term": "Compliance reporting", "definition": "The process of documenting and communicating an organization's adherence to applicable regulatory, legal, and internal security requirements to relevant stakeholders.", "scenario": "formally demonstrate to a regulator that required security controls have actually been implemented", "distractors": ["Risk register", "Audit (the assessment activity itself)", "Business impact analysis"], "tip": "DOCUMENTS and COMMUNICATES adherence — an audit is the underlying ASSESSMENT activity, this is the reporting output that follows it." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-54-1'><title id='dt-sd5-54-1'>Documenting and communicating adherence to regulatory, legal, and internal requirements.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Audit</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>the assessment activity</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Compliance report</text><text x='285' y='58' font-size='6.2' fill='var(--primary)' text-anchor='middle'>documents adherence</text><text x='285' y='70' font-size='6.2' fill='var(--primary)' text-anchor='middle'>to regulators</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Documenting and communicating adherence to regulatory, legal, and internal</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>requirements.</text></svg>"},
    { "id": "sd5-54-2", "core": "core1", "domain": "sd5", "objective": "5.4", "term": "Right to be forgotten", "definition": "A privacy right allowing individuals to request that an organization delete their personal data under certain conditions, notably established under regulations like GDPR.", "scenario": "process a former customer's formal request to have their personal data permanently deleted from company systems", "distractors": ["Data classification", "Data sovereignty", "Data minimization (a related but distinct principle)"], "tip": "Individuals can REQUEST DELETION — a specific GDPR-era privacy right, distinct from data minimization's broader principle of collecting less to begin with." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-54-2'><title id='dt-sd5-54-2'>A privacy right allowing individuals to request deletion of their personal data, notably under GDPR.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='95' y='50' font-size='7.3' fill='var(--text)' text-anchor='middle' font-weight='700'>Former customer</text><text x='95' y='64' font-size='6.2' fill='var(--muted)' text-anchor='middle'>requests deletion</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7.3' fill='var(--primary)' text-anchor='middle' font-weight='700'>Personal data</text><text x='285' y='58' font-size='6.4' fill='var(--primary)' text-anchor='middle' font-weight='700'>PERMANENTLY</text><text x='285' y='70' font-size='6.2' fill='var(--primary)' text-anchor='middle'>deleted (GDPR)</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A privacy right allowing individuals to request deletion of their personal data,</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>notably under GDPR.</text></svg>"},
    { "id": "sd5-54-3", "core": "core1", "domain": "sd5", "objective": "5.4", "term": "Data controller vs data processor", "definition": "Under privacy regulations, a data controller determines the purposes and means of processing personal data, while a data processor processes that data on the controller's behalf.", "scenario": "determine which party is legally responsible for deciding how customer data may be used when a company outsources data processing to a vendor", "distractors": ["Data owner vs data custodian (an internal governance pairing)", "Data subject vs data controller", "Data steward vs data controller"], "tip": "DETERMINES purpose (controller) vs. ACTS on instruction (processor) — a privacy-regulation pairing, distinct from internal roles like owner/custodian." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-54-3'><title id='dt-sd5-54-3'>A controller determines the purposes and means of processing personal data; a processor acts on its behalf.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Controller</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>DETERMINES purpose/means</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Processor</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>ACTS on instruction</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A controller determines the purposes and means of processing personal data; a</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>processor acts on its behalf.</text></svg>"},
    { "id": "sd5-54-4", "core": "core1", "domain": "sd5", "objective": "5.4", "term": "Consequences of non-compliance", "definition": "The fines, legal action, loss of certification, or reputational damage an organization may face for failing to meet applicable regulatory or contractual security requirements.", "scenario": "explain what a company risks financially and legally if it fails a required regulatory security audit", "distractors": ["Risk transfer", "Business impact analysis", "Vendor risk assessment"], "tip": "FINES, legal action, reputational damage — the REAL-WORLD stakes that make compliance requirements worth taking seriously in the first place." , "diagram": "<svg viewBox='0 0 380 140' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-54-4'><title id='dt-sd5-54-4'>Fines, legal action, loss of certification, or reputational damage from failing compliance requirements.</title><rect x='30' y='26' width='80' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='70' y='45' font-size='6' fill='var(--red)' text-anchor='middle' font-weight='700'>Fines</text><rect x='118' y='26' width='80' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='158' y='45' font-size='6' fill='var(--red)' text-anchor='middle' font-weight='700'>Legal action</text><rect x='206' y='26' width='80' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='246' y='45' font-size='6' fill='var(--red)' text-anchor='middle' font-weight='700'>Lost certification</text><rect x='294' y='26' width='80' height='30' rx='5' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5'/><text x='334' y='45' font-size='6' fill='var(--red)' text-anchor='middle' font-weight='700'>Reputational damage</text><text x='190' y='78' font-size='7.3' fill='var(--text)' text-anchor='middle'>The REAL-WORLD stakes that make compliance</text><text x='190' y='90' font-size='7.3' fill='var(--text)' text-anchor='middle'>requirements worth taking seriously.</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Fines, legal action, loss of certification, or reputational damage from failing</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>compliance requirements.</text></svg>"},

    { "id": "sd5-55-1", "core": "core1", "domain": "sd5", "objective": "5.5", "term": "Internal audit", "definition": "A security or compliance assessment conducted by an organization's own staff to evaluate adherence to internal policies and controls.", "scenario": "have the company's own compliance team review whether departments are following required security procedures", "distractors": ["External audit", "Penetration test", "Vendor risk assessment"], "tip": "Own STAFF conducts it — an external audit instead uses an INDEPENDENT third party, often for regulatory objectivity requirements." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-55-1'><title id='dt-sd5-55-1'>A security or compliance assessment conducted by an organization&#39;s own staff.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Internal audit</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>OWN staff conducts it</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--blue-soft)' stroke='var(--blue)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>External audit</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>INDEPENDENT third party</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A security or compliance assessment conducted by an organization&#39;s own staff.</text></svg>"},
    { "id": "sd5-55-2", "core": "core1", "domain": "sd5", "objective": "5.5", "term": "External audit", "definition": "A security or compliance assessment conducted by an independent third party, often required by regulation or contract, to objectively verify controls.", "scenario": "get an independent third party to formally verify the company's controls for a required regulatory certification", "distractors": ["Internal audit", "Vulnerability scan", "Self-assessment"], "tip": "INDEPENDENT third party — provides objectivity an internal audit or self-assessment structurally can't, often required by regulation." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-55-2'><title id='dt-sd5-55-2'>Conducted by an independent third party, often required by regulation, to objectively verify controls.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>External audit</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>INDEPENDENT, objective</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Internal audit</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>own staff, less objective</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Conducted by an independent third party, often required by regulation, to</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>objectively verify controls.</text></svg>"},
    { "id": "sd5-55-3", "core": "core1", "domain": "sd5", "objective": "5.5", "term": "Known environment penetration test", "definition": "A penetration test in which the testers are given full knowledge of the target's systems, architecture, and source code in advance.", "scenario": "give the hired testers full network diagrams and source code access to maximize thorough coverage in a limited test window", "distractors": ["Unknown environment penetration test", "Partially known environment penetration test", "Vulnerability scan"], "tip": "FULL knowledge given in advance (architecture, source code) — tests thoroughness rather than realism, the opposite of an unknown-environment test." , "diagram": "<svg viewBox='0 0 390 135' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-55-3'><title id='dt-sd5-55-3'>Full knowledge given in advance (architecture, source code) \u2014 tests thoroughness, the opposite of an unknown-environment test.</title><rect x='20' y='24' width='165' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='102' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Known environment</text><text x='102' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>full knowledge given</text><text x='102' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>in advance \u2014 tests</text><text x='102' y='84' font-size='6.5' fill='var(--muted)' text-anchor='middle'>thoroughness</text><rect x='195' y='24' width='165' height='66' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='277' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Unknown environment</text><text x='277' y='60' font-size='6.3' fill='var(--muted)' text-anchor='middle'>no advance knowledge \u2014</text><text x='277' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>simulates a real</text><text x='277' y='84' font-size='6.3' fill='var(--muted)' text-anchor='middle'>external attacker</text><text x='16' y='113' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Full knowledge given in advance (architecture, source code) \u2014 tests thoroughness,</text><text x='16' y='125' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>the opposite of an unknown-environment test.</text></svg>"},
    { "id": "sd5-55-4", "core": "core1", "domain": "sd5", "objective": "5.5", "term": "Unknown environment penetration test", "definition": "A penetration test in which the testers are given no advance knowledge of the target, simulating a real external attacker's perspective.", "scenario": "simulate exactly what an outside attacker with zero inside knowledge could actually accomplish against the company", "distractors": ["Known environment penetration test", "Partially known environment penetration test", "Vulnerability scan"], "tip": "NO advance knowledge — simulates a real external attacker's actual starting position, the opposite approach from a known-environment test." , "diagram": "<svg viewBox='0 0 390 135' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-55-4'><title id='dt-sd5-55-4'>No advance knowledge \u2014 simulates a real external attacker&#39;s actual starting position, the opposite of a known-environment test.</title><rect x='20' y='24' width='165' height='66' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='102' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Known environment</text><text x='102' y='60' font-size='6.5' fill='var(--muted)' text-anchor='middle'>full knowledge given</text><text x='102' y='72' font-size='6.5' fill='var(--muted)' text-anchor='middle'>in advance \u2014 tests</text><text x='102' y='84' font-size='6.5' fill='var(--muted)' text-anchor='middle'>thoroughness</text><rect x='195' y='24' width='165' height='66' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='277' y='44' font-size='8' fill='var(--text)' text-anchor='middle' font-weight='700'>Unknown environment</text><text x='277' y='60' font-size='6.3' fill='var(--muted)' text-anchor='middle'>no advance knowledge \u2014</text><text x='277' y='72' font-size='6.3' fill='var(--muted)' text-anchor='middle'>simulates a real</text><text x='277' y='84' font-size='6.3' fill='var(--muted)' text-anchor='middle'>external attacker</text><text x='16' y='113' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>No advance knowledge \u2014 simulates a real external attacker&#39;s actual starting</text><text x='16' y='125' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>position, the opposite of a known-environment test.</text></svg>"},
    { "id": "sd5-55-5", "core": "core1", "domain": "sd5", "objective": "5.5", "term": "Reconnaissance", "definition": "The information-gathering phase of a penetration test or attack, collecting publicly available or observable information about a target before attempting exploitation.", "scenario": "gather publicly available information about a target company's employees and technology before attempting any actual attack", "distractors": ["Exploitation phase", "Post-exploitation phase", "Reporting phase"], "tip": "INFORMATION-GATHERING FIRST — happens before any actual exploitation attempt, the initial phase of both real attacks and authorized pen tests." , "diagram": "<svg viewBox='0 0 360 206' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-55-5'><title id='dt-sd5-55-5'>The information-gathering phase before any exploitation attempt, in both real attacks and authorized pen tests.</title><rect x='16' y='16' width='328' height='34' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='180.0' y='28' font-size='9' fill='var(--text)' text-anchor='middle' font-weight='700'>Reconnaissance</text><text x='180.0' y='41' font-size='7.5' fill='var(--text)' text-anchor='middle'>gather public info FIRST</text><line x1='180.0' y1='50' x2='180.0' y2='56' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 54 L180.0 61 L184.0 54' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='62' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='74' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Exploitation</text><text x='180.0' y='87' font-size='7.5' fill='var(--muted)' text-anchor='middle'>attempt actual attack</text><line x1='180.0' y1='96' x2='180.0' y2='102' stroke='var(--muted)' stroke-width='1.5'/><path d='M176.0 100 L180.0 107 L184.0 100' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='16' y='108' width='328' height='34' rx='6' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='180.0' y='120' font-size='9' fill='var(--muted)' text-anchor='middle' font-weight='700'>Post-exploitation</text><text x='180.0' y='133' font-size='7.5' fill='var(--muted)' text-anchor='middle'>and reporting</text><text x='16' y='184' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>The information-gathering phase before any exploitation attempt, in both</text><text x='16' y='196' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>real attacks and authorized pen tests.</text></svg>"},

    { "id": "sd5-56-1", "core": "core1", "domain": "sd5", "objective": "5.6", "term": "Phishing simulation campaign", "definition": "A controlled, internal exercise that sends simulated phishing emails to employees to measure and improve their ability to recognize real phishing attempts.", "scenario": "measure how many employees would click a fake but realistic phishing email, and use the results to target follow-up training", "distractors": ["Penetration test", "Vulnerability scan", "Threat hunting"], "tip": "Tests EMPLOYEES specifically, not systems — measures human susceptibility to phishing, a people-focused exercise rather than a technical one." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-56-1'><title id='dt-sd5-56-1'>A controlled exercise sending simulated phishing emails to measure and improve employee recognition.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='2'/><text x='95' y='50' font-size='7.3' fill='var(--amber)' text-anchor='middle' font-weight='700'>Fake phishing email</text><text x='95' y='64' font-size='6.2' fill='var(--amber)' text-anchor='middle'>sent internally</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>Measures WHO</text><text x='285' y='58' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>clicks it</text><text x='285' y='70' font-size='5.8' fill='var(--primary)' text-anchor='middle'>targets follow-up training</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>A controlled exercise sending simulated phishing emails to measure and improve</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>employee recognition.</text></svg>"},
    { "id": "sd5-56-2", "core": "core1", "domain": "sd5", "objective": "5.6", "term": "Security awareness training", "definition": "Ongoing education provided to employees to help them recognize and respond appropriately to security threats such as phishing, social engineering, and unsafe practices.", "scenario": "teach all employees company-wide how to recognize a suspicious email before it becomes a real incident", "distractors": ["Phishing simulation (the testing exercise itself)", "Incident response training (technical staff specific)", "Onboarding (broader, non-security-specific)"], "tip": "ONGOING EDUCATION — phishing simulation is the TESTING exercise that measures how well this training actually worked." , "diagram": "<svg viewBox='0 0 380 175' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-56-2'><title id='dt-sd5-56-2'>Ongoing education to help employees recognize and respond to phishing, social engineering, and unsafe practices.</title><rect x='16.0' y='30' width='169.0' height='60' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.5'/><text x='100.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Training</text><text x='100.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>ONGOING education</text><rect x='195.0' y='30' width='169.0' height='60' rx='5' fill='var(--amber-soft)' stroke='var(--amber)' stroke-width='1.5'/><text x='279.5' y='56.0' font-size='8.5' fill='var(--text)' text-anchor='middle' font-weight='700'>Phishing sim</text><text x='279.5' y='70.0' font-size='7.5' fill='var(--muted)' text-anchor='middle'>the TESTING exercise</text><text x='16' y='153' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Ongoing education to help employees recognize and respond to phishing, social</text><text x='16' y='165' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>engineering, and unsafe practices.</text></svg>"},
    { "id": "sd5-56-3", "core": "core1", "domain": "sd5", "objective": "5.6", "term": "Anomalous behavior recognition", "definition": "Training users to notice and report unusual account or system behavior, such as unexpected logins or unfamiliar processes, as an early warning sign of compromise.", "scenario": "teach employees to notice and report a login notification from a location they've never visited", "distractors": ["Phishing recognition (a narrower, specific skill)", "Incident response (technical response, not user recognition)", "Threat hunting"], "tip": "USER-facing pattern recognition — noticing unusual account activity themselves, distinct from IT's technical threat hunting doing the same from the tooling side." , "diagram": "<svg viewBox='0 0 400 150' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-56-3'><title id='dt-sd5-56-3'>Training users to notice and report unusual account or system behavior as an early warning of compromise.</title><rect x='20' y='30' width='150' height='50' rx='6' fill='var(--red-soft)' stroke='var(--red)' stroke-width='1.5' stroke-dasharray='2 2'/><text x='95' y='50' font-size='7.3' fill='var(--red)' text-anchor='middle' font-weight='700'>\u26a0 Login from</text><text x='95' y='64' font-size='6.2' fill='var(--red)' text-anchor='middle'>unfamiliar country</text><line x1='172' y1='55' x2='204' y2='55' stroke='var(--muted)' stroke-width='1.5'/><path d='M202 51 L209 55 L202 59' fill='none' stroke='var(--muted)' stroke-width='1.5'/><rect x='210' y='24' width='150' height='62' rx='6' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='2'/><text x='285' y='44' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>User notices &amp;</text><text x='285' y='58' font-size='7' fill='var(--primary)' text-anchor='middle' font-weight='700'>REPORTS it</text><text x='285' y='70' font-size='6' fill='var(--primary)' text-anchor='middle'>early warning sign</text><text x='16' y='128' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Training users to notice and report unusual account or system behavior as an early</text><text x='16' y='140' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>warning of compromise.</text></svg>"},
    { "id": "sd5-56-4", "core": "core1", "domain": "sd5", "objective": "5.6", "term": "Social engineering recognition", "definition": "Training that helps users recognize manipulation tactics beyond email phishing, such as pretexting, tailgating, and vishing, that attackers use to bypass technical controls.", "scenario": "teach employees to question a caller pretending to be IT support who asks for their password over the phone", "distractors": ["Phishing simulation (email-specific)", "Anomalous behavior recognition (system behavior, not social manipulation)", "Incident response training"], "tip": "BEYOND email — pretexting, tailgating, vishing too; phishing simulation only tests the email-specific subset of this broader skill." , "diagram": "<svg viewBox='0 0 380 140' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-56-4'><title id='dt-sd5-56-4'>Helps users recognize manipulation tactics beyond email phishing, like pretexting, tailgating, and vishing.</title><rect x='30' y='26' width='80' height='30' rx='5' fill='var(--surface-3)' stroke='var(--border)' stroke-width='1.3'/><text x='70' y='45' font-size='5.8' fill='var(--muted)' text-anchor='middle' font-weight='700'>Phishing (email)</text><rect x='118' y='26' width='80' height='30' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='158' y='45' font-size='5.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Pretexting</text><rect x='206' y='26' width='80' height='30' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='246' y='45' font-size='5.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Tailgating</text><rect x='294' y='26' width='80' height='30' rx='5' fill='var(--primary-soft)' stroke='var(--primary)' stroke-width='1.8'/><text x='334' y='45' font-size='5.8' fill='var(--primary)' text-anchor='middle' font-weight='700'>Vishing (phone)</text><text x='190' y='78' font-size='7.3' fill='var(--text)' text-anchor='middle'>BEYOND email \u2014 phishing sim only tests the email-</text><text x='190' y='90' font-size='7.3' fill='var(--text)' text-anchor='middle'>specific subset of this broader skill.</text><text x='16' y='118' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Helps users recognize manipulation tactics beyond email phishing, like</text><text x='16' y='130' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>pretexting, tailgating, and vishing.</text></svg>"},
    { "id": "sd5-56-5", "core": "core1", "domain": "sd5", "objective": "5.6", "term": "Security awareness reporting and monitoring", "definition": "Tracking metrics from security awareness activities, such as phishing simulation click rates over time, to measure program effectiveness and target further training.", "scenario": "measure whether phishing click rates are improving over successive training cycles", "distractors": ["Compliance reporting (regulatory focus)", "Vulnerability reporting", "Incident response reporting"], "tip": "TRACKS PROGRAM EFFECTIVENESS over time (like click rates) — measures whether the training itself is working, not a regulatory compliance requirement." , "diagram": "<svg viewBox='0 0 380 185' xmlns='http://www.w3.org/2000/svg' role='img' aria-labelledby='dt-sd5-56-5'><title id='dt-sd5-56-5'>Tracking metrics from awareness activities, like phishing click rates, to measure program effectiveness.</title><line x1='30' y1='100' x2='350' y2='100' stroke='var(--border)' stroke-width='1.5'/><path d='M30 90 L110 78 L190 62 L270 48 L350 30' fill='none' stroke='var(--red)' stroke-width='1.5'/><circle cx='30' cy='90' r='3' fill='var(--red)'/><circle cx='110' cy='78' r='3' fill='var(--red)'/><circle cx='190' cy='62' r='3' fill='var(--red)'/><circle cx='270' cy='48' r='3' fill='var(--red)'/><circle cx='350' cy='30' r='3' fill='var(--red)'/><text x='30' y='24' font-size='6.4' fill='var(--red)' text-anchor='start' font-weight='700'>click rate improving \u2192</text><text x='190' y='122' font-size='7.3' fill='var(--text)' text-anchor='middle'>TRACKS PROGRAM EFFECTIVENESS over time \u2014 measures</text><text x='190' y='134' font-size='7.3' fill='var(--text)' text-anchor='middle'>whether training is working, not regulatory compliance.</text><text x='16' y='163' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>Tracking metrics from awareness activities, like phishing click rates, to</text><text x='16' y='175' font-size='8.5' fill='var(--muted-2)' text-anchor='start'>measure program effectiveness.</text></svg>"}
